// Soft particle shapes, shared by every falling / drifting / twinkling thing on the island (2026-11-20,
// user: "even particles are squares?"): no plane quads, octahedra or rotated squares any more.
//   petalGeometry(w, l)   a rounded, slightly cupped petal with a little notch at its tip (a blossom petal)
//   leafGeometry(w, l)    a pointed leaf with a stalk, folded along its midrib
//   softDotTexture()      a round glow with a soft falloff (motes, fireflies, stars)
//   sparkleTexture()      a 4-point star with a soft bright core (sparkles, glints)
//   sparkleSprite(color, size, opts)  a sprite drawing that star (additive, never writes depth)
// Geometry is small (petal 18 tris, leaf 16) and made once per call site; textures are one 64 px canvas each,
// made once and shared.
import * as THREE from "three";

// a petal in the xz plane (lying flat; y up), length along z: rounded, widest past its middle, a shallow notch
// at the tip, cupped (edges up) and a touch curled along its length. Origin at its middle.
export function petalGeometry(w = 0.09, l = 0.06, { cup = 0.35, notch = 0.12 } = {}) {
  const M = 18; // outline points
  const pos = [0, 0, 0];
  for (let i = 0; i < M; i++) {
    const a = (i / M) * Math.PI * 2; // a = 0 at the base (-z), round to the tip (+z) at a = PI
    const z = -Math.cos(a) * 0.5;
    // teardrop: narrow at the base, full and round towards the tip
    const x = Math.sin(a) * 0.5 * (0.5 + 0.5 * (z + 0.5));
    // the little notch in the middle of the tip
    const zz = z - notch * 0.5 * Math.exp(-((x * 7) ** 2)) * Math.max(0, z * 2);
    pos.push(x * w * 1.2, 0, zz * l);
  }
  const idx = [];
  for (let i = 1; i <= M; i++) idx.push(0, (i % M) + 1, i);
  const g = new THREE.BufferGeometry();
  const p = new Float32Array(pos);
  // cup and curl
  for (let i = 0; i < p.length; i += 3) {
    const x = p[i] / (w * 0.6);
    const z = p[i + 2] / (l * 0.5);
    p[i + 1] = (x * x * cup * 0.5 + z * z * 0.12) * Math.min(w, l) * 0.6;
  }
  g.setAttribute("position", new THREE.BufferAttribute(p, 3));
  const uv = new Float32Array((p.length / 3) * 2);
  for (let i = 0, j = 0; i < p.length; i += 3, j += 2) {
    uv[j] = p[i] / w + 0.5;
    uv[j + 1] = p[i + 2] / l + 0.5;
  }
  g.setAttribute("uv", new THREE.BufferAttribute(uv, 2));
  g.setIndex(idx);
  g.computeVertexNormals();
  return g;
}

// a pointed leaf in the xz plane, length along z (stalk at -z), folded a little along its midrib
export function leafGeometry(w = 0.1, l = 0.2, { fold = 0.25 } = {}) {
  const N = 5; // rows between the base and the tip
  const pos = [0, 0, -0.5]; // 0: the base
  for (let i = 1; i < N; i++) {
    const t = i / N;
    const half = Math.sin(Math.PI * Math.pow(t, 0.75)) * 0.5;
    const z = -0.5 + t;
    pos.push(-half, 0, z, 0, 0, z, half, 0, z); // left, midrib, right
  }
  const tip = pos.length / 3;
  pos.push(0, 0, 0.5);
  const row = (i) => 1 + (i - 1) * 3; // left index of row i (1..N-1)
  const idx = [];
  // base fan
  idx.push(0, row(1) + 1, row(1), 0, row(1) + 2, row(1) + 1);
  for (let i = 1; i < N - 1; i++) {
    const a = row(i);
    const b = row(i + 1);
    idx.push(a, a + 1, b + 1, a, b + 1, b, a + 1, a + 2, b + 2, a + 1, b + 2, b + 1);
  }
  const last = row(N - 1);
  idx.push(last, last + 1, tip, last + 1, last + 2, tip);
  // a short stalk
  const s0 = pos.length / 3;
  pos.push(-0.025, 0, -0.62, 0.025, 0, -0.62);
  idx.push(s0, 0, s0 + 1);
  const p = new Float32Array(pos);
  for (let i = 0; i < p.length; i += 3) {
    const x = p[i];
    const z = p[i + 2];
    p[i + 1] = Math.abs(x) * fold - z * z * 0.12; // folded along the midrib, the tip curling down a touch
    p[i] *= w;
    p[i + 1] *= w;
    p[i + 2] *= l;
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute("position", new THREE.BufferAttribute(p, 3));
  g.setIndex(idx);
  g.computeVertexNormals();
  return g;
}

let dotTex = null;
export function softDotTexture() {
  if (dotTex) return dotTex;
  const c = document.createElement("canvas");
  c.width = c.height = 64;
  const x = c.getContext("2d");
  const g = x.createRadialGradient(32, 32, 0, 32, 32, 32);
  g.addColorStop(0, "rgba(255,255,255,1)");
  g.addColorStop(0.18, "rgba(255,255,255,0.85)");
  g.addColorStop(0.45, "rgba(255,255,255,0.28)");
  g.addColorStop(1, "rgba(255,255,255,0)");
  x.fillStyle = g;
  x.fillRect(0, 0, 64, 64);
  dotTex = new THREE.CanvasTexture(c);
  dotTex.colorSpace = THREE.SRGBColorSpace;
  return dotTex;
}

let starTex = null;
export function sparkleTexture() {
  if (starTex) return starTex;
  const S = 64;
  const c = document.createElement("canvas");
  c.width = c.height = S;
  const x = c.getContext("2d");
  const img = x.createImageData(S, S);
  for (let j = 0; j < S; j++) {
    for (let i = 0; i < S; i++) {
      const u = (i + 0.5) / S - 0.5;
      const v = (j + 0.5) / S - 0.5;
      const r = Math.hypot(u, v) * 2;
      // four soft rays (thin, tapering) over a round soft core and a faint halo
      const ray = (a, b) => Math.exp(-((a * 22) ** 2)) * Math.max(0, 1 - Math.abs(b) * 2) ** 2;
      const rays = Math.max(ray(u, v), ray(v, u)) * 0.95 + Math.max(ray((u + v) * 0.7071, (u - v) * 0.7071), ray((u - v) * 0.7071, (u + v) * 0.7071)) * 0.25;
      const core = Math.exp(-r * r * 26);
      const halo = Math.max(0, 1 - r) ** 2 * 0.22;
      const a = Math.min(1, rays + core + halo);
      const k = (j * S + i) * 4;
      img.data[k] = img.data[k + 1] = img.data[k + 2] = 255;
      img.data[k + 3] = Math.round(a * 255);
    }
  }
  x.putImageData(img, 0, 0);
  starTex = new THREE.CanvasTexture(c);
  starTex.colorSpace = THREE.SRGBColorSpace;
  return starTex;
}

// a sparkle: the star on a sprite (additive by default, so it glows and never shows a card edge)
export function sparkleSprite(color = "#ffffff", size = 0.2, { additive = true, opacity = 1 } = {}) {
  const s = new THREE.Sprite(
    new THREE.SpriteMaterial({ map: sparkleTexture(), color, transparent: true, opacity, depthWrite: false, blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending }),
  );
  s.scale.setScalar(size);
  s.castShadow = false;
  s.raycast = () => {};
  return s;
}

// a sheet made solid from both sides for single-sided materials: the same sheet again, wound and lit the other
// way (its own vertices, so the two sides keep their own normals)
export function bothSides(g) {
  const a = g.index ? g.toNonIndexed() : g.clone();
  const b = a.clone();
  const p = b.attributes.position.array;
  const n = b.attributes.normal?.array;
  for (let i = 0; i < p.length; i += 9) {
    for (let k = 0; k < 3; k++) {
      const t = p[i + 3 + k];
      p[i + 3 + k] = p[i + 6 + k];
      p[i + 6 + k] = t;
      if (n) {
        const u = n[i + 3 + k];
        n[i + 3 + k] = n[i + 6 + k];
        n[i + 6 + k] = u;
      }
    }
  }
  if (n) for (let i = 0; i < n.length; i++) n[i] = -n[i];
  const out = new THREE.BufferGeometry();
  for (const k of Object.keys(a.attributes)) {
    const x = a.attributes[k];
    const y = b.attributes[k];
    const arr = new x.array.constructor(x.array.length * 2);
    arr.set(x.array, 0);
    arr.set(y.array, x.array.length);
    out.setAttribute(k, new THREE.BufferAttribute(arr, x.itemSize, x.normalized));
  }
  return out;
}
