// ---- the pack's files kept on the device ----------------------------------------------------------
// The service worker keeps the pack's files (models-v1, sw.template.js), but only on a visit it controls, and
// the old worker kept 80 of the ~240 a visit asks for (and threw out whatever else was in its cache): every
// refresh downloaded the island again. So the zone files are read from and kept in a cache of the island's
// own here, whatever the worker does, by their
// address (a pack's files never change: a new build has a new pack hash in its path; a path without one,
// a test bundle, is never kept)
const MODELS_CACHE = "island-files-v1";
const VERSIONED = /\/models\/[0-9a-f]{10}\//;
let modelCacheP = null;
const modelCache = () => (modelCacheP ||= Promise.resolve(globalThis.caches?.open(MODELS_CACHE) ?? null).catch(() => null));
const keepable = (url) => VERSIONED.test(new URL(url, location.href).pathname);
async function cachedFile(url) {
  if (!keepable(url)) return null;
  const c = await modelCache();
  try {
    return (c && (await c.match(url, { ignoreVary: true }))) || null;
  } catch {
    return null;
  }
}
async function keepFile(url, res) {
  // (kept here even on a page the worker controls: a worker that throws files out again, the old 80-file one,
  // must not decide what stays)
  if (!keepable(url)) return;
  const c = await modelCache();
  try {
    if (c) await c.put(url, res);
  } catch {}
}
// every file this visit will want, fetched ahead into the cache a few at a time (low priority), so the
// places further out and the rooms you walk to come off the device instead of the network
async function prefetchFiles(urls, gone) {
  const todo = [...new Set(urls)].filter(keepable);
  // (an older build's files go: a new build has a new pack hash in its path)
  try {
    const c = await modelCache();
    const pack = todo.length && VERSIONED.exec(new URL(todo[0], location.href).pathname)?.[0];
    if (c && pack) for (const req of await c.keys()) if (!new URL(req.url).pathname.includes(pack)) c.delete(req);
  } catch {}
  const one = async () => {
    while (todo.length && !gone()) {
      const url = todo.shift();
      try {
        if (await cachedFile(url)) continue;
        const res = await fetch(url, { priority: "low" });
        if (!res.ok) continue;
        await keepFile(url, res);
      } catch {}
    }
  };
  await Promise.all([one(), one(), one()]);
}

const kindRule = (k) => (KINDS.find(([re]) => re.test(k)) || [null, { max: 400 }])[1];
