// ---- the cobble material (MAT_paths_stone_vc) --------------------------------------------------
function cobbleMaterial(src, small) {
  const m = new THREE.MeshStandardMaterial({ name: "MAT_paths_stone_vc", vertexColors: true, roughness: 0.93, metalness: 0, flatShading: false, side: src?.side ?? THREE.FrontSide });
  m.onBeforeCompile = (sh) => {
    sh.vertexShader = sh.vertexShader
      .replace("#include <common>", "#include <common>\nvarying vec3 vCobW;\nvarying float vCobUp;")
      .replace(
        "#include <worldpos_vertex>",
        "#include <worldpos_vertex>\n{ vec4 cw = vec4(transformed, 1.0); vec3 cn = objectNormal;\n#ifdef USE_INSTANCING\ncw = instanceMatrix * cw; cn = mat3(instanceMatrix) * cn;\n#endif\nvCobW = (modelMatrix * cw).xyz; vCobUp = normalize(mat3(modelMatrix) * cn).y; }",
      );
    const noise = `
      varying vec3 vCobW;
      varying float vCobUp;
      float cobH(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
      float cobN(vec2 p) { vec2 i = floor(p), f = fract(p); f = f * f * (3.0 - 2.0 * f);
        return mix(mix(cobH(i), cobH(i + vec2(1, 0)), f.x), mix(cobH(i + vec2(0, 1)), cobH(i + vec2(1, 1)), f.x), f.y); }`;
    sh.fragmentShader = sh.fragmentShader.replace("#include <common>", "#include <common>\n" + noise).replace(
      "#include <color_fragment>",
      `#include <color_fragment>
      {
        // flanks and joints: the steeper the surface, the deeper in the crevice (a contact shade)
        float flank = 1.0 - smoothstep(0.62, 0.97, vCobUp);
        // gravel: coarse and fine grains, strongest in the joints and on the bedding
        float g1 = cobN(vCobW.xz * 13.0), g2 = cobN(vCobW.xz * 29.0 + 7.3);
        // (the grain fades out where it would be finer than a pixel: no sparkle in the distance)
        float fine = 1.0 - smoothstep(0.25, 0.7, length(fwidth(vCobW.xz)) * 29.0);
        float grit = ((g1 * 0.6 + g2 * 0.4) - 0.5) * fine;
        float lum = dot(diffuseColor.rgb, vec3(0.299, 0.587, 0.114));
        float jointish = clamp(flank + smoothstep(0.62, 0.52, lum) * 0.6, 0.0, 1.0);
        diffuseColor.rgb *= 1.0 + grit * mix(0.03, 0.3, jointish);
        // sand in the joints: a touch warmer, darker grains between the stones
        diffuseColor.rgb = mix(diffuseColor.rgb, diffuseColor.rgb * vec3(0.86, 0.78, 0.72), flank * 0.55);
        diffuseColor.rgb *= mix(1.0, 0.58, flank * flank) * 0.94;
      }`,
    );
  };
  m.customProgramCacheKey = () => "tdd_cobble";
  return m;
}

// ---- materials -------------------------------------------------------------------------------
const DRY = new THREE.Color("#fff0c4").multiplyScalar(1.06); // (autumn cards: a warm touch, not dry straw; fix pass 2026-11-21)

// ---- the weather on everything (track B, review 2026-11-20: in snow the roofs, paths, beds and crowns stayed summer;
// in autumn the crowns stayed green). One pair of shared uniforms drives every zone material: snow settles on what
// faces up (roofs, paths, tops of crowns, beds, fences), autumn turns foliage to ochre, amber and russet (a different
// tone per patch of crown). Set from the palette (weatherfx p.lawn, the christmas theme).
const WEATHER = { uSnow: { value: 0 }, uAutumn: { value: 0 }, uSnowCol: { value: new THREE.Color("#eef3fa") } };
const weatherDone = new WeakSet();
