      const big = bigTex && packFiles[`tex/T_${kitName}_2048.webp`];
      const m = new THREE.MeshStandardMaterial({ name: `MAT_kit_${kitName}`, map: tex(`T_${kitName}_${big ? 2048 : size}.webp`), roughness: variant === "gloss" ? 0.3 : 0.86, metalness: 0, flatShading: false });
