// Small things far away (a pebble, a flower, a cup on a table across the island) take up
// less than a few pixels on screen but still cost a whole draw each. Just for the main
// view, anything that small is skipped; it comes back long before it is big enough to
// see. Picking, the map, photos and shadows still see everything, because the skip is
// only switched on around the main render.
import * as THREE from "three";

const HIDE_PX = 2.4; // smaller than this across (in screen pixels): skipped
const SHOW_PX = 3.2; // back again once it is this big (a gap, so nothing flickers)
const MAX_R = 1.5; // only small things: never a building, a tree or the ground
const EVERY = 0.25; // seconds between looks
// see-through things and sprites (lamp halos, signs, glass, petals) are drawn after
// everything else, each on its own, and a phone pays dearly for every one: far off, where
// one is a smudge of a few pixels, it is skipped sooner, and bigger ones count too
const SOFT = { phone: { hide: 14, show: 18, maxR: 6 }, pc: { hide: 4, show: 5.5, maxR: 6 } };

export class DetailCull {
  constructor(scene, camera, { phone = false } = {}) {
    this.scene = scene;
    this.camera = camera;
    this.soft = phone ? SOFT.phone : SOFT.pc;
    this.hidden = new Set();
    this._next = new Set(); // (two sets taking turns: no new one every look)
    this.timer = 0;
    this._s = new THREE.Sphere();
    this._last = new THREE.Vector3(1e9, 0, 0);
  }

  // (the candidates, small meshes and sprites, are gathered in one walk every 2 s; each look is
  // spread over four frames, a quarter of them each: no whole-scene walk four times a second,
  // performance 14)
  gather() {
    const list = [];
    const walk = (o) => {
      if ((o.isSprite || (o.isMesh && !o.isInstancedMesh && !o.isSkinnedMesh)) && o.frustumCulled && !o.userData.keepDetail) list.push(o);
      const kids = o.children;
      for (let i = 0; i < kids.length; i++) walk(kids[i]);
    };
    walk(this.scene);
    this.list = list;
    this.gatheredAt = performance.now();
  }

  update(dt, viewHeight) {
    const cam = this.camera;
    this.timer -= dt;
    // a jump across the island (the map, a respawn) looks again straight away
    const jump = cam.position.distanceToSquared(this._last) >= 400;
    if (this.part === undefined || jump) this.part = 0;
    if (this.part === 0) {
      if (this.timer > 0 && !jump) return;
      this.timer = EVERY;
      this._last.copy(cam.position);
      if (!this.list || performance.now() - this.gatheredAt > 2000) this.gather();
      this._next.clear();
    }
    const pxPerUnit = viewHeight / (2 * Math.tan((cam.fov * Math.PI) / 360));
    const cp = cam.position;
    const s = this._s;
    const next = this._next;
    const list = this.list;
    const parts = jump ? 1 : 4;
    const a = Math.floor((list.length * this.part) / parts);
    const b = Math.floor((list.length * (this.part + 1)) / parts);
    for (let k = a; k < b; k++) {
      const o = list[k];
      if (!o.layers.isEnabled(0) && !this.hidden.has(o)) continue;
      let shown = Boolean(o.parent);
      for (let q = o; q && shown; q = q.parent) if (!q.visible) shown = false;
      if (!shown) continue;
      const sprite = o.isSprite;
      const soft = sprite || (o.material && !Array.isArray(o.material) && o.material.transparent);
      if (sprite) {
        s.center.setFromMatrixPosition(o.matrixWorld);
        s.radius = Math.max(o.scale.x, o.scale.y) * 0.5;
      } else {
        const g = o.geometry;
        if (!g.boundingSphere) g.computeBoundingSphere();
        s.copy(g.boundingSphere).applyMatrix4(o.matrixWorld);
      }
      if (s.radius < (soft ? this.soft.maxR : MAX_R)) {
        const dist = s.center.distanceTo(cp) - s.radius;
        if (dist > 1) {
          const px = ((2 * s.radius) / dist) * pxPerUnit;
          const was = this.hidden.has(o);
          if (px < (soft ? (was ? this.soft.show : this.soft.hide) : was ? SHOW_PX : HIDE_PX)) next.add(o);
        }
      }
    }
    this.part = (this.part + 1) % parts;
    if (this.part === 0) {
      this._next = this.hidden;
      this.hidden = next;
    }
  }

  // around the main render only
  hide() {
    for (const o of this.hidden) o.layers.disable(0);
  }
  show() {
    // (a piece merged into its neighbours since stays undrawn: see bake.js)
    for (const o of this.hidden) if (!o.__baked) o.layers.enable(0);
  }

  clear() {
    this.hidden.clear();
  }
}
