// The sky race's karts: three cute pastel go-karts (assets/blender/vehicles/_build_karts.py), only on the race road
// and only while a race is on. Each kart is the Blender model on its pivots (body > steer, steer_fl > wheel_fl,
// steer_fr > wheel_fr, wheel_rl, wheel_rr); phones (smallProps) load the _lite copies. Until the models are in (or
// with no zone pack) a simple procedural kart stands in on the same pivots.
import * as THREE from "three";
import { GLTFLoader } from "three/examples/jsm/loaders/GLTFLoader.js";
import { MeshoptDecoder } from "three/examples/jsm/libs/meshopt_decoder.module.js";
import { zoneMode } from "./zones/mode.js";
import { smallProps } from "./vehicle.js";

export const KART_KINDS = ["berry", "mint", "star"];
export const KART_SEAT = { y: 0.32, z: -0.2 }; // the seat top and how far back it sits (the ride_kart clip)
const BODY_Y = 0.24;
const WHEEL_R = { fl: 0.2, fr: 0.2, rl: 0.235, rr: 0.235 };
const STEER_AXIS = new THREE.Vector3(0, Math.sin(0.95), Math.cos(0.95)); // the steering column (the builder's COLUMN)
const TINT = { berry: "#ff9ec0", mint: "#9fe6c9", star: "#c6b3f2" };

// a kart for a scooter colour (so you and your person usually drive different ones)
export function kartFor(color, other) {
  const k = { "#8fd3f0": "mint", "#8fd3b6": "mint", "#b79be8": "star", "#ffd166": "star" }[color] || "berry";
  return k === other ? KART_KINDS[(KART_KINDS.indexOf(k) + 1) % 3] : k;
}

let lib = null; // Map(kind -> gltf scene)
let loading = null;
const made = new Set();
function load() {
  if (loading) return loading;
  const zm = zoneMode();
  if (!zm.v2 || !zm.base) return (loading = Promise.resolve(null));
  const loader = new GLTFLoader().setMeshoptDecoder(MeshoptDecoder);
  const sfx = smallProps() ? "_lite" : "";
  loading = Promise.all(
    KART_KINDS.map((k) =>
      loader.loadAsync(zm.base + "vehicles/veh_kart_" + k + sfx + ".glb").then((g) => {
        g.scene.traverse((o) => {
          if (!o.isMesh) return;
          o.geometry.userData.kit = true; // (shared by every kart: never disposed with one)
          o.material.flatShading = false;
          o.material.vertexColors = true;
          o.castShadow = true;
          o.receiveShadow = true;
        });
        return [k, g.scene];
      }),
    ),
  )
    .then((pairs) => {
      lib = new Map(pairs);
      for (const k of made) wear(k);
      return lib;
    })
    .catch((e) => {
      console.warn("karts", e);
      return null;
    });
  return loading;
}
// fetch the models ahead (the race is about to start)
export const preloadKarts = () => load();

// the model's meshes move onto the kart's pivots (the procedural stand-in leaves)
function wear(k) {
  const src = lib?.get(k.kind);
  if (!src || k.worn) return;
  k.worn = true;
  for (const g of Object.values(k.roles))
    for (const c of [...g.children])
      if (c.isMesh) {
        g.remove(c);
        c.geometry.dispose();
      }
  src.traverse((o) => {
    const role = o.userData?.tdd_role;
    const g = role && k.roles[role];
    if (!g) return;
    for (const c of o.children) {
      if (!c.isMesh) continue;
      const m = new THREE.Mesh(c.geometry, c.material);
      m.position.copy(c.position);
      m.quaternion.copy(c.quaternion);
      m.castShadow = true;
      m.receiveShadow = true;
      g.add(m);
    }
  });
}

const mat = (c) => new THREE.MeshStandardMaterial({ color: c, roughness: 0.5 });
export function makeKart(kind = "berry") {
  const root = new THREE.Group();
  const body = new THREE.Group();
  body.position.set(0, BODY_Y, 0);
  root.add(body);
  const steer = new THREE.Group();
  steer.position.set(0, 0.58 - BODY_Y, 0.16);
  body.add(steer);
  const roles = { body, steer };
  const wheels = {};
  const steers = {};
  for (const [w, r] of Object.entries(WHEEL_R)) {
    const x = w[1] === "l" ? 0.6 : -0.6;
    const z = w[0] === "f" ? 0.66 : -0.6;
    const wheel = new THREE.Group();
    if (w[0] === "f") {
      const s = new THREE.Group();
      s.position.set(x, r, z);
      s.add(wheel);
      root.add(s);
      steers[w] = s;
      roles["steer_" + w] = s;
    } else {
      wheel.position.set(x, r, z);
      root.add(wheel);
    }
    wheels[w] = wheel;
    roles["wheel_" + w] = wheel;
  }
  const k = { kind, root, body, steer, wheels, steers, roles, lean: body, isKart: true, spin: 0, wheelTurn: 0, roll: 0, pitch: 0, bobV: 0, last: 0, turbo: 0 };
  // the stand-in (until the model is in)
  const paint = mat(TINT[kind] || TINT.berry);
  const tub = new THREE.Mesh(new THREE.CapsuleGeometry(0.36, 1.1, 4, 10).rotateX(Math.PI / 2).scale(1, 0.4, 1), paint);
  tub.position.y = 0.06;
  body.add(tub);
  const ring = new THREE.Mesh(new THREE.TorusGeometry(0.11, 0.02, 6, 16), mat("#4d4560"));
  ring.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), STEER_AXIS);
  steer.add(ring);
  const tyre = mat("#4a4458");
  for (const [w, r] of Object.entries(WHEEL_R)) wheels[w].add(new THREE.Mesh(new THREE.CylinderGeometry(r, r, 0.26, 14).rotateZ(Math.PI / 2), tyre));
  root.traverse((o) => {
    if (o.isMesh) o.castShadow = true;
  });
  made.add(k);
  if (lib) wear(k);
  else load();
  return k;
}
export function dropKart(k) {
  made.delete(k);
}
// how far the body has bobbed from rest (the driver rides with it)
export const kartLift = (k) => k.body.position.y - BODY_Y;

const _q = new THREE.Quaternion();
// every frame: wheels spin and steer, the steering wheel turns, the body rolls into the turn (outward when sliding),
// squats on the gas, dips on the brakes and bobs on the road. slip: the drift angle (radians, + sliding right)
export function animateKart(k, dt, speed, turn, slip = 0, grounded = true) {
  if (!dt) return;
  const e = (r) => 1 - Math.exp(-dt * r);
  for (const [w, wh] of Object.entries(k.wheels)) wh.rotation.x += (speed * dt) / WHEEL_R[w];
  // (steering into a slide, the front wheels counter-steer a little)
  k.wheelTurn += (THREE.MathUtils.clamp(turn * 0.42 - slip * 0.6, -0.55, 0.55) - k.wheelTurn) * e(12);
  k.steers.fl.rotation.y = k.wheelTurn;
  k.steers.fr.rotation.y = k.wheelTurn;
  _q.setFromAxisAngle(STEER_AXIS, -k.wheelTurn * 2.6);
  k.steer.quaternion.copy(_q);
  const accel = (speed - k.last) / dt;
  k.last = speed;
  const rollWant = THREE.MathUtils.clamp(-turn * Math.abs(speed) * 0.006 + slip * 0.12, -0.09, 0.09);
  k.roll += (rollWant - k.roll) * e(7);
  const pitchWant = grounded ? THREE.MathUtils.clamp(-accel * 0.004, -0.05, 0.06) : 0;
  k.pitch += (pitchWant - k.pitch) * e(6);
  // a little engine shake, more at speed
  k.bobV += dt * (14 + Math.abs(speed) * 0.8);
  const bob = grounded ? Math.sin(k.bobV) * (0.004 + Math.min(1, Math.abs(speed) / 25) * 0.006) : 0;
  k.body.position.y = BODY_Y + bob;
  k.body.rotation.set(k.pitch, 0, k.roll);
}
