// The island shell (Wave 5), v2: zon_shell (lawn, lip, underside sectors, spires, boulders, the 14
// crystals and the 6 islets) and zon_shell_far (the range, falls, pools, river, cloud sea), or their
// _lite pair on phones. They supersede every zon_island* zone (never loaded). Kept ours: the fence,
// the drifting clouds, the far pine forests (lifted onto the new terrain), the islets' groups with
// the sky range's boards, and every bob and spin (the legacy formulas).
import * as THREE from "three";
import { sinkNow } from "./sink.js";
import { skyPines } from "../skyrange.js";
import { loadSky } from "../sky.js";

const UP = new THREE.Vector3(0, 1, 0);

// the whole zone switches level at once (the levels don't meet at the cell joins)
function zoneLevels(nodes) {
  const lv = [[], [], []];
  for (const [name, o] of nodes) {
    const m = /_LOD([0-2])(_raw)?$/.exec(name);
    if (m && o.isMesh) lv[+m[1]].push(o);
  }
  return lv;
}

export function shellFiles(small) {
  return small ? ["zon_shell_lite.glb", "zon_shell_lite_raw.glb"] : ["zon_shell.glb", "zon_shell_raw.glb", "zon_shell_raw_lod.glb"];
}
export function shellFarFiles(small) {
  return small ? ["zon_shell_far_lite_raw.glb"] : ["zon_shell_far_raw.glb", "zon_shell_far_raw_lod.glb"];
}

// the near shell is in (first frame): the legacy lawn, rim, underside, crystals and islet looks go
export function wireShell({ world, N, anims, root, mats, onPalette }) {
  sinkNow(world, "shell");
  // the islets follow their legacy groups (which bob, and carry the sky range's boards)
  const islets = world.islets || [];
  for (const [name, o] of N) {
    const m = /^ANIM_env_shell_islet_(\d)_bob/.exec(name);
    if (!m || !islets[+m[1]]) continue;
    const g = islets[+m[1]];
    root.attach(o);
    const dy = o.position.y - g.position.y;
    o.userData.zoneLive = true;
    anims.push(() => (o.position.y = g.position.y + dy));
  }
  // the crystals (pass 2: one GPU-instanced source, 14 instances in the cell holders) spin as
  // legacy, each its own: rotation.y = t * 0.3 + i, i by the angle it hangs at
  const parts = [];
  for (const [name, o] of N) if (/^GI_env_shell_crystal/.test(name)) o.traverse((c) => c.isInstancedMesh && parts.push(c));
  if (parts.length) {
    const list = [];
    const m = new THREE.Matrix4();
    for (const im of parts) {
      im.updateWorldMatrix(true, false);
      for (let k = 0; k < im.count; k++) {
        im.getMatrixAt(k, m);
        const w = m.clone().premultiply(im.matrixWorld);
        const p = new THREE.Vector3(), r = new THREE.Quaternion(), s = new THREE.Vector3();
        w.decompose(p, r, s);
        let a = Math.atan2(p.z, p.x) - 0.3;
        a = ((a % (Math.PI * 2)) + Math.PI * 2) % (Math.PI * 2);
        list.push({ p, r, s, i: Math.round((a / (Math.PI * 2)) * 14) % 14 });
      }
    }
    const src = parts[0];
    const all = new THREE.InstancedMesh(src.geometry, src.material, list.length);
    all.frustumCulled = false;
    all.castShadow = false;
    all.userData.zoneLive = true;
    all.__noBake = true;
    for (const im of parts) im.removeFromParent();
    root.add(all);
    const spin = new THREE.Quaternion();
    const rq = new THREE.Quaternion();
    // (the rest pose is the legacy pose at t = 0, Ry(i): the spin adds t * 0.3 on top)
    anims.push((t) => {
      list.forEach((c, k) => {
        rq.copy(c.r).premultiply(spin.setFromAxisAngle(UP, t * 0.3));
        all.setMatrixAt(k, m.compose(c.p, rq, c.s));
      });
      all.instanceMatrix.needsUpdate = true;
    });
    anims[anims.length - 1](0);
  }
  // (pass 1's crystals were single ANIM_ nodes)
  const q = new THREE.Quaternion();
  for (const [name, o] of N) {
    if (!/^ANIM_env_island_crystal_[abc]_spin/.test(name)) continue;
    const p = new THREE.Vector3();
    o.getWorldPosition(p);
    let a = Math.atan2(p.z, p.x) - 0.3;
    a = ((a % (Math.PI * 2)) + Math.PI * 2) % (Math.PI * 2);
    const i = Math.round((a / (Math.PI * 2)) * 14) % 14;
    root.attach(o);
    const q0 = o.quaternion.clone();
    o.userData.zoneLive = true;
    anims.push((t) => o.quaternion.copy(q0).multiply(q.setFromAxisAngle(UP, t * 0.3 + i)));
  }
  // the underside: at night a lift of the theme's underside colour, so it reads as moonlit rock (ref 2)
  const kit = mats.kitMat("shell");
  if (kit) {
    // (no emissive map: through the warm atlas the blue lift came out brown; a flat cool wash
    // reads as moonlight on the rock)
    // (the palette's underside colour leaning to a cool moonlight blue, ref 2)
    const moon = new THREE.Color("#5a78c8");
    const lift = (p) => kit.emissive.set(p.under || "#000000").lerp(moon, 0.5).multiplyScalar(0.25 * (p.night ?? 0));
    if (world.palette) lift(world.palette);
    onPalette(lift);
  }
  // the sectors: one level for the whole zone (LOD0 on the island, LOD1 out on the race / balloon)
  const lv = zoneLevels(N);
  const cam = new THREE.Vector3();
  let cur = -1;
  anims.push((t, dt, camPos) => {
    const d = Math.hypot(camPos.x, camPos.z);
    const want = !lv[1].length ? 0 : d < 150 ? 0 : !lv[2].length || d < 320 ? 1 : 2;
    if (want === cur) return;
    cur = want;
    lv.forEach((list, k) => list.forEach((o) => (o.visible = k === want)));
  });
  void cam;
}

// the far range is in (streamed right after the first frame): the legacy range, falls, pools,
// river and mist go; the pines step onto the new slopes; the zone's own level by device
export function wireShellFar({ world, N, anims, tier, haze, farPinesY }) {
  sinkNow(world, "shellfar");
  const lv = zoneLevels(N);
  const level = tier === "mid" ? 1 : 0;
  const want = lv[level].length ? level : 0;
  lv.forEach((list, k) => list.forEach((o) => (o.visible = !lv[want].length || k === want)));
  // (the haze the legacy range had: one mesh per material is enough to patch it)
  const seen = new Set();
  const g = new THREE.Group();
  for (const [, o] of N) {
    if (!o.isMesh || seen.has(o.material)) continue;
    seen.add(o.material);
    g.add(new THREE.Mesh(o.geometry, o.material));
  }
  haze?.(g);
  // the pine forests: the same pines, at the new terrain's height (assets/specs/shell/far_pines)
  // (version 2: the sculpted range's own pine layout, whole rows, in the soft Blender pine: skyrange.js)
  loadSky(world, { small: tier === "low" || tier === "mid" }); // (islets, clouds, gulls, light shafts, underbrush: sky.js)
  if (skyPines(world, farPinesY, tier === "low" || tier === "mid")) return;
  const pines = world.scenePines;
  if (pines && farPinesY?.length === pines.count) {
    const m = new THREE.Matrix4();
    for (let i = 0; i < pines.count; i++) {
      pines.getMatrixAt(i, m);
      m.elements[13] = farPinesY[i] - 0.6;
      pines.setMatrixAt(i, m);
    }
    pines.instanceMatrix.needsUpdate = true;
    pines.computeBoundingSphere();
  }
  void anims;
}
