// The seasonal zones (Wave 11, rebuild/reports/assets-seasonal.md): zon_seasonal_christmas and
// zon_seasonal_halloween, loaded the first time their theme shows. Each one hangs in the legacy
// theme group (world.festive / world.spooky), so it shows and hides with the theme exactly as the
// legacy set did, and the legacy set's meshes leave (its glow sprites, the pumpkin glows, the star's
// halo and the moon, stay). Colliders stay the legacy theme circles: push only, while the theme
// shows and below 2.5 m, never part of groundAt (island.js collide); the zone's COL_circ say the
// same and are only checked against them. The glow materials are the legacy ones (world.zoneMats:
// the fairy-light sets, the star, the carved faces, MAT_ghost, the third blended exception), so
// they twinkle and glow as before. Motion stays the legacy code's: the bats and the ghosts are 5
// InstancedMesh (bat body + 2 wings, ghost body + face) that follow the legacy movers each frame,
// the star turns with the legacy star. The snowmen are chr_snowman at the legacy snowmen.
import * as THREE from "three";
import { npcZoneIn } from "./characters.js";

const _q = new THREE.Quaternion();
const _r = new THREE.Matrix4();
const Z = new THREE.Vector3(0, 0, 1);

export function wireSeasonal(theme, { world, scene, anims, stats }) {
  const g = theme === "christmas" ? world.festive : world.spooky;
  if (!g) return;
  // the legacy look leaves (its sprites stay: they are the glows the zone does not draw)
  g.traverse((o) => {
    if (o.isMesh) o.visible = false;
  });
  const N = new Map();
  scene.traverse((o) => o.name && N.set(o.name, o));
  g.updateWorldMatrix(true, false);
  g.attach(scene);
  const st = { draws: 0 };
  // (the zone's circles against the legacy theme circles: same places, same sizes)
  const legacyC = theme === "christmas" ? world.festiveCircles || [] : world.spookyCircles || [];
  let match = 0;
  let cols = 0;
  const p = new THREE.Vector3();
  for (const [name, o] of N) {
    if (!/^COL_circ_/.test(name)) continue;
    cols++;
    o.getWorldPosition(p);
    if (legacyC.some((c) => Math.abs(c.x - p.x) < 0.03 && Math.abs(c.z - p.z) < 0.03 && Math.abs(c.r - (o.userData.tdd_r ?? c.r)) < 0.02)) match++;
  }
  st.colliders = { zone: cols, legacy: legacyC.length, matched: match };

  if (theme === "christmas") {
    const star = N.get("ANIM_sea_xmas_tree_star__0");
    if (star && world.festiveStar) anims.push(() => g.visible && (star.rotation.y = world.festiveStar.rotation.y));
    npcZoneIn(world, "christmas", [scene]);
  } else {
    const M = world.spookyMovers || { ghosts: [], bats: [] };
    // one InstancedMesh per part: the first mover's mesh is the shape, every node of that kind leaves
    const inst = (re, n) => {
      const nodes = [...N].filter(([k]) => re.test(k)).map(([, o]) => o);
      const src = nodes.find((o) => o.isMesh);
      if (!src || !n) return null;
      const m = new THREE.InstancedMesh(src.geometry, src.material, n);
      m.name = "seasonal." + src.name.replace(/__\d+$/, "");
      m.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
      m.frustumCulled = false;
      m.castShadow = false;
      m.receiveShadow = false;
      for (const o of nodes) o.visible = false;
      g.add(m);
      return m;
    };
    const batBody = inst(/^ANIM_sea_bat_body__\d+$/, M.bats.length);
    const wingL = inst(/^ANIM_sea_bat_wing_l__\d+$/, M.bats.length);
    const wingR = inst(/^ANIM_sea_bat_wing_r__\d+$/, M.bats.length);
    const ghost = inst(/^ANIM_sea_ghost_body__\d+$/, M.ghosts.length);
    const face = inst(/^SM_sea_ghost_face__\d+$/, M.ghosts.length);
    // (the bat body's children, the wings, stayed hidden with it: their nodes are under it)
    st.draws = [batBody, wingL, wingR, ghost, face].filter(Boolean).length;
    const m = new THREE.Matrix4();
    anims.push(() => {
      if (!g.visible) return;
      M.bats.forEach(({ bat, wings }, i) => {
        bat.updateMatrix();
        batBody?.setMatrixAt(i, bat.matrix);
        // (the wings flap about the body's long axis, as the legacy wings: l = wings[0])
        wingL?.setMatrixAt(i, m.multiplyMatrices(bat.matrix, _r.makeRotationFromQuaternion(_q.setFromAxisAngle(Z, wings[0].rotation.z))));
        wingR?.setMatrixAt(i, m.multiplyMatrices(bat.matrix, _r.makeRotationFromQuaternion(_q.setFromAxisAngle(Z, wings[1].rotation.z))));
      });
      M.ghosts.forEach((gh, i) => {
        gh.updateMatrix();
        ghost?.setMatrixAt(i, gh.matrix);
        face?.setMatrixAt(i, gh.matrix);
      });
      for (const x of [batBody, wingL, wingR, ghost, face]) if (x) x.instanceMatrix.needsUpdate = true;
    });
  }
  stats[theme] = st;
}
