// The flower icons (flowers track, 2026-11-20): every garden flower kind in every colour (and golden), rendered in
// Blender (assets/blender/vegetation/flowers/build_flowers.py) into one sheet packed with the zones
// (models/<hash>/flowers/T_flower_icons.webp + .json, never precached). The garden's shelf, book and bouquet
// cards show these; until the sheet is in (or with no zone pack) the garden draws its own picture as before.
import { zoneMode } from "../zones/mode.js";

let sheet = null; // { img, map }
let loading = null;
const urls = new Map();
const waiting = new Set();

function load() {
  if (loading) return loading;
  const base = zoneMode().base;
  if (!base) return (loading = Promise.resolve(null));
  loading = fetch(`${base}flowers/T_flower_icons.json`)
    .then((r) => (r.ok ? r.json() : null))
    .then(
      (map) =>
        map &&
        new Promise((done) => {
          const img = new Image();
          img.onload = () => done({ img, map });
          img.onerror = () => done(null);
          img.src = `${base}flowers/T_flower_icons.webp`;
        }),
    )
    .then((s) => {
      sheet = s;
      if (s) for (const fn of waiting) fn();
      waiting.clear();
      return s;
    })
    .catch(() => null);
  return loading;
}

// the icon of kind `id` in colour index `ci` (99 = golden) as a data URL, or null while the sheet isn't in
export function flowerIcon(id, ci = 0) {
  const key = `${id}|${ci}`;
  if (urls.has(key)) return urls.get(key);
  if (!sheet) {
    load();
    return null;
  }
  const at = sheet.map.icons[key];
  if (!at) return null;
  const n = sheet.map.size;
  const c = document.createElement("canvas");
  c.width = c.height = n;
  c.getContext("2d").drawImage(sheet.img, at[0], at[1], n, n, 0, 0, n, n);
  const url = c.toDataURL("image/png");
  urls.set(key, url);
  return url;
}

// call fn once the sheet has arrived (at once if it already has); start loading it now
export function onFlowerIcons(fn) {
  if (sheet) return fn();
  waiting.add(fn);
  load();
}
