// Phone layout for the 3D island (user, 2026-11-17, iPhone screenshots): the look editor took half the screen in
// landscape and nearly all of it in portrait, and toasts sat in the middle of the action. The 3D game's own sheet
// of rules, injected while the island runs (island.css is shared with the 2D site and stays untouched):
// - portrait phones: a slim editor sheet (36 % of the height) with smaller tabs, pills and swatches;
// - landscape phones (short screens): the editor is a narrow panel on the right, the toast a small strip at the top;
// - Safari cannot hide its own bars from a page: in landscape, a one-time tip suggests Add to Home Screen (the site
//   manifest opens standalone, full screen).
const CSS = `
@media (pointer: coarse) and (max-aspect-ratio: 4/5) and (max-width: 640px) {
  html .g3d-editor .g3d-editor-sheet { max-height: 36%; border-radius: 22px 22px 0 0; }
  html .g3d-editor .g3d-sheet-title, html .g3d-editor .g3d-panel-head { padding-top: 8px; padding-bottom: 4px; font-size: 15px; }
  html .g3d-editor .g3d-editor-body { padding: 2px 12px 12px; }
  html .g3d-editor .g3d-ed-tabs > .g3d-chips:first-child .g3d-chip { padding: 5px 10px; font-size: 13px; }
  html .g3d-editor .g3d-ed-tabs .g3d-ed-parts { margin-top: 6px; flex-wrap: nowrap; overflow-x: auto; scrollbar-width: none; }
  html .g3d-editor .g3d-ed-row .g3d-chip.g3d-chip-part { padding: 6px 8px 8px; font-size: 13px; white-space: nowrap; }
  html .g3d-editor .g3d-editor-body .g3d-ed-row:not(.g3d-ed-tabs) .g3d-chip { padding: 5px 10px; font-size: 12.5px; }
  html .g3d-editor .g3d-ed-row h3 { margin: 10px 0 5px; font-size: 10px; }
  html .g3d-editor .g3d-chips, html .g3d-editor .g3d-swatches { gap: 6px; }
  html .g3d-editor .g3d-swatch { width: 28px; height: 28px; }
}
@media (pointer: coarse) and (min-aspect-ratio: 5/4) and (max-height: 540px) {
  html .g3d-toast {
    top: calc(6px + env(safe-area-inset-top, 0px));
    padding: 6px 14px;
    font-size: 12.5px;
    max-width: min(46vw, 420px);
  }
  html .g3d-editor { place-items: stretch end; padding: 0; }
  html .g3d-editor .g3d-editor-sheet {
    width: min(330px, 40vw);
    max-height: 100%;
    height: 100%;
    border-radius: 20px 0 0 20px;
    padding-right: env(safe-area-inset-right, 0px);
  }
  html .g3d-editor .g3d-sheet-title, html .g3d-editor .g3d-panel-head { padding-top: 6px; padding-bottom: 2px; font-size: 14px; }
  html .g3d-editor .g3d-editor-body { padding: 2px 10px 10px; }
  html .g3d-editor .g3d-ed-tabs > .g3d-chips:first-child .g3d-chip { padding: 4px 8px; font-size: 12px; }
  html .g3d-editor .g3d-ed-tabs .g3d-ed-parts { margin-top: 4px; flex-wrap: nowrap; overflow-x: auto; scrollbar-width: none; }
  html .g3d-editor .g3d-ed-row .g3d-chip.g3d-chip-part { padding: 5px 7px 7px; font-size: 12px; white-space: nowrap; }
  html .g3d-editor .g3d-editor-body .g3d-ed-row:not(.g3d-ed-tabs) .g3d-chip { padding: 4px 9px; font-size: 12px; }
  html .g3d-editor .g3d-ed-row h3 { margin: 8px 0 4px; font-size: 10px; }
  html .g3d-editor .g3d-chips, html .g3d-editor .g3d-swatches { gap: 5px; }
  html .g3d-editor .g3d-swatch { width: 24px; height: 24px; }
  html .g3d-overlay:not(.g3d-editor) .g3d-sheet { max-height: 94%; }
}`;

let styleEl = null;
export function phoneUI({ toast, isTouch }) {
  if (!styleEl) {
    styleEl = document.createElement("style");
    styleEl.id = "g3d-phone-ui";
    styleEl.textContent = CSS;
    document.head.appendChild(styleEl);
  }
  if (!isTouch) return;
  const ios = /iPhone|iPad|iPod/.test(navigator.userAgent) || (navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1);
  const standalone = navigator.standalone || matchMedia("(display-mode: standalone)").matches || matchMedia("(display-mode: fullscreen)").matches;
  if (!ios || standalone) return;
  swipeUp();
  let seen = false;
  try {
    seen = localStorage.getItem("tdd3d.homeTip") === "1";
  } catch {}
  if (seen) return;
  let done = false;
  const tip = () => {
    if (done || !matchMedia("(orientation: landscape)").matches) return;
    done = true;
    removeEventListener("orientationchange", later);
    try {
      localStorage.setItem("tdd3d.homeTip", "1");
    } catch {}
    toast("tip: Share → Add to Home Screen plays the island full screen ♡");
  };
  const later = () => setTimeout(tip, 800);
  setTimeout(tip, 6000);
  addEventListener("orientationchange", later);
}
// Safari in landscape (user, 2026-11-17): its address and tab bars only fold away when the page itself is scrolled by a
// finger, and the island's page cannot scroll. While they show, the page is made a little taller and scrollable under a
// "swipe up" veil; once the bars have folded (the window is as tall as the screen) the veil leaves and the page locks
// again (its layers are fixed, the scroll offset doesn't move them). A tap on the veil skips it for this visit.
const SWIPE_CSS = `
html.g3d-on.g3d-swipe-on, html.g3d-on.g3d-swipe-on body { overflow-y: auto !important; height: calc(100% + 240px) !important; }
.g3d-swipe { position: fixed; inset: 0; z-index: 2147483000; display: grid; place-items: center; touch-action: pan-y;
  background: rgba(10, 8, 24, 0.55); color: #f2f1ff; font: 600 17px/1.3 inherit; text-align: center; -webkit-user-select: none; user-select: none; }
.g3d-swipe b { display: block; font-size: 34px; animation: g3d-swipe-up 1.2s ease-in-out infinite; }
@keyframes g3d-swipe-up { 0%, 100% { transform: translateY(8px); opacity: 0.6; } 50% { transform: translateY(-8px); opacity: 1; } }`;
let swipe = null;
function swipeUp() {
  if (swipe) return;
  const st = document.createElement("style");
  st.textContent = SWIPE_CSS;
  document.head.appendChild(st);
  const veil = document.createElement("div");
  veil.className = "g3d-swipe";
  veil.innerHTML = "<div><b>↑</b>swipe up for full screen</div>";
  let skipped = false;
  const html = document.documentElement;
  const barsShow = () => {
    const short = Math.min(screen.width, screen.height);
    return innerWidth > innerHeight && innerHeight < short - 8;
  };
  const check = () => {
    const want = !skipped && html.classList.contains("g3d-on") && barsShow();
    if (want && !veil.parentNode) {
      html.classList.add("g3d-swipe-on");
      document.body.appendChild(veil);
    } else if (!want && veil.parentNode) {
      veil.remove();
      html.classList.remove("g3d-swipe-on");
    }
  };
  veil.addEventListener("click", () => {
    skipped = true;
    check();
  });
  const later = () => setTimeout(check, 350);
  addEventListener("resize", check);
  addEventListener("scroll", check, { passive: true });
  addEventListener("orientationchange", later);
  setTimeout(check, 1500);
  swipe = () => {
    removeEventListener("resize", check);
    removeEventListener("scroll", check);
    removeEventListener("orientationchange", later);
    veil.remove();
    st.remove();
    html.classList.remove("g3d-swipe-on");
  };
}
// (when the island closes: the 3D rules leave with it)
export function phoneUIOff() {
  styleEl?.remove();
  styleEl = null;
  swipe?.();
  swipe = null;
}
