// Procedural textures painted on canvas: every surface in the world comes
// from here, so nothing needs to be downloaded. All are tileable.
import * as THREE from "three";

const cache = new Map();
let SIZE = 256;
let maxAniso = 4;
let dropPixels = false; // (painted pixels let go once uploaded, pixels())

export function configureTextures({ lowEnd, renderer }) {
  SIZE = lowEnd ? 128 : 256;
  dropPixels = true; // (every tier: on a computer the painted pixels were ~130 MB, review 2026-11-20)
  // (phones: 2x, review-threejs performance 22)
  maxAniso = Math.min(lowEnd ? 2 : 8, renderer.capabilities.getMaxAnisotropy());
}

function rng(seed) {
  let s = (seed * 2654435761) >>> 0 || 1;
  return () => {
    s ^= s << 13;
    s ^= s >>> 17;
    s ^= s << 5;
    return (s >>> 0) / 4294967296;
  };
}

// periodic value noise, so the textures tile without seams
function tileNoise(size, cells, seed) {
  const r = rng(seed);
  const g = new Float32Array(cells * cells);
  for (let i = 0; i < g.length; i++) g[i] = r();
  return (x, y) => {
    const fx = (x / size) * cells;
    const fy = (y / size) * cells;
    const x0 = Math.floor(fx);
    const y0 = Math.floor(fy);
    const tx = fx - x0;
    const ty = fy - y0;
    const sx = tx * tx * (3 - 2 * tx);
    const sy = ty * ty * (3 - 2 * ty);
    const xa = ((x0 % cells) + cells) % cells;
    const ya = ((y0 % cells) + cells) % cells;
    const xb = (xa + 1) % cells;
    const yb = (ya + 1) % cells;
    const a = g[ya * cells + xa];
    const b = g[ya * cells + xb];
    const c = g[yb * cells + xa];
    const d = g[yb * cells + xb];
    return a + (b - a) * sx + (c - a) * sy + (a - b - c + d) * sx * sy;
  };
}

function fbm(size, seed, base = 4) {
  const layers = [1, 2, 4, 8].map((m, i) => tileNoise(size, base * m, seed + i * 977));
  return (x, y) =>
    layers[0](x, y) * 0.5 + layers[1](x, y) * 0.25 + layers[2](x, y) * 0.15 + layers[3](x, y) * 0.1;
}

const hexToRgb = (hex) => {
  const c = new THREE.Color(hex);
  return [c.r * 255, c.g * 255, c.b * 255];
};

function paintPixels(ctx, size, fn) {
  const img = ctx.createImageData(size, size);
  const d = img.data;
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const i = (y * size + x) * 4;
      const [r, g, b] = fn(x, y);
      d[i] = r;
      d[i + 1] = g;
      d[i + 2] = b;
      d[i + 3] = 255;
    }
  }
  ctx.putImageData(img, 0, 0);
}

const mix = (a, b, t) => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
const shade = (c, k) => [c[0] * k, c[1] * k, c[2] * k];

const painters = {
  grass(ctx, s, [a, b]) {
    const n = fbm(s, 11, 4);
    const fine = tileNoise(s, 64, 5);
    const ca = hexToRgb(a);
    const cb = hexToRgb(b);
    paintPixels(ctx, s, (x, y) => shade(mix(ca, cb, n(x, y)), 0.88 + fine(x, y) * 0.22));
    const r = rng(3);
    for (let i = 0; i < s * 1.4; i++) {
      const x = r() * s;
      const y = r() * s;
      ctx.strokeStyle = `rgba(255,255,255,${0.05 + r() * 0.08})`;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x + (r() - 0.5) * 3, y - 2 - r() * 4);
      ctx.stroke();
    }
  },
  wood(ctx, s, [a, b]) {
    const n = fbm(s, 21, 2);
    const ca = hexToRgb(a);
    const cb = hexToRgb(b);
    const rows = 4;
    const r = rng(9);
    const tints = Array.from({ length: rows }, () => 0.85 + r() * 0.3);
    const offsets = Array.from({ length: rows }, () => r() * s);
    paintPixels(ctx, s, (x, y) => {
      const row = Math.floor((y / s) * rows);
      const ry = (y / s) * rows - row;
      const grain = Math.sin(((x + offsets[row]) / s) * Math.PI * 6 + n(x, y) * 14 + row) * 0.5 + 0.5;
      let c = shade(mix(ca, cb, grain * 0.6 + n(x, y) * 0.4), tints[row]);
      if (ry < 0.04 || ry > 0.96) c = shade(c, 0.55);
      const seam = ((x + offsets[row]) % s) / s;
      if (seam < 0.012) c = shade(c, 0.6);
      return c;
    });
  },
  tiles(ctx, s, [a, b]) {
    const n = fbm(s, 31, 4);
    const ca = hexToRgb(a);
    const cb = hexToRgb(b);
    const cells = 4;
    paintPixels(ctx, s, (x, y) => {
      const cx = Math.floor((x / s) * cells);
      const cy = Math.floor((y / s) * cells);
      const fx = (x / s) * cells - cx;
      const fy = (y / s) * cells - cy;
      const base = (cx + cy) % 2 ? ca : mix(ca, cb, 0.5);
      let c = shade(base, 0.9 + n(x, y) * 0.2);
      if (fx < 0.05 || fy < 0.05) c = shade(cb, 0.7);
      return c;
    });
  },
  cobble(ctx, s, [a, b]) {
    ctx.fillStyle = b;
    ctx.fillRect(0, 0, s, s);
    const r = rng(41);
    const ca = hexToRgb(a);
    const rows = 5;
    const h = s / rows;
    for (let row = 0; row < rows; row++) {
      let x = row % 2 ? -h * 0.5 : 0;
      while (x < s) {
        const w = h * (0.8 + r() * 0.6);
        const k = 0.8 + r() * 0.35;
        ctx.fillStyle = `rgb(${ca[0] * k | 0},${ca[1] * k | 0},${ca[2] * k | 0})`;
        const rad = h * 0.3;
        for (const dx of [0, s, -s]) {
          ctx.beginPath();
          ctx.roundRect(x + dx + 2, row * h + 2, w - 4, h - 4, rad);
          ctx.fill();
        }
        x += w;
      }
    }
    noiseOverlay(ctx, s, 51, 0.12);
  },
  wallpaper(ctx, s, [a, b]) {
    ctx.fillStyle = a;
    ctx.fillRect(0, 0, s, s);
    ctx.fillStyle = b;
    const stripes = 8;
    for (let i = 0; i < stripes; i += 2) ctx.fillRect((i / stripes) * s, 0, s / stripes / 3, s);
    ctx.globalAlpha = 0.55;
    const step = s / 4;
    for (let y = 0; y < 4; y++) {
      for (let x = 0; x < 4; x++) {
        heart(ctx, x * step + step * 0.5 + (y % 2 ? step / 2 : 0), y * step + step * 0.5, s / 28, b);
      }
    }
    ctx.globalAlpha = 1;
    noiseOverlay(ctx, s, 61, 0.06);
  },
  fabric(ctx, s, [a, b]) {
    const ca = hexToRgb(a);
    const cb = hexToRgb(b);
    const n = fbm(s, 71, 8);
    paintPixels(ctx, s, (x, y) => {
      const w = ((Math.floor(x / 2) + Math.floor(y / 2)) % 2) * 0.5;
      const check = (Math.floor(x / (s / 4)) + Math.floor(y / (s / 4))) % 2;
      return shade(mix(ca, cb, check * 0.6 + w * 0.15), 0.9 + n(x, y) * 0.18);
    });
  },
  shingles(ctx, s, [a, b]) {
    ctx.fillStyle = b;
    ctx.fillRect(0, 0, s, s);
    const r = rng(81);
    const ca = hexToRgb(a);
    const rows = 6;
    const h = s / rows;
    const cols = 6;
    const w = s / cols;
    for (let row = 0; row < rows + 1; row++) {
      for (let col = -1; col < cols + 1; col++) {
        const k = 0.82 + r() * 0.3;
        ctx.fillStyle = `rgb(${ca[0] * k | 0},${ca[1] * k | 0},${ca[2] * k | 0})`;
        const x = col * w + (row % 2 ? w / 2 : 0);
        const y = row * h;
        ctx.beginPath();
        ctx.moveTo(x + 1, y - h * 0.2);
        ctx.lineTo(x + w - 1, y - h * 0.2);
        ctx.lineTo(x + w - 1, y + h * 0.55);
        ctx.quadraticCurveTo(x + w / 2, y + h * 1.1, x + 1, y + h * 0.55);
        ctx.closePath();
        ctx.fill();
      }
    }
    noiseOverlay(ctx, s, 91, 0.1);
  },
  stone(ctx, s, [a, b]) {
    const n = fbm(s, 101, 3);
    const fine = tileNoise(s, 48, 7);
    const ca = hexToRgb(a);
    const cb = hexToRgb(b);
    paintPixels(ctx, s, (x, y) => {
      const band = Math.sin((y / s) * Math.PI * 10 + n(x, y) * 9) * 0.5 + 0.5;
      return shade(mix(ca, cb, band * 0.5 + n(x, y) * 0.5), 0.85 + fine(x, y) * 0.25);
    });
  },
  plaster(ctx, s, [a, b]) {
    const n = fbm(s, 111, 4);
    const ca = hexToRgb(a);
    const cb = hexToRgb(b);
    paintPixels(ctx, s, (x, y) => mix(ca, cb, n(x, y) * 0.7));
    // a beam along the bottom edge for a cottage look
    ctx.fillStyle = "rgba(90,60,45,0.35)";
    ctx.fillRect(0, s * 0.94, s, s * 0.06);
  },
  rug(ctx, s, [a, b]) {
    ctx.fillStyle = a;
    ctx.fillRect(0, 0, s, s);
    ctx.strokeStyle = b;
    ctx.lineWidth = s / 24;
    for (let i = 1; i < 5; i++) {
      ctx.beginPath();
      ctx.arc(s / 2, s / 2, (i / 5) * s * 0.48, 0, Math.PI * 2);
      ctx.stroke();
    }
    heart(ctx, s / 2, s / 2, s / 10, b);
    noiseOverlay(ctx, s, 121, 0.1);
  },
};

function heart(ctx, x, y, r, color) {
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.moveTo(x, y + r * 0.9);
  ctx.bezierCurveTo(x - r * 1.6, y - r * 0.2, x - r * 0.6, y - r * 1.4, x, y - r * 0.4);
  ctx.bezierCurveTo(x + r * 0.6, y - r * 1.4, x + r * 1.6, y - r * 0.2, x, y + r * 0.9);
  ctx.fill();
}

function noiseOverlay(ctx, s, seed, strength) {
  const n = fbm(s, seed, 8);
  const img = ctx.getImageData(0, 0, s, s);
  const d = img.data;
  for (let y = 0; y < s; y++) {
    for (let x = 0; x < s; x++) {
      const i = (y * s + x) * 4;
      const k = 1 + (n(x, y) - 0.5) * strength * 2;
      d[i] *= k;
      d[i + 1] *= k;
      d[i + 2] *= k;
    }
  }
  ctx.putImageData(img, 0, 0);
}

// A painted canvas kept as plain pixels: a phone quietly empties canvases it hasn't drawn
// to for a while when memory runs short, and a texture made from one came back black the
// next time it was sent to the graphics card (after the graphics were lost, say). Pixels in
// memory can't be emptied; the canvas itself is let go of.
export function pixelTex(canvas) {
  return pixels(canvas);
}
function pixels(canvas) {
  const { width, height } = canvas;
  const data = canvas.getContext("2d").getImageData(0, 0, width, height).data;
  canvas.width = canvas.height = 0;
  return dataTex(data, width, height);
}
function dataTex(data, width, height) {
  const tex = new THREE.DataTexture(data, width, height);
  tex.flipY = true;
  tex.generateMipmaps = true;
  tex.minFilter = THREE.LinearMipmapLinearFilter;
  tex.magFilter = THREE.LinearFilter;
  tex.needsUpdate = true;
  // once on the graphics card the pixels go too (~30 MB on a phone, review 2026-11-20; a repaint, upgrade(), sends new ones). Nothing here
  // re-sends them: phones have no room zones (their texture copies, zones/v2-local.js) and a lost GL context
  // reloads the island (island.js); a cached paint given back after being disposed is painted again (texture())
  // (small ones stay: a few kilobytes each, and a copy of one made with other settings, a custom shader's map,
  // must still have pixels to send: a 64 px one went up empty, GL INVALID_OPERATION)
  if (dropPixels && width * height > 64 * 64)
    tex.onUpdate = () => {
      if (tex.userData.keepPixels) return; // (a room's surfaces: the room zone copies them, world.js)
      tex.image = { data: new Uint8ClampedArray(0), width, height };
      tex.userData.dropped = tex.version; // (the version sent up: a later one could only send nothing)
      if (!tex.userData.goneHook) tex.addEventListener("dispose", () => (tex.userData.gone = true));
      tex.userData.goneHook = true;
      // (once its pixels are gone a texture is never sent again with nothing in it: a 'send again' (a new wrap, say)
      // keeps the copy on the card as it is; new pixels, upgrade(), still go up)
      if (!tex.userData.sendGuard) {
        tex.userData.sendGuard = true;
        Object.defineProperty(tex, "needsUpdate", {
          configurable: true,
          set(v) {
            if (!v) return;
            if (this.image?.data && this.image.data.length === 0) return;
            this.version++;
            this.source.needsUpdate = true;
          },
        });
      }
      globalThis.__tddArraysFreed = true;
    };
  return tex;
}

export function texture(kind, colors, repeat = 1) {
  const key = `${kind}|${colors.join(",")}|${repeat}`;
  if (cache.has(key) && !cache.get(key).userData.gone) return cache.get(key);
  // (painted on an earlier visit: read back, preloadPaints; with its Blender detail already laid over, on a computer)
  const kd = SIZE >= 256 && takePaint(`${key}|d${DETAIL_SIZE}`);
  const k0 = !kd && takePaint(`${key}|${SIZE}`);
  let tex;
  if (kd || k0) tex = dataTex(...(kd || k0));
  else {
    const canvas = document.createElement("canvas");
    canvas.width = canvas.height = SIZE;
    const ctx = canvas.getContext("2d");
    painters[kind](ctx, SIZE, colors);
    tex = pixels(canvas);
    keepPaint(`${key}|${SIZE}`, tex.image.data, SIZE, SIZE);
  }
  if (kd) tex.userData.detailed = true;
  tex.userData.paintKey = key;
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(repeat, repeat);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = maxAniso;
  tex.userData.paint = { kind, colors };
  cache.set(key, tex);
  if (detail) upgrade(tex);
  return tex;
}

// ---- Blender surface detail (PC) ---------------------------------------------------------------
// assets/blender/materials/build_surface_detail.py renders seamless greyscale detail maps (wood fibre and
// knots, stone grit, woven cloth, plaster tooth, glaze crazing). On PC the zone runtime hands their folder
// over (setSurfaceDetail): every painted surface is then repainted at 512 px with its map laid over the
// paint (overlay), so wood, stone, fabric and plaster read as material instead of a flat 256 px swatch.
// Phones keep the plain 256 px paint (memory).
const DETAIL_OF = { wood: "wood", shingles: "wood", stone: "stone", cobble: "stone", fabric: "fabric", rug: "fabric", plaster: "plaster", wallpaper: "plaster", tiles: "glaze" };
const DETAIL_STRENGTH = { wood: 0.32, stone: 0.4, fabric: 0.45, plaster: 0.35, glaze: 0.3 };
const DETAIL_SIZE = 512;
let detail = null; // name -> HTMLImageElement, once loaded
function upgrade(tex) {
  const p = tex.userData.paint;
  const d = p && DETAIL_OF[p.kind];
  const img = d && detail[d];
  if (!img || tex.userData.detailed) return;
  const kd = tex.userData.paintKey && takePaint(`${tex.userData.paintKey}|d${DETAIL_SIZE}`);
  if (kd) {
    tex.dispose();
    tex.userData.gone = false;
    tex.image = { data: kd[0], width: kd[1], height: kd[2] };
    tex.userData.detailed = true;
    tex.needsUpdate = true;
    return;
  }
  const canvas = document.createElement("canvas");
  canvas.width = canvas.height = DETAIL_SIZE;
  const ctx = canvas.getContext("2d");
  painters[p.kind](ctx, DETAIL_SIZE, p.colors);
  ctx.globalCompositeOperation = "overlay";
  ctx.globalAlpha = DETAIL_STRENGTH[d];
  ctx.drawImage(img, 0, 0, DETAIL_SIZE, DETAIL_SIZE);
  const data = ctx.getImageData(0, 0, DETAIL_SIZE, DETAIL_SIZE).data;
  canvas.width = canvas.height = 0;
  if (tex.userData.paintKey) keepPaint(`${tex.userData.paintKey}|d${DETAIL_SIZE}`, data, DETAIL_SIZE, DETAIL_SIZE);
  tex.dispose(); // (a new size: the GPU copy is made again)
  tex.userData.gone = false; // (new pixels follow: it is still the cached paint, pixels())
  tex.image = { data, width: DETAIL_SIZE, height: DETAIL_SIZE };
  tex.userData.detailed = true;
  tex.needsUpdate = true;
}
// a Blender surface map as a plain repeating texture (the garden plots' tilled soil), every tier: cb(tex) once
// the zone runtime has said where the pack is (setSurfaceBase) and the file is in
let surfaceBase = null;
const surfaceWait = [];
const surfaceMaps = new Map();
export function setSurfaceBase(base) {
  surfaceBase = base;
  for (const f of surfaceWait.splice(0)) f();
}
export function withSurfaceMap(name, repeat, cb) {
  const go = () => {
    const key = `${name}|${repeat}`;
    if (!surfaceMaps.has(key))
      surfaceMaps.set(
        key,
        new THREE.TextureLoader().loadAsync(`${surfaceBase}T_detail_${name}_512.webp`).then((t) => {
          t.wrapS = t.wrapT = THREE.RepeatWrapping;
          t.repeat.set(repeat, repeat);
          t.colorSpace = THREE.SRGBColorSpace;
          t.anisotropy = maxAniso;
          return t;
        }),
      );
    surfaceMaps.get(key).then(cb, () => {});
  };
  if (surfaceBase) go();
  else surfaceWait.push(go);
}
export function setSurfaceDetail(base, names = ["wood", "stone", "fabric", "plaster", "glaze"]) {
  if (detail || SIZE < 256) return Promise.resolve();
  const load = (n) =>
    new Promise((res) => {
      const im = new Image();
      im.onload = () => res([n, im]);
      im.onerror = () => res([n, null]);
      im.src = `${base}T_detail_${n}_512.webp`;
    });
  return Promise.all(names.map(load)).then((got) => {
    detail = Object.fromEntries(got.filter(([, im]) => im));
    for (const tex of cache.values()) upgrade(tex);
  });
}

// ---- painted textures kept on the device ----------------------------------------------------------------
// Painting every surface pixel by pixel took about 8 s of a computer's load (on every visit, refresh or not).
// Each paint is kept as a lossless PNG in the Cache API (paints-v1) under its key, its size and a stamp of the
// painters' own code (any change to a painter paints afresh). They are read back (decoded off the main thread)
// as soon as the island's code arrives, while the portal opens: whatever is in by the time a surface is wanted,
// the world build's or the computer's detail pass (upgrade), is not painted again.
const PAINTS = "paints-v1";
let stamp = null;
const stored = new Map(); // name -> [data, width, height]
const keepQ = [];
let keepTimer = 0;
const paintURL = (name) => `${location.origin}/__paint/${stamp}/${encodeURIComponent(name)}`;
function paintStamp() {
  const src = Object.values(painters).map(String).join("|") + String(noiseOverlay) + String(fbm) + String(tileNoise) + JSON.stringify(DETAIL_STRENGTH);
  let h = 2166136261;
  for (let i = 0; i < src.length; i++) h = Math.imul(h ^ src.charCodeAt(i), 16777619);
  return (h >>> 0).toString(36);
}
function takePaint(name) {
  const v = stored.get(name);
  if (v) stored.delete(name);
  return v || null;
}
function keepPaint(name, data, w, h) {
  if (!stamp || !data?.length) return;
  keepQ.push([name, data, w, h]);
  clearTimeout(keepTimer);
  // (after the build: the encoding runs off the main thread, the writes are small)
  keepTimer = setTimeout(flushPaints, 5000);
}
async function flushPaints() {
  try {
    const c = await caches.open(PAINTS);
    while (keepQ.length) {
      const [name, data, w, h] = keepQ.shift();
      const oc = new OffscreenCanvas(w, h);
      oc.getContext("2d").putImageData(new ImageData(data, w, h), 0, 0);
      const blob = await oc.convertToBlob({ type: "image/png" });
      await c.put(paintURL(name), new Response(blob, { headers: { "content-type": "image/png" } }));
    }
  } catch {
    keepQ.length = 0;
  }
}
async function preloadPaints() {
  try {
    if (!globalThis.caches || typeof OffscreenCanvas === "undefined" || typeof createImageBitmap === "undefined") return;
    stamp = paintStamp();
    const c = await caches.open(PAINTS);
    const mine = `/__paint/${stamp}/`;
    const keys = await c.keys();
    await Promise.all(
      keys.map(async (req) => {
        const path = new URL(req.url).pathname;
        // (another version's paints: gone)
        if (!path.startsWith(mine)) return c.delete(req);
        const res = await c.match(req);
        const bmp = await createImageBitmap(await res.blob(), { colorSpaceConversion: "none", premultiplyAlpha: "none" });
        const oc = new OffscreenCanvas(bmp.width, bmp.height);
        const ctx = oc.getContext("2d", { willReadFrequently: true });
        ctx.drawImage(bmp, 0, 0);
        stored.set(decodeURIComponent(path.slice(mine.length)), [ctx.getImageData(0, 0, bmp.width, bmp.height).data, bmp.width, bmp.height]);
        bmp.close();
      }),
    );
  } catch {}
}

preloadPaints();

// A canvas for signs and in-world screens that we redraw when text changes.
export function textCanvas(width, height) {
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = maxAniso;
  return { canvas, ctx: canvas.getContext("2d"), tex };
}

// photos and paintings travel between us as data URLs; only real images are
// ever shown, linked or drawn (never a script link)
export const isImageData = (src) => typeof src === "string" && /^data:image\/(png|jpe?g|webp|gif);base64,[a-z0-9+/=]+$/i.test(src);

export const FONT = '"Quicksand", "Noto Sans", "Noto Sans Symbols 2", "Noto Sans Batak", "Apple Color Emoji", "Noto Color Emoji", "Segoe UI Symbol", sans-serif';

export function wrapText(ctx, text, maxWidth) {
  const out = [];
  for (const para of String(text).split(/\n+/)) {
    const words = para.split(/\s+/).filter(Boolean);
    let line = "";
    for (const word of words) {
      const test = line ? `${line} ${word}` : word;
      if (ctx.measureText(test).width > maxWidth && line) {
        out.push(line);
        line = word;
      } else line = test;
    }
    if (line) out.push(line);
  }
  return out;
}

// a repeating texture painted onto a fresh canvas
// (`live`: one that is drawn into again later stays a canvas)
export function canvasTex(w, h, paint, rx = 1, ry = 1, live = false) {
  const c = document.createElement("canvas");
  c.width = w;
  c.height = h;
  paint(c.getContext("2d"), w, h);
  const t = live ? new THREE.CanvasTexture(c) : pixels(c);
  t.colorSpace = THREE.SRGBColorSpace;
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(rx, ry);
  t.anisotropy = 4;
  return t;
}
