// The picture's colour grade (look pass, VISUAL-TECH-SPEC §R): the island's own tone mapping (ACES
// Filmic, as before) followed by a light grade, the same on every tier:
//   - the darks lean towards the theme's shade colour and keep their colour (painted shade, never
//     grey), with a touch of lift;
//   - a little more colour overall (saturation), and a gentle gain / midtone gamma.
//
// One function, two ways in, so phones and computers see the same picture:
//   - high/ultra (the off-screen picture, look.js): GradePass is the last pass, in place of three's
//     OutputPass (tone mapping + grade + sRGB in the one pass the picture already took: no extra
//     full-screen pass);
//   - low/mid (straight onto the canvas, no passes): every material tone-maps itself, so the grade
//     rides in three's "custom" tone mapping (renderer.toneMapping = CustomToneMapping). Its three
//     values are uniforms no material knows about: they are set straight on each shader program
//     (setPrograms), and a program that never got them grades with zeros, which is no grade at all.
//
// Also on low/mid: the fog is mixed in BEFORE the tone mapping, as on the off-screen path (where the
// finished picture is tone-mapped, fog included). three mixes it after, so the canvas's fog looked a
// different colour from the off-screen picture's.
import * as THREE from "three";
import { Pass, FullScreenQuad } from "three/examples/jsm/postprocessing/Pass.js";

// three's own tone mapping chunks, kept to put back when the island is left
const ORIG = {};

const GRADE_GLSL = /* glsl */ `
// look pass grade (render/grade.js). All three are zero = no grade.
uniform vec4 lookA; // rgb: lift (added in the darks)          a: saturation - 1
uniform vec4 lookB; // rgb: gain - 1                           a: midtone gamma - 1
uniform vec4 lookC; // rgb: shade tint - 1 (the darks lean to it) a: extra saturation in the darks
vec3 lookGrade( vec3 c ) {
	float l = dot( c, vec3( 0.2126, 0.7152, 0.0722 ) );
	float dark = 1.0 - smoothstep( 0.0, 0.42, l );
	c *= 1.0 + lookC.rgb * dark;
	c = max( mix( vec3( l ), c, 1.0 + lookA.a + lookC.a * dark ), 0.0 );
	c = c * ( 1.0 + lookB.rgb ) + lookA.rgb * ( 1.0 - c );
	return pow( max( c, 0.0 ), vec3( 1.0 / ( 1.0 + lookB.a ) ) );
}
`;

// installed while an island (or the turntable) is running; idempotent
export function installGrade() {
  const C = THREE.ShaderChunk;
  if (ORIG.pars) return;
  ORIG.pars = C.tonemapping_pars_fragment;
  ORIG.frag = C.tonemapping_fragment;
  ORIG.fog = C.fog_fragment;
  const stub = "vec3 CustomToneMapping( vec3 color ) { return color; }";
  if (!ORIG.pars.includes(stub)) throw new Error("look: three's CustomToneMapping stub changed");
  C.tonemapping_pars_fragment = ORIG.pars.replace(stub, `${GRADE_GLSL}\nvec3 CustomToneMapping( vec3 color ) { return lookGrade( ACESFilmicToneMapping( color ) ); }`);
  // (the fog colour reaches a canvas shader already in sRGB: back to linear for the mix)
  C.tonemapping_fragment = `
#if defined( TONE_MAPPING ) && defined( USE_FOG )
	{
		#ifdef FOG_EXP2
			float lookFog = 1.0 - exp( - fogDensity * fogDensity * vFogDepth * vFogDepth );
		#else
			float lookFog = smoothstep( fogNear, fogFar, vFogDepth );
		#endif
		vec3 lookFogLin = mix( pow( fogColor * 0.9478672986 + vec3( 0.0521327014 ), vec3( 2.4 ) ), fogColor * 0.0773993808, vec3( lessThanEqual( fogColor, vec3( 0.04045 ) ) ) );
		gl_FragColor.rgb = mix( gl_FragColor.rgb, lookFogLin, lookFog );
	}
	#define LOOK_FOGGED
#endif
${ORIG.frag}`;
  C.fog_fragment = `#ifndef LOOK_FOGGED\n${ORIG.fog}\n#endif\n`;
  // the cached shadow box ends 28 m out: fade the shadow over its last eighth instead of a hard
  // line that steps as the box re-centres (review-threejs lighting 6; only the sun casts)
  ORIG.shadow = C.shadowmap_pars_fragment;
  const cut = "return mix( 1.0, shadow, shadowIntensity );";
  const at = ORIG.shadow.indexOf(cut);
  if (at >= 0)
    C.shadowmap_pars_fragment =
      ORIG.shadow.slice(0, at) +
      // (round, and over the outer third: a square fade still drew the box's corners round the
      // player, the user's "box following me", 2026-11-17)
      "vec2 lookE = abs( shadowCoord.xy - 0.5 ) * 2.0; return mix( 1.0, shadow, shadowIntensity * ( 1.0 - smoothstep( 0.62, 0.98, length( lookE ) ) ) );" +
      ORIG.shadow.slice(at + cut.length);
}

export function uninstallGrade() {
  if (!ORIG.pars) return;
  const C = THREE.ShaderChunk;
  C.tonemapping_pars_fragment = ORIG.pars;
  C.tonemapping_fragment = ORIG.frag;
  C.fog_fragment = ORIG.fog;
  if (ORIG.shadow) C.shadowmap_pars_fragment = ORIG.shadow;
  delete ORIG.pars;
}

// the grade's three values from a look palette's grade settings
//   g: { sat, darkSat, lift: [r,g,b], gain: [r,g,b], gamma, shade: [r,g,b] (multiplier in the darks) }
export function gradeVectors(g, out = { A: new Float32Array(4), B: new Float32Array(4), C: new Float32Array(4) }) {
  out.A.set([g.lift[0], g.lift[1], g.lift[2], g.sat - 1]);
  out.B.set([g.gain[0] - 1, g.gain[1] - 1, g.gain[2] - 1, g.gamma - 1]);
  out.C.set([g.shade[0] - 1, g.shade[1] - 1, g.shade[2] - 1, g.darkSat]);
  return out;
}

// The last pass of the off-screen picture: tone mapping, the grade, then sRGB onto the canvas.
export class GradePass extends Pass {
  constructor() {
    super();
    this.uniforms = {
      tDiffuse: { value: null },
      toneMappingExposure: { value: 1 },
      lookA: { value: new THREE.Vector4() },
      lookB: { value: new THREE.Vector4() },
      lookC: { value: new THREE.Vector4() },
    };
    this.material = new THREE.RawShaderMaterial({
      name: "LookGradeShader",
      uniforms: this.uniforms,
      vertexShader: /* glsl */ `
        precision highp float;
        uniform mat4 modelViewMatrix;
        uniform mat4 projectionMatrix;
        attribute vec3 position;
        attribute vec2 uv;
        varying vec2 vUv;
        void main() {
          vUv = uv;
          gl_Position = projectionMatrix * modelViewMatrix * vec4( position, 1.0 );
        }`,
      fragmentShader: /* glsl */ `
        precision highp float;
        uniform sampler2D tDiffuse;
        #include <tonemapping_pars_fragment>
        #include <colorspace_pars_fragment>
        varying vec2 vUv;
        void main() {
          gl_FragColor = texture2D( tDiffuse, vUv );
          gl_FragColor.rgb = CustomToneMapping( gl_FragColor.rgb );
          gl_FragColor = sRGBTransferOETF( gl_FragColor );
          // (a step of noise before the 8-bit output: no banding in dark gradients, lighting review 14)
          gl_FragColor.rgb += ( fract( sin( dot( gl_FragCoord.xy, vec2( 12.9898, 78.233 ) ) ) * 43758.5453 ) - 0.5 ) / 255.0;
        }`,
    });
    this.fsQuad = new FullScreenQuad(this.material);
    // (draws onto the canvas; never swaps the composer's targets, see look.js)
    this.needsSwap = false;
  }

  set(v) {
    this.uniforms.lookA.value.fromArray(v.A);
    this.uniforms.lookB.value.fromArray(v.B);
    this.uniforms.lookC.value.fromArray(v.C);
  }

  render(renderer, writeBuffer, readBuffer) {
    this.uniforms.tDiffuse.value = readBuffer.texture;
    this.uniforms.toneMappingExposure.value = renderer.toneMappingExposure;
    renderer.setRenderTarget(this.renderToScreen ? null : writeBuffer);
    if (this.clear) renderer.clear();
    this.fsQuad.render(renderer);
  }

  dispose() {
    this.material.dispose();
    this.fsQuad.dispose();
  }
}

// low/mid: the grade's values set straight on every shader program that tone-maps (three never
// touches uniforms its materials don't list, so they stay as set). Programs made later (a phone's
// merged pieces, a photo) get them on the next call; one that is still compiling waits for it.
export class ProgramGrade {
  constructor(renderer) {
    this.renderer = renderer;
    this.locs = new WeakMap();
    this.v = null;
    this.version = 0;
    this.count = -1;
  }

  set(v) {
    this.v = v;
    this.version++;
  }

  // once a frame (cheap when nothing changed)
  sync(force = false) {
    const v = this.v;
    if (!v) return;
    const list = this.renderer.info.programs;
    if (!list) return;
    // (the ids, not the count: one freed and one compiled between two syncs keep the count,
    // lighting review 11)
    let sig = list.length;
    for (const p of list) sig = (sig * 31 + p.id) % 2147483647;
    if (!force && sig === this.count && this.done === this.version) return;
    const gl = this.renderer.getContext();
    const state = this.renderer.state;
    let pending = false;
    for (const p of list) {
      let l = this.locs.get(p);
      if (l && l.version === this.version && !force) continue;
      // (asking a program that is still compiling would wait for it, holding the page)
      if (typeof p.isReady === "function" && !p.isReady()) {
        pending = true;
        continue;
      }
      if (!l) {
        const prog = p.program;
        const ok = prog && gl.getProgramParameter(prog, gl.LINK_STATUS);
        l = ok ? { a: gl.getUniformLocation(prog, "lookA"), b: gl.getUniformLocation(prog, "lookB"), c: gl.getUniformLocation(prog, "lookC"), version: -1 } : { version: -1 };
        this.locs.set(p, l);
      }
      if (l.a || l.b || l.c) {
        state.useProgram(p.program);
        if (l.a) gl.uniform4fv(l.a, v.A);
        if (l.b) gl.uniform4fv(l.b, v.B);
        if (l.c) gl.uniform4fv(l.c, v.C);
      }
      l.version = this.version;
    }
    this.count = pending ? -1 : sig;
    this.done = pending ? -1 : this.version;
  }

  // the graphics came back: every program is new
  reset() {
    this.locs = new WeakMap();
    this.count = -1;
    this.done = -1;
  }
}
