// One-role clip players for the things that are not creatures (scale.md): the ambient props (signs,
// pennants, flags, mobiles, the vane, windsock, pinwheel, mailbox flag, gift lid), the balloon's craft and
// flame and the swings' arms. No Animator and no pose array: a clip's one track is sampled straight into
// a small TRS, crossfaded with the one before it by weight. Phase per instance: t + hash(name) x length.
import * as THREE from "three";
import { clipLib } from "./clips.js";
import { isCalm, smooth01 } from "./runtime.js";

const _q = new THREE.Quaternion();
const _q2 = new THREE.Quaternion();
const _e = new THREE.Euler();

// a stable 0..1 per name (an instance's phase offset)
export function hash01(s) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
  return ((h >>> 0) % 10007) / 10007;
}

// sample the clip's tracks for role ri at t into o (10 floats: t3 q4 s3), from the carrier's rest
export function sampleRole(lib, clip, ri, t, o) {
  const R = lib.rest;
  const b = ri * 10;
  for (let j = 0; j < 10; j++) o[j] = R[b + j];
  const d = clip.duration;
  if (clip.loop && d > 0) t = ((t % d) + d) % d;
  else t = t < 0 ? 0 : t > d ? d : t;
  const f = t * clip.fps;
  const fi = f | 0;
  const u = f - fi;
  for (const tr of clip.tracks) {
    if (tr.ri !== ri) continue;
    const i0 = fi < tr.n - 1 ? fi : tr.n - 1;
    const i1 = i0 + 1 < tr.n ? i0 + 1 : i0;
    const D = tr.data;
    if (tr.kind === 1) {
      let l = 0;
      for (let j = 0; j < 4; j++) {
        o[3 + j] = D[i0 * 4 + j] + (D[i1 * 4 + j] - D[i0 * 4 + j]) * u;
        l += o[3 + j] * o[3 + j];
      }
      l = 1 / Math.sqrt(l || 1);
      for (let j = 0; j < 4; j++) o[3 + j] *= l;
    } else {
      const off = tr.kind === 0 ? 0 : 7;
      for (let j = 0; j < 3; j++) o[off + j] = D[i0 * 3 + j] + (D[i1 * 3 + j] - D[i0 * 3 + j]) * u;
    }
  }
  return o;
}
// blend b into a by w (nlerp)
export function mixTRS(a, b, w) {
  if (w <= 0) return a;
  if (w >= 1) {
    a.set(b);
    return a;
  }
  for (let j = 0; j < 3; j++) a[j] += (b[j] - a[j]) * w;
  for (let j = 7; j < 10; j++) a[j] += (b[j] - a[j]) * w;
  const s = a[3] * b[3] + a[4] * b[4] + a[5] * b[5] + a[6] * b[6] < 0 ? -1 : 1;
  let l = 0;
  for (let j = 3; j < 7; j++) {
    a[j] += (s * b[j] - a[j]) * w;
    l += a[j] * a[j];
  }
  l = 1 / Math.sqrt(l || 1);
  for (let j = 3; j < 7; j++) a[j] *= l;
  return a;
}

// One role on one node, with its own state: play(name) crossfades from whatever was playing.
// apply modes: "rest" (q = rest x clip, p = rest + clip delta: zone pivots), or "euler" with a list of the
// legacy rotation components it owns ("x", "yz"...: the legacy pieces, whose other components stay).
export class RolePlayer {
  constructor(carrier, role, node, { phase = 0, mode = "rest", axes = "xyz", amp = 1, restQ = null, restP = null } = {}) {
    this.carrier = carrier;
    this.role = role;
    this.node = node;
    this.phase = phase;
    this.mode = mode;
    this.axes = axes;
    this.amp = amp;
    this.lib = null;
    this.ri = -1;
    this.cur = null;
    this.prev = null;
    this.t = 0;
    this.pt = 0;
    this.w = 1;
    this.fade = 0.3;
    this.a = new Float32Array(10);
    this.b = new Float32Array(10);
    this.restP = (restP || node.position).clone();
    this.restQ = (restQ || node.quaternion).clone();
    this.restE = node.rotation.clone();
    this.restS = node.scale.clone();
  }
  // the carrier is in (false: the legacy motion keeps the node)
  ready() {
    if (this.lib) return true;
    const lib = clipLib(this.carrier);
    if (!lib) return false;
    const ri = lib.index.get(this.role);
    if (ri === undefined) return false;
    this.lib = lib;
    this.ri = ri;
    return true;
  }
  name() {
    return this.cur?.name || "";
  }
  done() {
    return this.cur ? !this.cur.loop && this.t >= this.cur.duration : true;
  }
  play(name, fade = 0.3, t0 = null) {
    const c = this.lib?.get(name);
    if (!c || c === this.cur) return;
    this.prev = this.cur;
    this.pt = this.t;
    this.cur = c;
    this.t = t0 ?? (c.loop ? this.phase * c.duration : 0);
    this.w = this.prev && fade > 0 ? 0 : 1;
    this.fade = fade;
  }
  // step and write the node; the clip's next (tdd_next) follows a one-shot by itself
  update(dt, weight = 1) {
    const c = this.cur;
    if (!c) return;
    const k = isCalm() ? 0.5 : 1;
    this.t += dt * k;
    this.pt += dt * k;
    if (this.w < 1) this.w = Math.min(1, this.w + dt / Math.max(1e-3, this.fade));
    if (!c.loop && this.t >= c.duration && c.extras.tdd_next) this.play(c.extras.tdd_next, 0.2);
    this.write(weight);
  }
  // drive the clip at a time directly (phase-driven clips)
  at(name, t, weight = 1) {
    const c = this.lib?.get(name);
    if (!c) return;
    this.cur = c;
    this.prev = null;
    this.t = t;
    this.w = 1;
    this.write(weight);
  }
  write(weight) {
    const L = this.lib;
    const a = sampleRole(L, this.cur, this.ri, this.t, this.a);
    if (this.prev && this.w < 1) {
      const b = sampleRole(L, this.prev, this.ri, this.pt, this.b);
      mixTRS(b, a, smooth01(this.w));
      a.set(b);
    }
    const amp = (isCalm() ? 0.25 : 1) * this.amp * weight;
    const R = L.rest;
    const o = this.ri * 10;
    const n = this.node;
    _q.set(a[3], a[4], a[5], a[6]);
    if (amp !== 1) _q.slerp(_q2.set(R[o + 3], R[o + 4], R[o + 5], R[o + 6]), 1 - amp);
    if (this.mode === "rest") {
      n.position.set(this.restP.x + (a[0] - R[o]) * amp, this.restP.y + (a[1] - R[o + 1]) * amp, this.restP.z + (a[2] - R[o + 2]) * amp);
      n.quaternion.copy(this.restQ).multiply(_q);
      // (scale relative to the carrier's rest: the balloon's flame is all scale)
      const k = (j) => (R[o + j] ? a[j] / R[o + j] : a[j]);
      n.scale.set(this.restS.x * k(7), this.restS.y * k(8), this.restS.z * k(9));
    } else {
      _e.setFromQuaternion(_q, "XYZ");
      const A = this.axes;
      const r = n.rotation;
      if (A.includes("x")) r.x = this.restE.x + _e.x;
      if (A.includes("y")) r.y = this.restE.y + _e.y;
      if (A.includes("z")) r.z = this.restE.z + _e.z;
    }
  }
}

// the ambient props: one player per node, looping its role's clip on the world clock at its own phase
// (t + hash(id) x length: deterministic, no state). Legacy closures call ambient(...) and keep their own
// sine when it answers false (the carrier is not in yet, or zones=legacy).
const players = new WeakMap(); // (by node: a node that leaves takes its player with it)
export function ambientPlayer(id, node, role, { axes = "xyz", mode = "euler", restQ = null, restP = null } = {}) {
  let p = players.get(node);
  if (!p) {
    p = new RolePlayer("env_ambient_clips", role, node, { phase: hash01(id), mode, axes, restQ, restP });
    players.set(node, p);
  }
  return p.ready() ? p : null;
}
function isStill(c, ri) {
  for (const tr of c.tracks) {
    if (tr.ri !== ri) continue;
    const s = tr.kind === 1 ? 4 : 3;
    for (let i = s; i < tr.data.length; i++) if (Math.abs(tr.data[i] - tr.data[i % s]) > 1e-4) return false;
  }
  return true;
}
export function ambient(id, node, role, clip, t, opts) {
  const p = ambientPlayer(id, node, role, opts);
  if (!p) return false;
  const c = p.lib.get(clip);
  // (a clip whose track never moves, the pinwheel's single-key spin: the legacy motion stays)
  if (!c || (c.still ??= isStill(c, p.ri))) return false;
  const k = isCalm() ? 0.5 : 1;
  p.at(clip, t * k + p.phase * c.duration);
  return true;
}


// the mailbox flag: mailbox_flag_up / _down once on an unread change, then the last frame held (legacy
// eased x 0.1 a frame, frame-rate bound). Answers false until the carrier is in.
export function mailFlag(node, unread, dt, opts) {
  const p = ambientPlayer("mailbox_flag", node, "mailbox_flag", opts);
  if (!p) return false;
  const want = unread ? "mailbox_flag_up" : "mailbox_flag_down";
  if (p.name() !== want) {
    const first = !p.name();
    p.play(want, 0);
    if (first) p.t = p.cur.duration; // (as it is now, no flourish on arrival)
  }
  p.update(Math.min(dt || 0.016, 0.1));
  return true;
}
