// The daisy wheel: a slow pastel Ferris wheel in the meadow between the duck lake and the campfire.
// The Blender ride (assets/blender/activities/ferris/_build_ferris.py, rides/act_ferris_wheel[_lite].glb) brings
// three pivots: base (the A-frame behind the wheel, the boarding deck), wheel (turned here about its axle) and one
// gondola (cloned per cabin, kept level, each tinted its own pastel). It runs on the shared wall clock (balloon.js
// clock), so both of you see the same cabin at the deck. It never stops: each cabin slowly passes the deck, you
// hop in while it goes by, ride one whole turn and hop out as it passes the deck again (island.js).
import * as THREE from "three";
import { GLTFLoader } from "three/examples/jsm/loaders/GLTFLoader.js";
import { MeshoptDecoder } from "three/examples/jsm/libs/meshopt_decoder.module.js";
import { zoneMode } from "./zones/mode.js";
import { clock } from "./balloon.js";

// (the Blender builder's numbers)
const HUB = 9.3;
const R = 6.4;
const N = 8;
const PIN_Z = 2.9;
const FLOOR = 2.45;
const DECK = 0.3;
export const FERRIS_SEAT_H = 0.45; // the cushion above the cabin floor
const LOOP = 60; // s for one whole turn (the cabin passes the deck at about 0.67 m/s)
const D = (Math.PI * 2) / N;
const W_SPD = (Math.PI * 2) / LOOP;
const WIN = 0.17; // rad either side of the bottom: the cabin is by the deck (about 1.1 m each way, 3.2 s)
const TAU = Math.PI * 2;
const wrapPi = (a) => a - TAU * Math.floor((a + Math.PI) / TAU);
// where it stands: an open meadow (the colliders' clearest spot that fits it), its deck facing the willow
const SPOT = new THREE.Vector3(-46, 0, -34);
const YAW = Math.atan2(-SPOT.x, -SPOT.z);
const TINTS = ["#ffb6d0", "#cdb6ff", "#a9ead3", "#ffe39a", "#ffc4a6", "#b7d9ff", "#f7b2e8", "#c8f0a8"];
// what stands on the ground (local metres): kept clear of the meadow's trees, flowers and tufts
const CLEAR = { x0: -6.3, x1: 6.3, z0: -6.4, z1: 7.2 };


export class Ferris {
  constructor(scene, world, { small = false } = {}) {
    this.world = world;
    this.yaw = YAW;
    this.root = new THREE.Group();
    this.root.name = "ferris";
    this.root.position.copy(SPOT);
    this.root.rotation.y = YAW;
    this.root.updateMatrixWorld(true);
    this.wheel = new THREE.Group();
    this.wheel.position.set(0, HUB, 0);
    this.root.add(this.wheel);
    this.cabins = [];
    this.theta = 0;
    this.ready = false;
    scene.add(this.root);
    this.exit = this.toWorld(0, DECK, 4.9);
    this.stand = this.toWorld(0, DECK, 4.7);

    // the meadow's trees, rocks, flowers and tufts keep off it (zones/runtime.js drops their instances in
    // world.clearings; the legacy colliders of the small ones go here)
    const inv = new THREE.Matrix4().copy(this.root.matrixWorld).invert();
    const clearing = { inv, ...CLEAR };
    clearing.has = (x, z) => {
      const p = _v.set(x, 0, z).applyMatrix4(inv);
      return p.x > CLEAR.x0 && p.x < CLEAR.x1 && p.z > CLEAR.z0 && p.z < CLEAR.z1;
    };
    (world.clearings ||= []).push(clearing);
    for (let i = world.circles.length - 1; i >= 0; i--) {
      const c = world.circles[i];
      if (c.r <= 1.6 && clearing.has(c.x, c.z)) world.circles.splice(i, 1);
    }
    // its colliders: the A-frame's three feet, the deck (stood on, top DECK) and its step, the rails
    for (const [x, z] of [[-4.7, -2.3], [4.7, -2.3], [0, -5.6]]) world.circles.push({ ...this.flat(x, z), r: 0.6, top: Infinity });
    for (const x of [-2.6, -0.9, 0.9, 2.6]) for (const z of [0.6, 2.2, 3.8, 5.2]) world.circles.push({ ...this.flat(x, z), r: 1.15, top: DECK - 0.04 }) // (a hair under the planks: stepped onto from anywhere, the rails keep the sides);
    for (const x of [-0.7, 0.7]) world.circles.push({ ...this.flat(x, 6.15), r: 0.6, top: 0.16 });
    for (const x of [-3.6, 3.6]) {
      const a = this.flat(x, 0.9), b = this.flat(x, 5.7);
      world.segments.push({ ax: a.x, az: a.z, bx: b.x, bz: b.z, h: 1.3, room: "" });
    }
    const self = this;
    world.interactables.push({
      id: "ferris",
      get label() {
        return self.riding ? "" : self.canBoard() ? "hop in the daisy wheel 🎡" : `the daisy wheel 🎡 · next cabin in ${Math.ceil(self.untilStop()) || 1}s`;
      },
      pos: this.stand.clone(),
      radius: 2.6,
      action: { type: "ferris" },
      hits: [],
    });
    this.load(small);
  }

  toWorld(x, y, z, out = new THREE.Vector3()) {
    return out.set(x, y, z).applyMatrix4(this.root.matrixWorld);
  }
  flat(x, z) {
    const p = this.toWorld(x, 0, z);
    return { x: p.x, z: p.z };
  }

  load(small) {
    const zm = zoneMode();
    if (!zm.v2 || !zm.base) return;
    const sfx = small ? "_lite" : "";
    new GLTFLoader()
      .setMeshoptDecoder(MeshoptDecoder)
      .loadAsync(zm.base + "rides/act_ferris_wheel" + sfx + ".glb")
      .then((g) => {
        const roles = {};
        g.scene.traverse((o) => {
          if (o.userData?.tdd_role) roles[o.userData.tdd_role] = o.children.filter((c) => c.isMesh);
        });
        if (!roles.base || !roles.wheel || !roles.gondola) return;
        this.bulbMat = new THREE.MeshBasicMaterial({ vertexColors: true, toneMapped: false });
        const prep = (m, cast) => {
          if (/bulb/.test(m.material.name)) m.material = this.bulbMat;
          else {
            m.material.flatShading = false;
            m.material.vertexColors = true;
          }
          m.castShadow = cast;
          m.receiveShadow = true;
          return m;
        };
        for (const m of roles.base) this.root.add(prep(m, true));
        for (const m of roles.wheel) this.wheel.add(prep(m, false));
        for (let i = 0; i < N; i++) {
          const cab = new THREE.Group();
          cab.name = "ferris.cabin" + i;
          const tint = new THREE.Color(TINTS[i % TINTS.length]);
          for (const m0 of roles.gondola) {
            const m = prep(m0.clone(), false);
            if (/tint/.test(m0.material.name)) {
              m.material = m0.material.clone();
              m.material.color.copy(tint);
            }
            cab.add(m);
          }
          this.root.add(cab);
          this.cabins.push(cab);
        }
        this.makeGlow();
        this.ready = true;
        this.update(0, this.night || 0);
      })
      .catch((e) => console.warn("ferris", e));
  }

  // the bulbs' soft halos at night: one point cloud on the wheel (it turns with it) and one on the lamp posts
  makeGlow() {
    const c = document.createElement("canvas");
    c.width = c.height = 64;
    const x = c.getContext("2d");
    const grd = x.createRadialGradient(32, 32, 0, 32, 32, 32);
    grd.addColorStop(0, "rgba(255,255,255,1)");
    grd.addColorStop(0.25, "rgba(255,255,255,0.5)");
    grd.addColorStop(1, "rgba(255,255,255,0)");
    x.fillStyle = grd;
    x.fillRect(0, 0, 64, 64);
    const tex = new THREE.CanvasTexture(c);
    const cols = ["#ffe2a8", "#ffa8cc", "#ffe08a", "#d8c4ff"].map((h) => new THREE.Color(h));
    const cloud = (pts, size) => {
      const g = new THREE.BufferGeometry();
      g.setAttribute("position", new THREE.Float32BufferAttribute(pts.flatMap((p) => p[0]), 3));
      g.setAttribute("color", new THREE.Float32BufferAttribute(pts.flatMap((p) => p[1].toArray()), 3));
      const m = new THREE.PointsMaterial({ map: tex, size, vertexColors: true, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending, opacity: 0 });
      const o = new THREE.Points(g, m);
      o.frustumCulled = false;
      o.renderOrder = 5;
      return o;
    };
    const wp = [];
    for (let k = 0; k < 32; k++) {
      const a = ((k + 0.25) / 32) * Math.PI * 2;
      wp.push([[Math.sin(a) * 6.55, Math.cos(a) * 6.55, 0.4], cols[k % 4]]);
    }
    for (let k = 0; k < 16; k++) {
      const a = ((k + 0.5) / 16) * Math.PI * 2;
      wp.push([[Math.sin(a) * 4.6, Math.cos(a) * 4.6, 0.38], cols[0]]);
    }
    this.glowW = cloud(wp, 0.9);
    this.wheel.add(this.glowW);
    this.glowB = cloud([[[-3.6, 2.68, 5.7], cols[0]], [[3.6, 2.68, 5.7], cols[0]]], 2.2);
    this.root.add(this.glowB);
  }

  // the wheel's turn at time t (cabin i's pin sits at angle i*D + theta from the top, clockwise seen from the deck)
  thetaAt(t) {
    return (t % LOOP) * W_SPD;
  }
  // how far cabin i is past the bottom (the deck) at time t, -PI..PI rad
  offDeck(i, t = clock()) {
    return wrapPi(i * D + this.thetaAt(t) - Math.PI);
  }
  // the cabin passing the deck now with time left to hop in (-1 if none)
  boardCabin(t = clock()) {
    for (let i = 0; i < N; i++) {
      const d = this.offDeck(i, t);
      if (d > -WIN && d < WIN - 0.9 * W_SPD) return i;
    }
    return -1;
  }
  now() {
    return clock();
  }
  // you can hop out: your cabin is by the deck, on the pass you got in on or a whole turn later
  canLeave(i, t0, t = clock()) {
    return this.atDeck(i, t) && (t - t0 < 6 || t - t0 > LOOP / 2);
  }
  canBoard(t = clock()) {
    return this.boardCabin(t) >= 0;
  }
  // seconds till the next cabin reaches the deck
  untilStop(t = clock()) {
    if (this.canBoard(t)) return 0;
    let best = Infinity;
    for (let i = 0; i < N; i++) best = Math.min(best, (((-WIN - this.offDeck(i, t)) % TAU) + TAU) % TAU / W_SPD);
    return best;
  }
  // cabin i is by the deck (you can hop out)
  atDeck(i, t = clock()) {
    return Math.abs(this.offDeck(i, t)) < WIN;
  }
  // seconds till cabin i (boarded at t0) is back at the deck after its whole turn, and till it leaves the deck again
  rideLeft(i, t0, t = clock()) {
    return this.rideEnd(i, t0) - WIN / W_SPD - t;
  }
  rideEnd(i, t0) {
    // the bottom pass about one turn after boarding, then the end of that pass
    const back = t0 + LOOP - this.offDeck(i, t0) / W_SPD;
    return back + WIN / W_SPD;
  }
  pinLocal(i, out) {
    const a = i * D + this.theta;
    return out.set(Math.sin(a) * R, HUB + Math.cos(a) * R, PIN_Z);
  }
  // where seat s (0 left, 1 right) of cabin i is: the floor under the cushion, and the way it faces
  seatPose(i, s, out = new THREE.Vector3()) {
    this.pinLocal(i, out);
    const sx = s ? 0.27 : -0.27, w = this.sway || 0;
    out.x += sx * Math.cos(w) + FLOOR * Math.sin(w);
    out.y += sx * Math.sin(w) - FLOOR * Math.cos(w);
    out.z -= 0.36;
    return this.toWorld(out.x, out.y, out.z, out);
  }

  // the ride's camera, like the coaster's: your seat, behind the cabin, or from the meadow beside the wheel
  // (lookYaw / lookPitch: the drag, turning the view on the spot)
  static VIEWS = ["your seat 👀", "behind the cabin 🎡", "watching from the side 🎥"];
  view = 0;
  cycleView() {
    this.view = (this.view + 1) % Ferris.VIEWS.length;
    this.camQ = null;
    this.sideAim = null;
    return Ferris.VIEWS[this.view];
  }
  resetCam() {
    this.camQ = null;
    this.sideAim = null;
  }
  placeCamera(camera, i, s, lookYaw = 0, lookPitch = 0) {
    const dt = this.dt || 0.016;
    const Y = _Y;
    const fwd = _f.set(Math.sin(this.yaw), 0, Math.cos(this.yaw));
    const right = _r.set(-fwd.z, 0, fwd.x);
    const seat = this.seatPose(i, s, _p);
    let dir;
    if (this.view === 0) {
      // from your eyes on the cushion, out over the island
      camera.position.copy(seat).addScaledVector(fwd, 0.05);
      camera.position.y += FERRIS_SEAT_H + 0.72;
      dir = _d.copy(fwd).setY(-0.16).normalize().applyAxisAngle(right, lookPitch).applyAxisAngle(Y, lookYaw);
    } else if (this.view === 1) {
      // off the cabin's shoulder, just past its roof: you in your cabin and the island below
      // (a tall phone screen: further out and turned in across the cabin, so you stay in the narrow frame)
      const sd = s ? -1 : 1, tall = camera.aspect < 1;
      camera.position.copy(seat).addScaledVector(fwd, -0.9).addScaledVector(right, sd * (tall ? 2.4 : 1.85));
      camera.position.y += 2.0;
      dir = _d.copy(fwd).addScaledVector(right, -sd * (tall ? 1.5 : 0.42)).setY(-0.4).normalize().applyAxisAngle(right, lookPitch).applyAxisAngle(Y, lookYaw);
    } else {
      // out in the meadow off the deck's corner, the whole wheel in view, following your cabin round
      this.toWorld(-9, 5.5, 13, camera.position);
      const aim = _d.copy(seat).sub(camera.position).normalize();
      if (!this.sideAim) this.sideAim = aim.clone();
      else this.sideAim.lerp(aim, 1 - Math.exp(-dt * 10)).normalize();
      const rt = _r.crossVectors(this.sideAim, Y).normalize();
      dir = _d.copy(this.sideAim).applyAxisAngle(rt, lookPitch).applyAxisAngle(Y, lookYaw);
    }
    camera.up.set(0, 1, 0);
    camera.lookAt(_l.copy(camera.position).add(dir));
    const want = camera.quaternion.clone();
    if (!this.camQ) this.camQ = want;
    else this.camQ.slerp(want, 1 - Math.exp(-dt * 12));
    camera.quaternion.copy(this.camQ);
    return true;
  }

  update(dt, night = 0) {
    this.night = night;
    this.dt = dt;
    const t = clock();
    this.theta = this.thetaAt(t);
    // a breath of sway as the cabins ride round
    this.sway = Math.sin(t * 0.7) * 0.012;
    this.wheel.rotation.z = -this.theta;
    if (!this.ready) return;
    for (let i = 0; i < this.cabins.length; i++) {
      const c = this.cabins[i];
      this.pinLocal(i, c.position);
      c.rotation.z = this.sway;
    }
    const k = Math.min(1, night * 1.3);
    this.bulbMat.color.setScalar(0.92 + k * 0.9);
    if (this.glowW) {
      this.glowW.material.opacity = 0.85 * k;
      this.glowB.material.opacity = 0.9 * k;
      this.glowW.visible = this.glowB.visible = k > 0.02;
    }
  }
}

const _v = new THREE.Vector3();
const _Y = new THREE.Vector3(0, 1, 0), _f = new THREE.Vector3(), _r = new THREE.Vector3(), _p = new THREE.Vector3(), _d = new THREE.Vector3(), _l = new THREE.Vector3();
