// The avatar's and the cat's clip graphs (runtime-design §4): the behaviour state the game already has goes
// in, a pose comes out. No new gameplay state and no protocol change.
import { Animator, sampleInto, smooth01, mulberry, LookAt, SpringChain, STRIDE, isCalm, rotateRole } from "./runtime.js";

// ---- avatar ------------------------------------------------------------------------------------------------
const EMOTES = new Set(["wave", "heart", "hug", "kiss", "cuddle", "pet", "poop", "dance"]);
const KEEP_MOVING = new Set(["heart", "kiss"]); // (moving above 0.6 m/s cancels the others, as legacy)
const AV_IDLES = ["idle_breathe", "idle_look", "idle_shift"];
const AV_IDLE_W = [3, 2, 2];
const SIT_STATES = new Set(["sit_down", "sit_bench", "sit_swing"]);
const AV_SETTLE = new Set(["walk_stop", "land", "stand_up", "lie_up", "lounge_up", "floor_up"]);
// the rest families (scale.md "The avatar's new clips"): [down, loop, up]
const REST = { lie: ["lie_down", "lie_bed", "lie_up"], lounge: ["lounge_down", "lounge", "lounge_up"], floor: ["floor_down", "floor_sit", "floor_up"] };
const RIDES = new Set(["ride_kart", "ride_scooter", "ride_unicorn", "ride_unicorn_gait", "ride_unicorn_back"]);
// name -> [family, 0 down / 1 loop / 2 up] for every rest and ride clip
const SEATED = new Map();
for (const [f, l] of Object.entries(REST)) l.forEach((n, i) => SEATED.set(n, [f, i]));
for (const n of RIDES) SEATED.set(n, ["ride", 1]);
const SEAT_H = 0.45; // the sit clips' seat height

export class AvatarAnim {
  constructor(binding, seed = 1) {
    const lib = binding.lib;
    this.lib = lib;
    this.b = binding;
    this.an = new Animator(binding);
    this.loco = ["walk_slow", "walk", "run"].map((n) => ({ clip: lib.get(n), speed: lib.get(n).extras.tdd_speed * binding.k }));
    this.rng = mulberry(seed);
    this.blinkIn = 1.5;
    this.emote = null;
    this.pose = null;
    this.wasMoving = false;
    this.maxSpeed = 0;
    this.vs = 0; // the gait's speed, eased (blend weights and cadence never jump with a frame's speed)
    this.fallW = 0;
    this.seatW = 0;
    this.restW = 0;
    this.restRef = 0.45;
    this.restFam = "";
    this.hold = -1;
    this.aim = false;
    this.ri = (r) => lib.index.get(r) ?? -1;
    this.hips = this.ri("hips");
    this.head = this.ri("head");
    this.body = this.ri("body");
    this.sh = [this.ri("shoulder_0"), this.ri("shoulder_1")];
    this.look = new LookAt(0.7, 0.3, 2.5);
    this.tail = new SpringChain([this.ri("tail")], [3.2], 0.4, [0.08], 0.03);
    const rise = lib.get("air_rise");
    const fall = lib.get("air_fall");
    this.air = (P, w, l) => {
      this.fallW += ((l.vy < 0 ? Math.min(1, -l.vy / 5) : 0) - this.fallW) * 0.25;
      sampleInto(this.b, rise, l.t, P, w);
      sampleInto(this.b, fall, l.t, P, w * smooth01(this.fallW));
    };
    this.an.play("idle_breathe", 0);
  }

  // s: the avatar itself (speed, airborne, vy, landed, emote, pose, sitting, swingPhase, holdArm, aiming, ...)
  update(clock, s, near) {
    const dt = clock.dt;
    const an = this.an;
    const cur = an.current();
    const name = cur.name;
    const lib = this.lib;
    const moving = s.speed > 0.05;
    if (this.emote && !KEEP_MOVING.has(this.emote) && s.speed > 0.6) this.stopEmote();
    if (s.airborne) {
      const e = name === "@air" ? cur : an.play("@air", 0.1, this.air);
      e.vy = s.vy;
    } else if (s.landed) {
      an.play("land", 0.05);
    } else if (s.sitting && (s.riding || s.lying || s.lounge || s.floorSit) && s.swingPhase == null) {
      // in bed, on a sofa, on the floor, on a scooter or a unicorn (front or pillion): their own clips
      if (s.riding) {
        const want = s.kart && lib.get("ride_kart") ? "ride_kart" : (s.seatH || 0) > 1 ? (s.pillion ? "ride_unicorn_back" : s.ridePhase != null ? "ride_unicorn_gait" : "ride_unicorn") : "ride_scooter";
        if (want === "ride_unicorn_gait") {
          const e = name === want ? cur : an.play(want, 0.25, null, true);
          e.t = s.ridePhase * e.clip.duration;
        } else if (name !== want) an.play(want, name === "ride_unicorn_gait" ? 0.3 : 0.25);
        if (s.rideTurbo) {
          an.overlay("ride_scooter_turbo", true, 0.1, true, 0.25);
          s.rideTurbo = 0;
        }
      } else {
        const f = REST[s.lying ? "lie" : s.lounge ? "lounge" : "floor"];
        if (name !== f[0] && name !== f[1]) an.play(f[0], 0.15);
        else if (name === f[0] && cur.t >= cur.clip.duration - 0.1) an.play(f[1], 0.2);
      }
    } else if (s.sitting) {
      if (s.swingPhase != null) {
        const e = name === "sit_swing" ? cur : an.play("sit_swing", 0.45, null, true);
        e.t = s.swingPhase * e.clip.duration;
      } else if (name !== "sit_down" && name !== "sit_bench") an.play("sit_down", 0.12);
      else if (name === "sit_down" && cur.t >= cur.clip.duration - 0.1) an.play("sit_bench", 0.15);
    } else if (SIT_STATES.has(name)) {
      an.play("stand_up", 0.12);
    } else if (SEATED.has(name) && SEATED.get(name)[1] < 2) {
      // up out of a rest family through its own clip; off a ride straight into an idle
      const f = SEATED.get(name)[0];
      an.play(f === "ride" ? this.pickIdle("") : REST[f][2], 0.15);
    } else if (moving) {
      if (name !== "@loco" && !(name === "land" && cur.t < 0.15) && !(name === "stand_up" && cur.t < 0.3)) {
        // (eased in over a quarter second: a snap from the idle into the stride read as a jolt on video)
        an.play("@loco", name === "walk_stop" ? 0.25 : 0.24);
        if (!this.wasMoving) an.overlay("walk_start", true, 0.08, true, 0.12);
      }
      this.maxSpeed = Math.max(this.maxSpeed * Math.exp(-dt * 2), s.speed);
    } else if (name === "@loco") {
      // stopped: a planted stop step when really going, else settle into an idle
      if (this.maxSpeed > 1.0) an.play("walk_stop", 0.18);
      else an.play(this.pickIdle(""), 0.35);
      this.maxSpeed = 0;
    } else if (AV_SETTLE.has(name) && cur.t >= cur.clip.duration - 0.08) {
      an.play(this.pickIdle(""), 0.3);
    } else if (cur.clip && cur.clip.loop && name.startsWith("idle_") && cur.t >= cur.clip.duration - 0.4) {
      an.play(isCalm() ? "idle_breathe" : this.pickIdle(name), 0.6);
    } else if (name === "@air") {
      an.play(this.pickIdle(""), 0.2);
    }
    this.wasMoving = moving;
    // emotes and album poses: overlays; poses are held
    if (s.emote !== this.lastIn || s.emoteSeq !== this.seq) {
      this.lastIn = s.emote;
      this.seq = s.emoteSeq;
      if (s.emote && EMOTES.has(s.emote)) this.startEmote(s.emote);
      else if (!s.emote && this.emote) this.stopEmote();
    }
    const pose = s.pose || null;
    if (pose !== this.pose) {
      if (this.pose) an.overlay("pose_" + this.pose, false, 0.35);
      if (pose) an.overlay("pose_" + pose, true, 0.35, true, 0.3, true);
      this.pose = pose;
    }
    const hold = s.holdArm === 0 || s.holdArm === 1 ? s.holdArm : -1;
    if (hold !== this.hold) {
      an.overlay("hold_hand_0", hold === 0, 0.25);
      an.overlay("hold_hand_1", hold === 1, 0.25);
      this.hold = hold;
    }
    const aim = Boolean(s.aiming);
    if (aim !== this.aim) {
      an.overlay("aim", aim, 0.1);
      this.aim = aim;
    }
    this.blinkIn -= dt;
    if (this.blinkIn <= 0) {
      an.overlay("blink", true, 0.02, true, 0.02);
      this.blinkIn = 2 + this.rng() * 3;
    }
    // (eased toward the real speed: walk <-> run blends over ~0.3 s, a stop winds the cadence down)
    this.vs += (s.speed - this.vs) * (1 - Math.exp(-dt * (s.speed > this.vs ? 7 : 9)));
    if (!moving && this.vs < 0.05) this.vs = 0;
    const P = an.update(dt, this.vs, this.loco);
    // the sit clips are authored for a 0.45 m seat: the hips follow the real one. The clip's hips come scaled by the
    // body (k: a smaller avatar's seat of the pants sits at 0.45 k), so the offset is from 0.45 k, not 0.45 (it sank a
    // small avatar into the seat and lifted a tall one off it)
    const c = an.current();
    const sw = c.name === "sit_bench" || c.name === "sit_swing" ? 1 : c.name === "sit_down" ? smooth01(c.t / c.clip.duration) : c.name === "stand_up" ? 1 - smooth01(c.t / c.clip.duration) : 0;
    this.seatW += (sw - this.seatW) * Math.min(1, dt * 14);
    if (this.hips >= 0 && this.seatW > 0.001) P[this.hips * STRIDE + 1] += ((s.seatH ?? SEAT_H) - SEAT_H * this.b.k) * this.seatW;
    // the rest and ride clips carry their own seat height (tdd_seat_h): the real one moves the hips, in bed
    // the body; the part above the seat scales with the body (k), the seat itself does not
    const st = SEATED.get(c.name);
    const rw = !st ? 0 : st[1] === 1 ? 1 : st[1] === 0 ? smooth01(c.t / c.clip.duration) : 1 - smooth01(c.t / c.clip.duration);
    this.restW += (rw - this.restW) * Math.min(1, dt * 14);
    if (this.restW > 0.001 && st) this.restRef = c.clip.extras.tdd_seat_h ?? this.restRef;
    if (st) this.restFam = st[0];
    if (this.restW > 0.001) {
      const k = this.b.k;
      const lie = this.restFam === "lie";
      const ri = lie ? this.body : this.hips;
      const h = s.seatH ?? (lie ? 0.7 : this.restRef);
      if (ri >= 0) P[ri * STRIDE + 1] += (h - this.restRef * k + (lie ? 0.13 * (1 - k) : 0)) * this.restW;
      // the snuggle roll toward the other one stays a runtime offset on the body
      const sn = this.pose === "snuggleR" ? 1 : this.pose === "snuggleL" ? -1 : 0;
      if (lie && sn && this.body >= 0) rotateRole(P, this.body, 0, -sn * 0.55 * this.restW * this.an.overlayW("pose_" + this.pose), 0);
    }
    // aim: the pitch stays an additive shoulder offset
    const aw = an.overlayW("aim");
    if (aw > 0.001) {
      const ap = -(s.aimPitch || 0) * aw;
      rotate(P, this.sh[0], ap);
      rotate(P, this.sh[1], ap);
    }
    if (near) {
      const idle = c.name.startsWith("idle_") || c.name === "sit_bench";
      this.look.update(clock, s.lookYaw || 0, s.lookPitch || 0, Boolean(s.lookOn) && idle && !this.emote && !this.pose);
      this.look.apply(P, this.head);
      if (s.bunnyTail && this.tail.ris[0] >= 0) {
        this.tail.update(clock, s.yawRate || 0, 0);
        this.tail.apply(P);
      }
    }
    return P;
  }
  // how much of an emote or pose shows (the face squints in some)
  emoteW() {
    return this.emote ? this.an.overlayW(this.emote) : this.pose ? this.an.overlayW("pose_" + this.pose) : 0;
  }
  startEmote(n) {
    if (this.emote) this.an.overlay(this.emote, false, 0.15);
    this.emote = n;
    this.an.overlay(n, true, 0.12, true, 0.3);
  }
  stopEmote() {
    this.an.overlay(this.emote, false, 0.3);
    this.emote = null;
  }
  pickIdle(not) {
    let tot = 0;
    for (let i = 0; i < AV_IDLES.length; i++) if (AV_IDLES[i] !== not) tot += AV_IDLE_W[i];
    let r = this.rng() * tot;
    for (let i = 0; i < AV_IDLES.length; i++) {
      if (AV_IDLES[i] === not) continue;
      if ((r -= AV_IDLE_W[i]) <= 0) return AV_IDLES[i];
    }
    return "idle_breathe";
  }
}
function rotate(P, ri, x) {
  if (ri < 0) return;
  // (about the shoulder's own x: a small-angle quaternion product, no Euler)
  const o = ri * STRIDE;
  const h = x * 0.5;
  const s = Math.sin(h);
  const c = Math.cos(h);
  const qx = P[o + 3];
  const qy = P[o + 4];
  const qz = P[o + 5];
  const qw = P[o + 6];
  P[o + 3] = qx * c + qw * s;
  P[o + 4] = qy * c + qz * s;
  P[o + 5] = qz * c - qy * s;
  P[o + 6] = qw * c - qx * s;
}

// ---- cat ---------------------------------------------------------------------------------------------------
const CAT_IDLES = ["idle_breathe", "idle_look", "idle_tailflick"];
const CAT_IDLE_W = [3, 2, 1];
const CAT_NEXT = { sit_down: "sit_loop", lie_down: "lie_loop", roll_over: "belly_loop", stand_up: "idle_breathe", stretch: "idle_breathe" };
const SIT_FAMILY = new Set(["sit_down", "sit_loop", "groom"]);
const LIE_FAMILY = new Set(["lie_down", "lie_loop", "sleep_loop"]);

export class CatAnim {
  constructor(binding, seed = 1) {
    const lib = binding.lib;
    this.lib = lib;
    this.an = new Animator(binding);
    this.loco = [
      { clip: lib.get("walk"), speed: lib.get("walk").extras.tdd_speed },
      { clip: lib.get("run"), speed: lib.get("run").extras.tdd_speed },
    ];
    this.look = new LookAt(0.8, 0.35, 2.2);
    this.head = lib.index.get("head") ?? -1;
    this.tail = new SpringChain(["tail_0", "tail_1", "tail_2", "tail_3"].map((r) => lib.index.get(r) ?? -1), [4.5, 3.6, 3.0, 2.5], 0.4, [0.05, 0.07, 0.09, 0.11], 0.015);
    this.rng = mulberry(seed);
    this.settle = 0;
    this.inPose = 0;
    this.lastPose = "";
    this.lastSpeed = 0;
    this.an.play("idle_breathe", 0);
  }
  // s: { speed, mode, pose, happy, stay, yawRate, lookYaw, lookPitch, lookOn }
  update(clock, s, near) {
    const dt = clock.dt;
    const an = this.an;
    const cur = an.current();
    const name = cur.name;
    const moving = s.speed > 0.08 || s.mode === "walk" || s.mode === "run" || s.mode === "flee";
    if (moving) {
      if (name !== "@loco") an.play("@loco", LIE_FAMILY.has(name) || name === "belly_loop" ? 0.4 : SIT_FAMILY.has(name) ? 0.3 : 0.18);
      this.settle = 0;
      this.inPose = 0;
    } else {
      const want = s.pose || "";
      if (want !== this.lastPose) {
        this.inPose = 0;
        this.lastPose = want;
      }
      this.inPose += dt;
      const next = CAT_NEXT[name];
      if (next && cur.t >= cur.clip.duration - 0.12) an.play(next, 0.15);
      else if (want === "belly") {
        if (name !== "roll_over" && name !== "belly_loop") an.play("roll_over", 0.15);
      } else if (want === "loaf") {
        if (!LIE_FAMILY.has(name)) an.play("lie_down", 0.2);
        else if (name === "lie_loop" && this.inPose > 6) an.play("sleep_loop", 1.5);
      } else if (want === "stretch") {
        if (name !== "stretch") an.play("stretch", 0.25);
      } else if (want === "groom") {
        if (!SIT_FAMILY.has(name)) an.play("sit_down", 0.2);
        else if (name === "sit_loop") an.play("groom", 0.35);
      } else if (name === "@loco") {
        this.settle = 0.7 + this.rng() * 0.5;
        an.play(isCalm() ? "idle_breathe" : this.pickIdle(), 0.22);
      } else if (name === "groom") an.play("sit_loop", 0.35);
      else if (LIE_FAMILY.has(name) || name === "belly_loop") an.play("stand_up", 0.35);
      else if (name === "sit_loop" && !s.stay) an.play("stand_up", 0.3);
      else if (name.startsWith("idle_")) {
        // (W16: a pet stands on its four feet; it sits when told to stay, and otherwise changes idles now and then)
        this.settle -= dt;
        if (this.settle <= 0) {
          if (s.stay) an.play("sit_down", 0.2);
          else {
            this.settle = 4 + this.rng() * 5;
            const next = isCalm() ? "idle_breathe" : this.pickIdle();
            if (next !== name) an.play(next, 0.45);
          }
        }
      }
    }
    an.overlay("happy", s.happy > 0 && s.pose !== "belly", 0.35);
    const P = an.update(dt, s.speed, this.loco);
    if (near && dt > 0) {
      const accel = (s.speed - this.lastSpeed) / dt;
      this.tail.update(clock, s.yawRate || 0, Math.max(-20, Math.min(20, accel)));
      this.tail.apply(P);
      const c = an.current().name;
      this.look.update(clock, s.lookYaw || 0, s.lookPitch || 0, Boolean(s.lookOn) && !moving && (c.startsWith("idle_") || c === "sit_loop"));
      this.look.apply(P, this.head);
    }
    this.lastSpeed = s.speed;
    return P;
  }
  pickIdle() {
    let r = this.rng() * 6;
    for (let i = 0; i < CAT_IDLES.length; i++) if ((r -= CAT_IDLE_W[i]) <= 0) return CAT_IDLES[i];
    return CAT_IDLES[0];
  }
}
