// Contact shade (look pass, VISUAL-TECH-SPEC §R): the soft darkening where things meet the ground,
// painted in the theme's shade colour rather than grey, as in the references (ref 1, 6, 13). No
// screen-space ambient occlusion (phones can't afford it): one soft decal flat on the ground under
// every tree, post, rock, prop and pillar, and a soft ring round the foot of every building. All of
// them in one draw, on every tier.
//
// Where they go is read from the world, never listed: its colliders (`circles`: trunks, posts,
// rocks, props; `solids` standing on the ground; the round and box-shaped buildings in `rooms`).
// The decals multiply what is under them; nothing in the world changes.
import * as THREE from "three";

const LIFT = 0.09; // m above the ground (the plazas' inlays sit up to 8 cm high)

export class ContactShade {
  constructor(scene) {
    this.scene = scene;
    this.mesh = null;
    this.count = 0;
    this.uniforms = {
      uTint: { value: new THREE.Color(0.5, 0.45, 0.6) },
      uStrength: { value: 1 },
      uFade: { value: new THREE.Vector2(30, 160) },
      uEncoded: { value: 0 },
    };
  }

  // once everything is built (before the shaders are compiled). encoded: drawn straight onto the
  // canvas (its colours are already sRGB there: the multiplier is matched to that)
  build(world, { islandR = 84, encoded = false } = {}) {
    const list = [];
    const R = islandR - 1;
    const inIsland = (x, z) => Math.hypot(x, z) < R;
    // posts, trunks, rocks, props: a soft patch round each
    for (const c of world.circles || []) {
      if (!(c.r >= 0.12) || !inIsland(c.x, c.z) || c.r > 3) continue;
      list.push([c.x, c.z, c.r * 0.7, c.r * 0.7, 0, 0, c.r * 2.2 + 0.45, Math.min(0.7, 0.42 + c.r * 0.25), 0]);
    }
    // pillars and trunks standing on the ground (the stacked ones above them are skipped)
    const seen = new Set();
    for (const s of world.solids || []) {
      if (s.type && s.type !== "cyl") continue;
      if (!(s.bottom <= 0.05) || !inIsland(s.x, s.z) || !(s.r > 0.1) || s.r > 4) continue;
      const k = `${s.x.toFixed(2)},${s.z.toFixed(2)}`;
      if (seen.has(k)) continue;
      seen.add(k);
      list.push([s.x, s.z, s.r * 0.8, s.r * 0.8, 0, 0, s.r * 0.8 + 0.5, 0.5, 0]);
    }
    // the foot of every building: a ring outside its walls (nothing inside, on its floor)
    for (const room of world.rooms?.values?.() || []) {
      const d = room.def || {};
      const p = room.group?.position;
      if (!p || !inIsland(p.x, p.z)) continue;
      const rotY = room.group.rotation?.y || 0;
      if ((d.kind === "pavilion" || d.kind === "tower") && room.radius > 1) {
        const r = room.radius;
        list.push([p.x, p.z, r, r, 0, 0, 1.1 + r * 0.12, 0.5, 1]);
      } else if ((d.kind === "bakery" || d.kind === "hall") && room.rect) {
        list.push([p.x, p.z, room.rect.w / 2, room.rect.d / 2, rotY, 1, 1.3, 0.5, 1]);
      }
    }
    const n = list.length;
    this.count = n;
    const geo = new THREE.InstancedBufferGeometry();
    geo.setAttribute("position", new THREE.Float32BufferAttribute([-1, 0, -1, 1, 0, -1, 1, 0, 1, -1, 0, 1], 3));
    geo.setIndex([0, 2, 1, 0, 3, 2]);
    const aPos = new Float32Array(n * 3);
    const aBox = new Float32Array(n * 4);
    const aFall = new Float32Array(n * 4);
    list.forEach(([x, z, hx, hz, rot, box, fall, str, hole], i) => {
      aPos.set([x, LIFT, z], i * 3);
      aBox.set([hx, hz, rot, box], i * 4);
      aFall.set([fall, str, hole, 0], i * 4);
    });
    geo.setAttribute("aPos", new THREE.InstancedBufferAttribute(aPos, 3));
    geo.setAttribute("aBox", new THREE.InstancedBufferAttribute(aBox, 4));
    geo.setAttribute("aFall", new THREE.InstancedBufferAttribute(aFall, 4));
    geo.instanceCount = n;
    this.uniforms.uEncoded.value = encoded ? 1 : 0;
    const mat = new THREE.ShaderMaterial({
      name: "LookContactShade",
      uniforms: this.uniforms,
      transparent: true,
      depthWrite: false,
      toneMapped: false,
      vertexShader: /* glsl */ `
        attribute vec3 aPos;
        attribute vec4 aBox;  // half width, half depth, turn, box (1) or round (0)
        attribute vec4 aFall; // how far it fades out, strength, hollow inside (a building)
        varying vec2 vLocal;
        varying vec4 vBox;
        varying vec4 vFall;
        varying float vDist;
        void main() {
          vec2 ext = aBox.xy + aFall.x;
          vec2 l = position.xz * ext;
          float c = cos( aBox.z ), s = sin( aBox.z );
          vec3 p = aPos + vec3( c * l.x + s * l.y, 0.0, -s * l.x + c * l.y );
          vLocal = l;
          vBox = aBox;
          vFall = aFall;
          vec4 mv = modelViewMatrix * vec4( p, 1.0 );
          vDist = length( mv.xyz );
          gl_Position = projectionMatrix * mv;
        }`,
      fragmentShader: /* glsl */ `
        uniform vec3 uTint;
        uniform float uStrength;
        uniform vec2 uFade;
        uniform float uEncoded;
        varying vec2 vLocal;
        varying vec4 vBox;
        varying vec4 vFall;
        varying float vDist;
        void main() {
          float d;
          if ( vBox.w > 0.5 ) {
            vec2 q = abs( vLocal ) - vBox.xy;
            d = length( max( q, 0.0 ) ) + min( max( q.x, q.y ), 0.0 );
          } else d = length( vLocal ) - vBox.x;
          float a = 1.0 - smoothstep( 0.0, vFall.x, d );
          // (a building's ring: nothing on its own floor)
          if ( vFall.z > 0.5 ) a *= smoothstep( -0.4, 0.0, d );
          a = min( pow( a, 1.6 ) * vFall.y * uStrength * ( 1.0 - smoothstep( uFade.x, uFade.y, vDist ) ), 0.9 );
          if ( a < 0.004 ) discard;
          vec3 f = mix( vec3( 1.0 ), uTint, a );
          if ( uEncoded > 0.5 ) f = pow( f, vec3( 1.0 / 2.2 ) );
          gl_FragColor = vec4( f, 1.0 );
        }`,
    });
    // (multiplies what is under it; the picture's alpha is left as it is)
    mat.blending = THREE.CustomBlending;
    mat.blendSrc = THREE.ZeroFactor;
    mat.blendDst = THREE.SrcColorFactor;
    mat.blendSrcAlpha = THREE.ZeroFactor;
    mat.blendDstAlpha = THREE.OneFactor;
    const mesh = new THREE.Mesh(geo, mat);
    mesh.name = "look.contactShade";
    mesh.frustumCulled = false;
    mesh.renderOrder = -1;
    mesh.matrixAutoUpdate = false;
    mesh.raycast = () => {};
    mesh.__noBake = true;
    mesh.userData.keepDetail = true;
    this.mesh = mesh;
    this.scene.add(mesh);
    return n;
  }

  // the theme's shade colour, how strong, and how far before the haze takes it
  set(tint, strength, fogNear, fogFar) {
    this.uniforms.uTint.value.copy(tint);
    this.uniforms.uStrength.value = strength;
    this.uniforms.uFade.value.set(Math.max(20, fogNear + 10), Math.max(60, fogFar * 0.55));
    if (this.mesh) this.mesh.visible = strength > 0.001 && this.count > 0;
  }

  dispose() {
    if (!this.mesh) return;
    this.mesh.removeFromParent();
    this.mesh.geometry.dispose();
    this.mesh.material.dispose();
    this.mesh = null;
  }
}
