// Remote players, buffered (runtime-design §7): every packet is stamped on arrival (no protocol change) and
// the body is drawn about 100 ms behind (150 ms when the arrival jitter is over 30 ms), on a cubic Hermite
// through the bracketing snapshots with Catmull-Rom tangents; facing takes the shortest arc. A dry buffer
// extrapolates at the last velocity for at most 150 ms, then holds; a jump of more than 8 m snaps.
// The clips are driven by the speed of the drawn body, never by the packet's stepwise speed.
const N = 10;
const SEND_MS = 100;

export class SnapBuffer {
  constructor(x, y, z, f) {
    this.s = [];
    for (let i = 0; i < N; i++) this.s.push({ t: 0, x: 0, y: 0, z: 0, f: 0, a: false });
    this.n = 0; // snapshots held (oldest first, ring from `head`)
    this.head = 0;
    this.jitter = 0;
    this.lastT = 0;
    this.px = x;
    this.py = y;
    this.pz = z;
    this.speed = 0;
    this.vy = 0;
    this.air = false;
    this.push(performance.now(), x, y, z, f, false);
  }
  at(i) {
    return this.s[(this.head + i) % N];
  }
  push(t, x, y, z, f, a) {
    if (this.n) {
      const l = this.at(this.n - 1);
      const gap = t - l.t;
      this.jitter += (Math.abs(gap - SEND_MS) - this.jitter) * 0.1;
      if (Math.hypot(x - l.x, z - l.z) > 8) this.n = 0; // (a teleport: start over)
    }
    if (this.n === N) {
      this.head = (this.head + 1) % N;
      this.n--;
    }
    const e = this.s[(this.head + this.n) % N];
    e.t = t;
    e.x = x;
    e.y = y;
    e.z = z;
    e.f = f;
    e.a = Boolean(a);
    this.n++;
  }
  // the drawn state at `now` into out (a Vector3) and returns the facing
  sample(now, dt, out) {
    const T = now - (this.jitter > 30 ? 150 : SEND_MS);
    let f;
    const n = this.n;
    const last = this.at(n - 1);
    if (n === 1 || T <= this.at(0).t) {
      const e = n === 1 ? last : this.at(0);
      out.set(e.x, e.y, e.z);
      f = e.f;
      this.air = e.a;
    } else if (T >= last.t) {
      // dry: extrapolate at the last velocity for at most 150 ms, then hold
      const p = this.at(n - 2);
      const span = Math.max(1, last.t - p.t);
      const k = Math.min(T - last.t, 150) / span;
      out.set(last.x + (last.x - p.x) * k, last.y + (last.y - p.y) * k, last.z + (last.z - p.z) * k);
      f = last.f;
      this.air = last.a;
    } else {
      let i = 0;
      while (i < n - 2 && this.at(i + 1).t <= T) i++;
      const s1 = this.at(i);
      const s2 = this.at(i + 1);
      const s0 = i > 0 ? this.at(i - 1) : s1;
      const s3 = i + 2 < n ? this.at(i + 2) : s2;
      const h = Math.max(1, s2.t - s1.t);
      const u = (T - s1.t) / h;
      const u2 = u * u;
      const u3 = u2 * u;
      const h00 = 2 * u3 - 3 * u2 + 1;
      const h10 = u3 - 2 * u2 + u;
      const h01 = -2 * u3 + 3 * u2;
      const h11 = u3 - u2;
      const k1 = h / Math.max(1, s2.t - s0.t);
      const k2 = h / Math.max(1, s3.t - s1.t);
      out.set(
        h00 * s1.x + h10 * (s2.x - s0.x) * k1 + h01 * s2.x + h11 * (s3.x - s1.x) * k2,
        h00 * s1.y + h10 * (s2.y - s0.y) * k1 + h01 * s2.y + h11 * (s3.y - s1.y) * k2,
        h00 * s1.z + h10 * (s2.z - s0.z) * k1 + h01 * s2.z + h11 * (s3.z - s1.z) * k2,
      );
      const d = Math.atan2(Math.sin(s2.f - s1.f), Math.cos(s2.f - s1.f));
      f = s1.f + d * u;
      this.air = s1.a || s2.a;
    }
    // the speed and the vertical speed of the drawn body (damped at 12/s)
    if (dt > 0) {
      const v = Math.hypot(out.x - this.px, out.z - this.pz) / dt;
      const k = 1 - Math.exp(-dt * 12);
      this.speed += (Math.min(v, 30) - this.speed) * k;
      this.vy += ((out.y - this.py) / dt - this.vy) * k;
    }
    this.px = out.x;
    this.py = out.y;
    this.pz = out.z;
    return f;
  }
}
