// The clip runtime (rebuild/reports/animation/runtime-design.md): no AnimationMixer, no PropertyBinding,
// nothing allocated per frame. The clip carriers (chr_avatar_clips, ani_pet_cat_clips) are sampled once
// into flat 30 Hz tables per role; a pose is a struct of arrays (10 floats per role: t3 q4 s3); states
// crossfade by weight, locomotion is one blend space with one phase, overlays are masked by authoring.
//   ClipLib.fromGLTF(gltf, asset)    the carrier's clips by role (extras from parser.json: r170 drops them)
//   RigBinding(nodes, lib)           role -> Object3D (null: role absent, skipped) and its rest pose
//   sampleInto(lib, clip, t, pose, w, full)
//   Animator                         states + crossfades + "@loco" blend space + overlays
//   LookAt, SpringChain              damped look-at and springs on fixed 1/120 s sub-steps
//   AnimClock                        dt clamp (0.1 s) + sub-step count
import * as THREE from "three";

export const STRIDE = 10;
const _q0 = new THREE.Quaternion();
const _q1 = new THREE.Quaternion();
const _e = new THREE.Euler();

// ---- reduced motion (prefers-reduced-motion): idles breathe only, no springs, no look-at -----------------
let calm = false;
export const setCalm = (on) => (calm = Boolean(on));
export const isCalm = () => calm;

// ---- clips ------------------------------------------------------------------------------------------------
export class ClipLib {
  static fromGLTF(gltf, asset) {
    const lib = new ClipLib();
    lib.asset = asset;
    const pre = "ANIM_" + asset + "_";
    const nodes = [];
    gltf.scene.traverse((o) => o.name.startsWith(pre) && nodes.push(o));
    lib.roles = nodes.map((o) => o.name.slice(pre.length));
    lib.index = new Map(lib.roles.map((r, i) => [r, i]));
    lib.rest = new Float32Array(lib.roles.length * STRIDE);
    nodes.forEach((o, i) => writeTRS(lib.rest, i, o.position, o.quaternion, o.scale));
    lib.clips = new Map();
    const js = gltf.parser?.json?.animations || [];
    gltf.animations.forEach((a, k) => {
      const ex = js[k]?.extras || {};
      const c = { name: a.name, duration: a.duration, loop: Boolean(ex.tdd_loop), extras: ex, fps: 30, tracks: [] };
      for (const tr of a.tracks) {
        const dot = tr.name.lastIndexOf(".");
        const role = tr.name.slice(0, dot).slice(pre.length);
        const prop = tr.name.slice(dot + 1);
        const ri = lib.index.get(role);
        if (ri === undefined) continue;
        const kind = prop === "position" ? 0 : prop === "quaternion" ? 1 : 2;
        const size = kind === 1 ? 4 : 3;
        const n = Math.max(1, Math.round(a.duration * c.fps) + 1);
        const data = new Float32Array(n * size);
        const interp = tr.createInterpolant();
        for (let i = 0; i < n; i++) {
          const r = interp.evaluate(Math.min(a.duration, i / c.fps));
          for (let j = 0; j < size; j++) data[i * size + j] = r[j];
          if (kind === 1) {
            _q0.fromArray(data, i * 4).normalize();
            if (i && _q0.dot(_q1.fromArray(data, (i - 1) * 4)) < 0) _q0.set(-_q0.x, -_q0.y, -_q0.z, -_q0.w);
            _q0.toArray(data, i * 4);
          }
        }
        c.tracks.push({ ri, kind, n, data });
      }
      // channel groups the clip leaves at rest (full-body states pull them back to rest)
      const cover = new Uint8Array(lib.roles.length * 3);
      for (const tr of c.tracks) cover[tr.ri * 3 + tr.kind] = 1;
      const un = [];
      for (let ri = 0; ri < lib.roles.length; ri++) for (let g = 0; g < 3; g++) if (!cover[ri * 3 + g]) un.push(ri * STRIDE + (g === 0 ? 0 : g === 1 ? 3 : 7), g);
      c.uncovered = Int32Array.from(un);
      c.full = (ex.tdd_kind || "") !== "layer";
      lib.clips.set(a.name, c);
    });
    return lib;
  }
  get(name) {
    return this.clips.get(name) || null;
  }
}

function writeTRS(a, i, p, q, s) {
  const o = i * STRIDE;
  a[o] = p.x;
  a[o + 1] = p.y;
  a[o + 2] = p.z;
  a[o + 3] = q.x;
  a[o + 4] = q.y;
  a[o + 5] = q.z;
  a[o + 6] = q.w;
  a[o + 7] = s.x;
  a[o + 8] = s.y;
  a[o + 9] = s.z;
}

// ---- binding: role -> node of a mesh rig, and its rest pose -----------------------------------------------
// get(role) -> Object3D | null. Translations are rest-relative and scaled by k = this body's hips (or body)
// height over the carrier's, so one clip drives every body (runtime-design §1).
export class RigBinding {
  constructor(lib, get, scaleRole = null) {
    this.lib = lib;
    const n = lib.roles.length;
    this.nodes = lib.roles.map((r) => get(r) || null);
    this.rest = new Float32Array(n * STRIDE);
    for (let i = 0; i < n; i++) {
      const o = this.nodes[i];
      const r = o?.userData.restTRS;
      if (r) this.rest.set(r, i * STRIDE);
      else if (o) writeTRS(this.rest, i, o.position, o.quaternion, o.scale);
      else this.rest.set(lib.rest.subarray(i * STRIDE, i * STRIDE + STRIDE), i * STRIDE);
    }
    this.k = 1;
    const si = scaleRole ? lib.index.get(scaleRole) : undefined;
    if (si !== undefined && this.nodes[si]) {
      const c = lib.rest[si * STRIDE + 1];
      if (Math.abs(c) > 1e-3) this.k = this.rest[si * STRIDE + 1] / c;
    }
  }
  newPose() {
    const p = new Float32Array(this.rest.length);
    p.set(this.rest);
    return p;
  }
  // a pose onto the nodes (quaternion fields written directly: no Euler round trip per joint)
  apply(pose) {
    const N = this.nodes;
    for (let i = 0; i < N.length; i++) {
      const o = N[i];
      if (!o) continue;
      const k = i * STRIDE;
      o.position.x = pose[k];
      o.position.y = pose[k + 1];
      o.position.z = pose[k + 2];
      const q = o.quaternion;
      q._x = pose[k + 3];
      q._y = pose[k + 4];
      q._z = pose[k + 5];
      q._w = pose[k + 6];
      o.scale.x = pose[k + 7];
      o.scale.y = pose[k + 8];
      o.scale.z = pose[k + 9];
    }
  }
  // the nodes' current transforms into a pose (to crossfade from a procedural owner)
  read(pose) {
    const N = this.nodes;
    for (let i = 0; i < N.length; i++) if (N[i]) writeTRS(pose, i, N[i].position, N[i].quaternion, N[i].scale);
  }
}

// blend pose b into a by w (nlerp for rotations)
export function blendPose(a, b, w) {
  if (w <= 0) return;
  for (let o = 0; o < a.length; o += STRIDE) {
    for (let j = 0; j < 3; j++) a[o + j] += (b[o + j] - a[o + j]) * w;
    for (let j = 7; j < 10; j++) a[o + j] += (b[o + j] - a[o + j]) * w;
    const s = a[o + 3] * b[o + 3] + a[o + 4] * b[o + 4] + a[o + 5] * b[o + 5] + a[o + 6] * b[o + 6] < 0 ? -1 : 1;
    let l = 0;
    for (let j = 3; j < 7; j++) {
      a[o + j] += (s * b[o + j] - a[o + j]) * w;
      l += a[o + j] * a[o + j];
    }
    l = 1 / Math.sqrt(l || 1);
    for (let j = 3; j < 7; j++) a[o + j] *= l;
  }
}

// sample `clip` at time t into `pose` with weight w. full: the channel groups it does not key go to rest.
export function sampleInto(binding, clip, t, pose, w = 1, full = clip.full) {
  if (w <= 0 || !clip) return;
  const d = clip.duration;
  if (clip.loop && d > 0) t = ((t % d) + d) % d;
  else t = t < 0 ? 0 : t > d ? d : t;
  const f = t * clip.fps;
  const fi = f | 0;
  const u = f - fi;
  const R = binding.rest;
  const C = binding.lib.rest;
  const k = binding.k;
  const a = pose;
  if (full) {
    const U = clip.uncovered;
    for (let i = 0; i < U.length; i += 2) {
      const o = U[i];
      if (U[i + 1] === 1) {
        const s = a[o] * R[o] + a[o + 1] * R[o + 1] + a[o + 2] * R[o + 2] + a[o + 3] * R[o + 3] < 0 ? -1 : 1;
        let l = 0;
        for (let j = 0; j < 4; j++) {
          a[o + j] += (s * R[o + j] - a[o + j]) * w;
          l += a[o + j] * a[o + j];
        }
        l = 1 / Math.sqrt(l || 1);
        for (let j = 0; j < 4; j++) a[o + j] *= l;
      } else for (let j = 0; j < 3; j++) a[o + j] += (R[o + j] - a[o + j]) * w;
    }
  }
  const T = clip.tracks;
  for (let n = 0; n < T.length; n++) {
    const tr = T[n];
    const i0 = fi < tr.n - 1 ? fi : tr.n - 1;
    const i1 = i0 + 1 < tr.n ? i0 + 1 : i0;
    const o = tr.ri * STRIDE;
    const D = tr.data;
    if (tr.kind === 1) {
      const p = i0 * 4;
      const q = i1 * 4;
      let x = D[p] + (D[q] - D[p]) * u;
      let y = D[p + 1] + (D[q + 1] - D[p + 1]) * u;
      let z = D[p + 2] + (D[q + 2] - D[p + 2]) * u;
      let ww = D[p + 3] + (D[q + 3] - D[p + 3]) * u;
      if (w < 1) {
        const s = a[o + 3] * x + a[o + 4] * y + a[o + 5] * z + a[o + 6] * ww < 0 ? -1 : 1;
        x = a[o + 3] + (s * x - a[o + 3]) * w;
        y = a[o + 4] + (s * y - a[o + 4]) * w;
        z = a[o + 5] + (s * z - a[o + 5]) * w;
        ww = a[o + 6] + (s * ww - a[o + 6]) * w;
      }
      const l = 1 / Math.sqrt(x * x + y * y + z * z + ww * ww || 1);
      a[o + 3] = x * l;
      a[o + 4] = y * l;
      a[o + 5] = z * l;
      a[o + 6] = ww * l;
    } else {
      const off = tr.kind === 0 ? 0 : 7;
      const p = i0 * 3;
      const q = i1 * 3;
      for (let j = 0; j < 3; j++) {
        let v = D[p + j] + (D[q + j] - D[p + j]) * u;
        if (tr.kind === 0) v = R[o + j] + (v - C[o + j]) * k;
        a[o + off + j] += (v - a[o + off + j]) * w;
      }
    }
  }
}

// ---- helpers ----------------------------------------------------------------------------------------------
export const smooth01 = (x) => (x <= 0 ? 0 : x >= 1 ? 1 : x * x * (3 - 2 * x));
export function mulberry(a) {
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// post-rotate one role of a pose by Euler (x, y, z) (look-at, springs, the aim offset)
export function rotateRole(pose, ri, x, y, z, order = "XYZ") {
  if (ri == null || ri < 0 || Math.abs(x) + Math.abs(y) + Math.abs(z) < 1e-5) return;
  const o = ri * STRIDE;
  _q0.set(pose[o + 3], pose[o + 4], pose[o + 5], pose[o + 6]);
  _q1.setFromEuler(_e.set(x, y, z, order));
  _q0.multiply(_q1);
  pose[o + 3] = _q0.x;
  pose[o + 4] = _q0.y;
  pose[o + 5] = _q0.z;
  pose[o + 6] = _q0.w;
}

// ---- clock: dt clamped at 0.1 s (true time down to 10 fps), springs on fixed 1/120 s sub-steps ----------
export class AnimClock {
  constructor(maxDt = 0.1, step = 1 / 120) {
    this.maxDt = maxDt;
    this.h = step;
    this.acc = 0;
    this.dt = 0;
    this.steps = 0;
  }
  tick(raw) {
    const dt = raw > this.maxDt ? this.maxDt : raw > 0 ? raw : 0;
    this.dt = dt;
    this.acc += dt;
    let n = 0;
    while (this.acc >= this.h && n < 24) {
      this.acc -= this.h;
      n++;
    }
    if (n === 24) this.acc = 0;
    this.steps = n;
    return this;
  }
}

// ---- damped look-at (second order, clamped), a post-rotation on the head -----------------------------------
export class LookAt {
  constructor(maxYaw = 0.9, maxPitch = 0.4, freq = 3) {
    this.maxYaw = maxYaw;
    this.maxPitch = maxPitch;
    this.w = 2 * Math.PI * freq;
    this.yaw = 0;
    this.pitch = 0;
    this.vy = 0;
    this.vp = 0;
  }
  update(clock, yaw, pitch, on) {
    if (calm) on = false;
    const ty = on ? Math.max(-this.maxYaw, Math.min(this.maxYaw, yaw)) : 0;
    const tp = on ? Math.max(-this.maxPitch, Math.min(this.maxPitch, pitch)) : 0;
    const w = this.w;
    const h = clock.h;
    for (let i = 0; i < clock.steps; i++) {
      this.vy += (w * w * (ty - this.yaw) - 2 * w * this.vy) * h;
      this.yaw += this.vy * h;
      this.vp += (w * w * (tp - this.pitch) - 2 * w * this.vp) * h;
      this.pitch += this.vp * h;
    }
  }
  apply(pose, ri) {
    rotateRole(pose, ri, this.pitch, this.yaw, 0, "YXZ");
  }
}

// ---- springs: each segment bends against the yaw rate and lifts with forward acceleration, with lag --------
export class SpringChain {
  constructor(ris, freq, zeta, gain, lift) {
    this.ris = ris;
    this.w = freq.map((f) => 2 * Math.PI * f);
    this.zeta = zeta;
    this.gain = gain;
    this.lift = lift;
    const n = ris.length;
    this.x = new Float32Array(n);
    this.v = new Float32Array(n);
    this.y = new Float32Array(n);
    this.vy = new Float32Array(n);
  }
  update(clock, yawRate, accel) {
    if (calm) yawRate = accel = 0;
    const h = clock.h;
    for (let s = 0; s < clock.steps; s++)
      for (let i = 0; i < this.ris.length; i++) {
        const w = this.w[i];
        const tx = -yawRate * this.gain[i];
        const ty = -accel * this.lift;
        this.v[i] += (w * w * (tx - this.x[i]) - 2 * this.zeta * w * this.v[i]) * h;
        this.x[i] += this.v[i] * h;
        this.vy[i] += (w * w * (ty - this.y[i]) - 2 * this.zeta * w * this.vy[i]) * h;
        this.y[i] += this.vy[i] * h;
      }
  }
  apply(pose) {
    for (let i = 0; i < this.ris.length; i++) rotateRole(pose, this.ris[i], this.y[i], 0, this.x[i]);
  }
}

// ---- animator: base states with crossfades, the "@loco" blend space, overlays ------------------------------
// A base entry: { name, clip, t, w, target, rate, loco, custom, drive, vy }. A fixed pool: play() never
// allocates; the oldest (already fading) entry is reused when the pool is full.
const POOL = 5;
export class Animator {
  constructor(binding) {
    this.binding = binding;
    this.lib = binding.lib;
    this.pose = binding.newPose();
    this.pool = [];
    for (let i = 0; i < POOL; i++) this.pool.push({ name: "", clip: null, t: 0, w: 0, target: 0, rate: 1, loco: false, custom: null, drive: false, vy: 0 });
    this.layers = []; // active entries, oldest first
    this.ovs = []; // overlays (one object per name, made the first time it is used)
    this.ovByName = new Map();
    this.phase = 0;
    this.k = null;
    this.snap = false; // far tier: no crossfades
  }
  current() {
    return this.layers[this.layers.length - 1];
  }
  play(name, fade = 0.25, custom = null, drive = false) {
    const top = this.current();
    if (top && top.name === name && top.target === 1) return top;
    if (this.snap) fade = 0;
    const rate = 1 / Math.max(1e-3, fade);
    for (let i = 0; i < this.layers.length; i++) {
      this.layers[i].target = 0;
      this.layers[i].rate = rate;
    }
    let e = null;
    for (const p of this.pool) if (!this.layers.includes(p)) e = p;
    if (!e) e = this.layers.shift();
    e.name = name;
    e.clip = name[0] === "@" ? null : this.lib.get(name);
    e.t = 0;
    e.w = this.layers.length && fade > 0 ? 0 : 1;
    if (e.w === 1) this.layers.length = 0;
    e.target = 1;
    e.rate = rate;
    e.loco = name === "@loco";
    e.custom = custom;
    e.drive = drive;
    this.layers.push(e);
    return e;
  }
  overlay(name, on, fade = 0.3, restart = false, fadeOut = 0.3, hold = false) {
    let o = this.ovByName.get(name);
    if (!o) {
      const clip = this.lib.get(name);
      if (!clip) return null;
      o = { name, clip, t: 0, w: 0, target: 0, rate: 1, oneShot: false, fadeOut: 0.3 };
      this.ovByName.set(name, o);
      this.ovs.push(o);
    }
    if (restart) {
      o.t = 0;
      o.oneShot = !o.clip.loop && !hold;
      o.fadeOut = fadeOut;
    }
    o.target = on ? 1 : 0;
    o.rate = 1 / Math.max(1e-3, fade);
    return o;
  }
  overlayW(name) {
    const o = this.ovByName.get(name);
    return o ? o.w : 0;
  }
  // loco: [{ clip, speed }] sorted by speed
  update(dt, speed, loco) {
    const L = this.layers;
    for (let i = 0; i < L.length; i++) {
      const l = L[i];
      l.w = l.target > l.w ? Math.min(l.target, l.w + l.rate * dt) : Math.max(l.target, l.w - l.rate * dt);
      if (!l.loco && !l.drive) l.t += dt;
    }
    while (L.length > 1 && L[0].w <= 0 && L[0].target === 0) L.shift();
    if (loco) {
      const k = loco.fade ? this.locoSwitch(loco, speed, dt) : this.locoWeights(loco, speed);
      let stride = 0;
      for (let i = 0; i < loco.length; i++) stride += k[i] * (loco[i].clip.extras.tdd_stride || 1) * this.binding.k;
      const minRate = loco[0].clip.extras.tdd_rate_min ?? 0.5;
      const v = Math.max(speed, minRate * loco[0].speed);
      this.phase = (this.phase + (dt * v) / Math.max(0.05, stride)) % 1;
    }
    const P = this.pose;
    P.set(this.binding.rest);
    // (the first clip written at full weight lands on the rest pose: its "back to rest" pass is skipped)
    let fresh = true;
    for (let i = 0; i < L.length; i++) {
      const l = L[i];
      const w = i === 0 ? 1 : smooth01(l.w);
      if (l.loco) {
        if (!loco) continue;
        let acc = 0;
        for (let j = 0; j < loco.length; j++) {
          const kj = this.k[j];
          if (kj < 0.02) continue;
          acc += kj;
          const ww = (kj / acc) * w;
          sampleInto(this.binding, loco[j].clip, this.phase * loco[j].clip.duration, P, ww, !(fresh && ww >= 1));
          fresh = false;
        }
      } else if (l.custom) {
        l.custom(P, w, l);
        fresh = false;
      } else if (l.clip) {
        sampleInto(this.binding, l.clip, l.t, P, w, !(fresh && w >= 1) && l.clip.full);
        fresh = false;
      }
    }
    const O = this.ovs;
    for (let i = 0; i < O.length; i++) {
      const o = O[i];
      if (o.w <= 0 && o.target === 0) continue;
      if (o.oneShot && o.t >= o.clip.duration - o.fadeOut) {
        o.target = 0;
        o.rate = 1 / Math.max(1e-3, o.fadeOut);
      }
      if (!o.fixed) o.w = o.target > o.w ? Math.min(1, o.w + o.rate * dt) : Math.max(0, o.w - o.rate * dt);
      o.t += dt;
      if (o.w > 0) sampleInto(this.binding, o.clip, o.t, P, smooth01(o.w), false);
    }
    return P;
  }
  // (opt-in, loco.fade = seconds) gaits by speed range with hysteresis: the gait whose range holds the speed is
  // chosen (the change-over sits at the geometric mean of two gaits' speeds, so each plays at most ~1.6x or
  // ~0.6x its own rate there, and a gait is left only 8 % past it) and the weights crossfade to it over `fade`
  // seconds, eased; a held speed always plays ONE gait at its own rate, so a hoof is never half of two strides
  locoSwitch(loco, speed, dt) {
    const n = loco.length;
    const k = this.k && this.k.length === n ? this.k : null;
    if (!k) {
      this.k = new Float32Array(n);
      this.kLin = new Float32Array(n);
      this.gait = 0;
      while (this.gait < n - 1 && speed > Math.sqrt(loco[this.gait].speed * loco[this.gait + 1].speed)) this.gait++;
      this.kLin[this.gait] = 1;
    }
    let g = this.gait;
    while (g < n - 1 && speed > Math.sqrt(loco[g].speed * loco[g + 1].speed) * 1.08) g++;
    while (g > 0 && speed < Math.sqrt(loco[g - 1].speed * loco[g].speed) * 0.92) g--;
    this.gait = g;
    const L = this.kLin;
    const step = dt / Math.max(1e-3, loco.fade);
    let sum = 0;
    for (let i = 0; i < n; i++) {
      L[i] = i === g ? Math.min(1, L[i] + step) : Math.max(0, L[i] - step);
      sum += L[i];
    }
    for (let i = 0; i < n; i++) this.k[i] = sum > 0 ? (i === g ? smooth01(L[i]) : L[i] * (1 - smooth01(L[g])) / Math.max(1e-6, sum - L[g])) : i === g ? 1 : 0;
    return this.k;
  }
  locoWeights(loco, speed) {
    const k = this.k && this.k.length === loco.length ? this.k : (this.k = new Float32Array(loco.length));
    k.fill(0);
    if (speed <= loco[0].speed) k[0] = 1;
    else {
      let done = false;
      for (let i = 0; i < loco.length - 1 && !done; i++) {
        if (speed <= loco[i + 1].speed) {
          const u = (speed - loco[i].speed) / (loco[i + 1].speed - loco[i].speed);
          k[i] = 1 - u;
          k[i + 1] = u;
          done = true;
        }
      }
      if (!done) k[loco.length - 1] = 1;
    }
    return k;
  }
}

// ---- distance tiers (camera distance, polled every 0.25 s with 15 % hysteresis) ---------------------------
// 0 near (every frame, springs, look), 1 mid (every 2nd frame), 2 far (every 4th, no crossfades), 3 out
let tierN = 0;
export class Tier {
  constructor() {
    // (spread over frames by a counter: no Math.random, whose seeded stream the snapshot gates replay)
    const n = tierN++;
    this.tier = 0;
    this.poll = (n % 8) * 0.03;
    this.acc = 0;
    this.frame = n % 4;
  }
  pick(dt, d, cut = 60, phoneMid = false) {
    if ((this.poll -= dt) > 0) return this.tier;
    this.poll = 0.25;
    const h = (edge, cur) => (this.tier > cur ? edge * 0.85 : edge * 1.15);
    let t = 0;
    if (d > h(cut, 2)) t = 3;
    else if (d > h(40, 1)) t = 2;
    else if (d > h(15, 0)) t = 1;
    if (phoneMid && t === 0) t = 1;
    this.tier = t;
    return t;
  }
  // accumulate dt; returns the dt to step this frame (0: skip)
  step(dt) {
    this.acc += dt;
    this.frame++;
    const every = this.tier === 0 ? 1 : this.tier === 1 ? 2 : this.tier === 2 ? 4 : 0;
    if (!every || this.frame % every) return 0;
    const s = this.acc;
    this.acc = 0;
    return s;
  }
}
