// Willow plaza (the "plaza" room), v2: the ring path, the ring's lamp posts and the willow (trunk,
// canopy, planter, lantern posts, heart sign, curtain hooks, fireflies) are the Blender zone
// zon_plaza.glb. Gameplay stays code: the lamp colliders here, the willow's anchors, growth and
// decorations in tree.js. zones/legacy-plaza.js stays the fallback.
import * as THREE from "three";

// INTERIORS.plaza: the pink marker over the heart sign (the zone only has its socket)
export { interior } from "./legacy-plaza.js";

// World.buildDecor: the ring's 10 lamp posts, data only (same steps off the trail spokes)
export function ringLamps(kit, ringR) {
  const spokes = this.trailSpokes || [];
  const gap = 2.2 / (ringR + 1.6);
  for (let i = 0; i < 10; i++) {
    let a = (i / 10) * Math.PI * 2 + 0.31;
    for (const sa of spokes) {
      const d = Math.atan2(Math.sin(a - sa), Math.cos(a - sa));
      if (Math.abs(d) < gap) a = sa + Math.sign(d || 1) * gap;
    }
    this.addCircle(Math.sin(a) * (ringR + 1.6), Math.cos(a) * (ringR + 1.6) - 0.5, 0.2);
    this.circles[this.circles.length - 1].top = 3.55; // (zon_plaza COL_ extras)
  }
}

export function wire({ root, nodes, kit, willow, strands, stats }) {
  const N = nodes.plaza;
  if (!N) return;
  // the ring lamps' halos, as legacy's glow sprites
  for (const [name, o] of N) {
    if (!/^SOCK_lamp__\d+$/.test(name)) continue;
    const sp = kit.glowSprite("#ffd08a", 2.2);
    o.getWorldPosition(sp.position);
    root.add(sp);
  }
  const sock = N.get("SOCK_willow_tree");
  if (!sock || !willow) return;
  // the 48 anchors in the zone are checked against the code constants (never used for placing)
  let worst = 0;
  for (let i = 0; i < willow.anchors.length; i++) {
    const a = N.get(`ANCHOR_${i}`);
    if (!a) {
      worst = Infinity;
      continue;
    }
    worst = Math.max(worst, a.position.distanceTo(willow.anchors[i].clone().multiplyScalar(willow.big)));
  }
  stats.anchors = { n: willow.anchors.length, maxErr: worst };
  const hooks = [];
  for (const [name, o] of N) if (/^ANIM_zon_plaza_strand_\d+$/.test(name)) hooks.push(o);
  hooks.sort((a, b) => +a.userData.name.split("_").pop() - +b.userData.name.split("_").pop());
  let flies = null;
  for (const [name, o] of N) if (/^GI_veg_willow_firefly/.test(name)) o.traverse((c) => c.isInstancedMesh && !flies && (flies = c));
  willow.attachZone({
    sock,
    swing: N.get("ANIM_env_plaza_sign_swing__0"),
    faces: [N.get("SCREEN_face_front__0"), N.get("SCREEN_face_back__0")].filter(Boolean),
    hooks,
    strands,
    strandMap: strands?.map,
    flies,
  });
}

void THREE;
