// The trail network, v2 (zon_paths.glb): stones, rosettes, signposts and the six path lanterns
// are Blender's. Here: the names on the signpost boards (live, from the trail layout the World
// worked out, as legacy), and the lanterns' halos. Colliders stay the World's (buildDecor).
import * as THREE from "three";
import { boardTexture } from "../trails.js";

export function wire({ world, root, nodes, kit }) {
  const N = new Map([...(nodes.paths || new Map())]);
  const posts = world.signposts || [];
  const p = new THREE.Vector3();
  for (const [name, o] of N) {
    const m = /^SCREEN_(one|two)_(front|back)__\d+$/.exec(name);
    if (!m || !o.isMesh) continue;
    o.getWorldPosition(p);
    // which board: the signpost standing here, the board at this height (trails.js buildSignposts)
    let names = null;
    for (const sp of posts) {
      if (Math.hypot(sp.x - p.x, sp.z - p.z) > 0.05) continue;
      sp.boards.forEach((b, i) => {
        const two = b.names.length > 1;
        if ((m[1] === "two") !== two) return;
        const y = 2.15 - i * 0.5 - (two ? 0.08 : 0);
        if (Math.abs(y - p.y) < 0.02) names = b.names;
      });
    }
    if (!names) continue;
    const t = boardTexture(names, m[2] === "back", true);
    t.flipY = false;
    t.needsUpdate = true;
    o.material = new THREE.MeshBasicMaterial({ map: t, transparent: true, alphaTest: 0.3 });
    o.castShadow = false;
  }
  // the lanterns' halos (legacy glowSprite #ffd08a 1.3 at the lantern head)
  for (const [name, o] of N) {
    if (!/^SOCK_light__\d+$/.test(name)) continue;
    const sp = kit.glowSprite("#ffd08a", 1.3);
    o.getWorldPosition(sp.position);
    sp.userData.pathLantern = true;
    root.add(sp);
  }
}
