// Night glow cards (look pass, D-E1a): a soft additive glow on every lamp, lantern, lit window,
// fairy light and candle, so the night reads like ref 2 on every tier (the phones' straight-to-canvas
// path has no bloom pass). One draw for all of them: one quad, drawn once per light, facing you.
//
// The lights are found in the world, never listed: every piece drawn with the island's shared glow
// materials (world.js `glow`: windows, lamps, lanterns, fairy lights) plus anything else that shines
// brightly in a warm or pink colour (pumpkin faces, candles, bulbs). Each card follows its light:
// where it is (lights that move, move their card), and whether it is shown (a room's insides hidden
// by distance, the halloween and christmas sets, the lookout's roof...). Not the detail cull: a far
// lamp too small to draw still glows.
//
// Nothing in the world changes: the cards are extra, drawn after everything solid, never cast or
// catch shadows, and are not clickable.
import * as THREE from "three";

const _mi = new THREE.Matrix4();
const KIND = {
  // colour (linear-ish, from these sRGB values), strength, size per metre of the light's own radius
  window: { color: "#ffa648", strength: 0.9, k: 3.1, min: 1.6, max: 3.6 },
  lamp: { color: "#ffb04e", strength: 0.85, k: 4.2, min: 0.8, max: 2.2 },
  fairy: { color: "#ffc070", strength: 0.7, k: 7, min: 0.32, max: 0.9 },
  fairyPink: { color: "#ff79b0", strength: 0.55, k: 7, min: 0.3, max: 0.8 },
  pink: { color: "#ff79b0", strength: 0.85, k: 4.6, min: 0.4, max: 2.2 },
  magic: { color: "#a68cff", strength: 0.45, k: 3.2, min: 0.6, max: 3 },
  own: { color: null, strength: 0.8, k: 4.4, min: 0.5, max: 2.6 },
};
// MAT_glow_vc's vertex colours: the linear base colour of each glow kind (glow.warm / pink / magic)
const VC_KINDS = [
  ["warm", 1, 0.791, 0.434],
  ["pink", 1, 0.631, 0.761],
  ["magic", 0.686, 0.578, 1],
];
const VIS_EVERY = 6; // frames between looks at what is shown
const RECOUNT = 180; // frames between looks for new lights

const _v = new THREE.Vector3();
const _m = new THREE.Matrix4();

function shownIn(o, root) {
  for (let p = o; p; p = p.parent) {
    if (!p.visible) return false;
    if (p === root) return true;
  }
  return false;
}

// a warm or pink light colour (not a blue screen, a white cloud or a cool crystal)
function warmish(c) {
  return c.r > 0.5 && c.r >= c.b && c.r + c.g + c.b < 2.6;
}

// the separate pieces of a merged mesh (a place's still pieces are merged into one mesh per
// material a moment after it is built, bake.js): its parts that share no corner with each other
const _t = new THREE.Vector3();
// (worked out once per shape: every re-collect, each time a zone came in, did them all again, ~80 ms)
const _pieces = new WeakMap();
function pieces(geo) {
  let p = _pieces.get(geo);
  if (!p || p.n !== geo.attributes.position.count) _pieces.set(geo, (p = { n: geo.attributes.position.count, list: piecesOf(geo) }));
  return p.list;
}
function piecesOf(geo) {
  const pos = geo.attributes.position;
  const idx = geo.index;
  const tris = Math.floor((idx ? idx.count : pos.count) / 3);
  const up = new Int32Array(tris);
  for (let i = 0; i < tris; i++) up[i] = i;
  const find = (i) => {
    while (up[i] !== i) i = up[i] = up[up[i]];
    return i;
  };
  const owner = new Map();
  const vert = (t, k) => (idx ? idx.getX(t * 3 + k) : t * 3 + k);
  for (let t = 0; t < tris; t++)
    for (let k = 0; k < 3; k++) {
      const v = vert(t, k);
      const key = `${Math.round(pos.getX(v) * 200)},${Math.round(pos.getY(v) * 200)},${Math.round(pos.getZ(v) * 200)}`;
      const o = owner.get(key);
      if (o === undefined) owner.set(key, t);
      else {
        const a = find(o), b = find(t);
        if (a !== b) up[a] = b;
      }
    }
  const boxes = new Map();
  for (let t = 0; t < tris; t++) {
    const r = find(t);
    let bx = boxes.get(r);
    if (!bx) boxes.set(r, (bx = { box: new THREE.Box3(), v: vert(t, 0) }));
    for (let k = 0; k < 3; k++) bx.box.expandByPoint(_t.fromBufferAttribute(pos, vert(t, k)));
  }
  return [...boxes.values()];
}

// a small glowing face lying flat (a record's label, a lit plate on a table): its card, standing up through
// its centre to face you, was cut by the surface it lies on, so only the half above it was drawn (the song
// room's record lit on one half, then dark). It glows by itself; no card. (A wide one, the campfire's ember
// bed, keeps its card: there the half above the ground reads as the fire's glow)
const _fb = new THREE.Box3();
function lyingFlat(box, mw) {
  _fb.copy(box).applyMatrix4(mw).getSize(_t);
  return _t.y < 0.15 * Math.min(_t.x, _t.z) && Math.max(_t.x, _t.z) < 0.5;
}

export class GlowCards {
  constructor(scene) {
    this.scene = scene;
    this.items = [];
    this.uniforms = { uTime: { value: 0 }, uGlow: { value: 0 }, uFade: { value: new THREE.Vector2(40, 220) } };
    this.mesh = null;
    this.frame = 0;
    this.glow = null;
    this.stale = 0;
  }

  // how many pieces are drawn with the shared glow materials (a cheap look for new lights)
  count() {
    const g = this.glow;
    let n = 0;
    this.scene.traverse((o) => {
      if (o.isMesh && (o.material === g.warm || o.material === g.pink || o.material === g.magic || o.material?.userData?.isGlow)) n++;
    });
    return n;
  }

  // every light in the world now
  collect() {
    this.seen = this.count();
    this.collectedAt = performance.now();
    const glow = this.glow;
    const scene = this.scene;
    // (not forced: what stands still is already in place, performance 10)
    scene.updateMatrixWorld();
    const items = [];
    const add = (o, centre, radius, kind, color, instance = -1, box = null) => {
      const K = KIND[kind];
      const size = THREE.MathUtils.clamp(radius * K.k, K.min, K.max);
      const it = { o, instance, local: centre.clone(), size, strength: K.strength, kind, color: new THREE.Color(color || K.color), push: Math.min(radius * 1.1, 0.9), last: new Float32Array([NaN, NaN, NaN]), shown: true, normal: null };
      if (kind === "window") it.normal = this.facing(o, box || o.geometry.boundingBox || o.geometry.computeBoundingBox() || o.geometry.boundingBox, centre);
      items.push(it);
    };
    scene.traverse((o) => {
      if (!o.isMesh || !o.material || Array.isArray(o.material) || o.userData.lookGlow === false || o === this.mesh) return;
      // (a phone's merged copy stands in for pieces like this one: the copy is counted instead)
      if (o.layers.mask === 0) return;
      const m = o.material;
      let kind = null;
      if (m === glow.warm) kind = "warm";
      else if (m === glow.pink) kind = "pink";
      else if (m === glow.magic) kind = "magic";
      else if (m.userData?.isGlow && o.geometry.attributes.color) kind = "vc";
      else if (m.emissive && !m.map && !m.emissiveMap && m.emissiveIntensity >= 1.2 && warmish(m.emissive)) kind = "own";
      if (!kind) return;
      const g = o.geometry;
      if (!g.boundingSphere) g.computeBoundingSphere();
      const own = kind === "own" ? `#${m.emissive.getHexString()}` : null;
      const pick = (r, k = kind) => (k === "warm" ? (r >= 0.5 ? "window" : r < 0.11 ? "fairy" : "lamp") : k === "pink" ? (r < 0.11 ? "fairyPink" : "pink") : k);
      // the draw-call pass's one merged glow (MAT_glow_vc): each piece's vertex colour says its kind
      if (kind === "vc") {
        const col = g.attributes.color;
        const sc = o.matrixWorld.getMaxScaleOnAxis();
        for (const { box, v } of pieces(g)) {
          if (lyingFlat(box, o.matrixWorld)) continue;
          let best = "warm";
          let bd = Infinity;
          for (const [k, r, gg, b] of VC_KINDS) {
            const d = (col.getX(v) - r) ** 2 + (col.getY(v) - gg) ** 2 + (col.getZ(v) - b) ** 2;
            if (d < bd) {
              bd = d;
              best = k;
            }
          }
          const r = (box.getSize(_t).length() / 2) * sc;
          add(o, box.getCenter(new THREE.Vector3()), r, pick(r, best), null, -1, box);
        }
        return;
      }
      if (o.isInstancedMesh) {
        for (let i = 0; i < o.count; i++) {
          o.getMatrixAt(i, _m);
          // (a pair of path lanterns taken out where another light stands: scaled to nothing)
          if (Math.abs(_m.determinant()) < 1e-9) continue;
          const sc = Math.cbrt(Math.abs(_m.determinant()));
          const r = g.boundingSphere.radius * sc;
          add(o, g.boundingSphere.center.clone().applyMatrix4(_m), r, pick(r), own, i);
          // (lights that fly about as instances, fireflies or motes: the card follows its instance)
          if (o.userData.glowMoves) items[items.length - 1].gc = g.boundingSphere.center.clone();
        }
        return;
      }
      const sc = o.matrixWorld.getMaxScaleOnAxis();
      if (g.boundingSphere.radius * sc > 1.2) {
        // a merged mesh: each piece its own light
        for (const { box: b } of pieces(g)) {
          if (lyingFlat(b, o.matrixWorld)) continue;
          const r = (b.getSize(_t).length() / 2) * sc;
          add(o, b.getCenter(new THREE.Vector3()), r, pick(r), own, -1, b);
        }
        return;
      }
      if (!g.boundingBox) g.computeBoundingBox();
      if (lyingFlat(g.boundingBox, o.matrixWorld)) return;
      add(o, g.boundingSphere.center, g.boundingSphere.radius * sc, pick(g.boundingSphere.radius * sc), own);
    });
    this.items = items;
    const n = items.length;
    const geo = this.mesh?.geometry;
    if (geo && geo.userData.capacity < n) {
      // (more lights than room: bigger buffers, the same shader)
      for (const k of ["aCentre", "aData", "aColor", "aNormal"]) geo.deleteAttribute(k);
      this.alloc(geo, n);
    }
    if (geo) this.fill(geo);
    return n;
  }

  // a lit window looks out of its wall: the wall's thin axis, turned away from its building's middle
  // (null: not known; the card then faces you from every side)
  facing(o, box, centre) {
    if (!box || !this.centres?.length) return null;
    const s = box.getSize(new THREE.Vector3());
    const axis = s.x <= s.y && s.x <= s.z ? 0 : s.y <= s.z ? 1 : 2;
    if (axis === 1) return null;
    const n = new THREE.Vector3().setComponent(axis, 1).transformDirection(o.matrixWorld);
    n.y = 0;
    if (n.lengthSq() < 1e-6) return null;
    n.normalize();
    const p = centre.clone().applyMatrix4(o.matrixWorld);
    let best = null;
    let bd = 22 * 22;
    for (const c of this.centres) {
      const d = (c.x - p.x) ** 2 + (c.z - p.z) ** 2;
      if (d < bd) {
        bd = d;
        best = c;
      }
    }
    if (!best) return null;
    if (n.x * (p.x - best.x) + n.z * (p.z - best.z) < 0) n.negate();
    return n;
  }

  alloc(geo, n) {
    const cap = Math.ceil(n * 1.25) + 32;
    geo.userData.capacity = cap;
    this.aCentre = new THREE.InstancedBufferAttribute(new Float32Array(cap * 3), 3);
    this.aData = new THREE.InstancedBufferAttribute(new Float32Array(cap * 4), 4);
    this.aColor = new THREE.InstancedBufferAttribute(new Float32Array(cap * 3), 3);
    this.aNormal = new THREE.InstancedBufferAttribute(new Float32Array(cap * 3), 3);
    geo.setAttribute("aNormal", this.aNormal);
    this.aCentre.setUsage(THREE.DynamicDrawUsage);
    this.aData.setUsage(THREE.DynamicDrawUsage);
    geo.setAttribute("aCentre", this.aCentre);
    geo.setAttribute("aData", this.aData);
    geo.setAttribute("aColor", this.aColor);
  }

  fill(geo) {
    this.items.forEach((it, i) => {
      this.aData.setXYZW(i, it.size, it.strength, (i * 2.399) % 6.283, it.push);
      this.aColor.setXYZ(i, it.color.r, it.color.g, it.color.b);
      if (it.normal) this.aNormal.setXYZ(i, it.normal.x, it.normal.y, it.normal.z);
      else this.aNormal.setXYZ(i, 0, 0, 0);
    });
    this.aNormal.needsUpdate = true;
    geo.instanceCount = this.items.length;
    this.aColor.needsUpdate = true;
    this.frame = 0;
    this.update(this.uniforms.uTime.value, true);
  }

  // once everything is built (and before the shaders are compiled)
  build(glow, { centres = [], direct = false } = {}) {
    this.glow = glow;
    this.centres = centres;
    const scene = this.scene;
    const n0 = this.collect();
    const geo = new THREE.InstancedBufferGeometry();
    geo.setAttribute("position", new THREE.Float32BufferAttribute([-0.5, -0.5, 0, 0.5, -0.5, 0, 0.5, 0.5, 0, -0.5, 0.5, 0], 3));
    geo.setIndex([0, 1, 2, 0, 2, 3]);
    this.alloc(geo, n0);
    const mat = new THREE.ShaderMaterial({
      name: "LookGlowCards",
      uniforms: this.uniforms,
      transparent: true,
      depthWrite: false,
      vertexShader: /* glsl */ `
        attribute vec3 aCentre;
        attribute vec4 aData; // size, strength, phase, push towards you
        attribute vec3 aColor;
        attribute vec3 aNormal; // a lit window: the way it looks out (zero: any way)
        uniform float uTime;
        uniform float uGlow;
        uniform vec2 uFade;
        varying vec2 vUv;
        varying vec3 vColor;
        varying float vA;
        void main() {
          bool win = dot( aNormal, aNormal ) > 0.5;
          // a window glows outwards, just outside its wall, and not into the room behind it
          vec3 c = win ? aCentre + aNormal * 0.25 : aCentre;
          float face = win ? smoothstep( -0.05, 0.3, dot( aNormal, normalize( cameraPosition - c ) ) ) : 1.0;
          vec4 mv = modelViewMatrix * vec4( c, 1.0 );
          float d = length( mv.xyz );
          // a little towards you, so the lamp's own glass doesn't cut the card
          if ( !win ) mv.xyz += normalize( -mv.xyz ) * min( aData.w, d * 0.5 );
          mv.xy += position.xy * aData.x;
          vUv = position.xy * 2.0;
          // a slow breath, each light its own; dimmer through the far haze, never gone
          vA = face * aData.y * uGlow * ( 0.93 + 0.07 * sin( uTime * 1.6 + aData.z ) ) * mix( 1.0, 0.5, smoothstep( uFade.x, uFade.y, d ) );
          vColor = aColor;
          gl_Position = projectionMatrix * mv;
          // (a light switched off is a card of no size)
          if ( vA <= 0.0 ) gl_Position = vec4( 2.0, 2.0, 2.0, 1.0 );
        }`,
      fragmentShader: /* glsl */ `
        varying vec2 vUv;
        varying vec3 vColor;
        varying float vA;
        void main() {
          float r2 = dot( vUv, vUv );
          if ( r2 >= 1.0 ) discard;
          // a bright little core and a wide soft halo, fading to nothing at the card's edge
          float w = 1.0 - r2;
          vec3 c = vColor * ( exp( -r2 * 10.0 ) * 1.4 + w * w * 0.32 ) * vA;
          // (straight onto the canvas the card is tone-mapped on its own: only what it adds, so the
          // grade's lift never shows as a square)
          #ifdef TONE_MAPPING
            c = max( toneMapping( c ) - toneMapping( vec3( 0.0 ) ), 0.0 );
          #endif
          gl_FragColor = linearToOutputTexel( vec4( c, 1.0 ) );
        }`,
    });
    // (added on top, colour only: the picture's alpha is left as it is)
    mat.blending = THREE.CustomBlending;
    // (straight onto the canvas the colours are already encoded: screen-blend, which can never
    // run past white; review lighting 3)
    mat.blendSrc = direct ? THREE.OneMinusDstColorFactor : THREE.OneFactor;
    mat.blendDst = THREE.OneFactor;
    mat.blendSrcAlpha = THREE.ZeroFactor;
    mat.blendDstAlpha = THREE.OneFactor;
    const mesh = new THREE.Mesh(geo, mat);
    mesh.name = "look.glowCards";
    mesh.frustumCulled = false;
    mesh.renderOrder = 8;
    mesh.matrixAutoUpdate = false;
    mesh.raycast = () => {};
    mesh.__noBake = true;
    mesh.userData.keepDetail = true;
    mesh.visible = false;
    this.mesh = mesh;
    scene.add(mesh);
    this.fill(geo);
    return n0;
  }

  // the night's glow (0 by day: then nothing is drawn at all), the haze's distances
  set(glow, fogNear, fogFar) {
    this.uniforms.uGlow.value = glow;
    this.uniforms.uFade.value.set(Math.max(10, fogNear), Math.max(40, fogFar));
    if (this.mesh) this.mesh.visible = glow > 0.002 && this.items.length > 0;
  }

  // once a frame, after the world's matrices are up to date
  update(t, all = false) {
    if (!this.mesh) return;
    this.uniforms.uTime.value = t;
    if (!this.mesh.visible && !all) return;
    const look = all || this.frame++ % VIS_EVERY === 0;
    const root = this.scene;
    const C = this.aCentre.array;
    const D = this.aData.array;
    let moved = false;
    let shown = false;
    for (let i = 0; i < this.items.length; i++) {
      const it = this.items[i];
      if (look) {
        // (merged away into one mesh a moment after its place was built: look again, below)
        if (!it.o.parent) this.stale++;
        const on = Boolean(it.o.parent) && shownIn(it.o, root);
        if (on !== it.shown) {
          it.shown = on;
          D[i * 4 + 1] = on ? it.strength : 0;
          shown = true;
        }
      }
      if (!it.shown) continue;
      if (it.gc) {
        it.o.getMatrixAt(it.instance, _mi);
        _v.copy(it.gc).applyMatrix4(_mi).applyMatrix4(it.o.matrixWorld);
        C[i * 3] = _v.x;
        C[i * 3 + 1] = _v.y;
        C[i * 3 + 2] = _v.z;
        moved = true;
        continue;
      }
      const e = it.o.matrixWorld.elements;
      const l = it.last;
      if (e[12] === l[0] && e[13] === l[1] && e[14] === l[2] && !all) continue;
      l[0] = e[12];
      l[1] = e[13];
      l[2] = e[14];
      _v.copy(it.local).applyMatrix4(it.o.matrixWorld);
      C[i * 3] = _v.x;
      C[i * 3 + 1] = _v.y;
      C[i * 3 + 2] = _v.z;
      moved = true;
    }
    if (moved) this.aCentre.needsUpdate = true;
    if (shown || all) this.aData.needsUpdate = true;
    // (lights added while you play, a lamp hung on the willow say: counted now and then)
    if (!all && this.frame % RECOUNT === 0 && this.count() !== this.seen) this.stale++;
    // (at most once every 2 s: zones arriving one after another each made one, performance 10)
    if (this.stale && !all && performance.now() - (this.collectedAt || 0) > 2000) {
      this.stale = 0;
      this.collect();
    }
  }

  dispose() {
    if (!this.mesh) return;
    this.mesh.removeFromParent();
    this.mesh.geometry.dispose();
    this.mesh.material.dispose();
    this.mesh = null;
    this.items = [];
  }
}
