// The characters kit (Wave 10, rebuild/reports/assets-avatars.md) in the game: every Avatar (yours, a
// visitor's, a photo double) is first built the old procedural way, as before (dims, pivots, emotes,
// poses, the save fields and the sync are untouched), and then wears its Blender look: one skinned
// mesh per level whose bones are the kit's ANIM_ joints, which sit exactly where the legacy groups
// sat, so Avatar.update() drives the very same fields. The look comes from avatarLook() (the
// reference assembly): which SM_ parts of which chr_avatar_* GLB, their three tint channels (per
// vertex, so one material serves every avatar), the glow of the halo, crown and star clips (per
// vertex too), the fits over the hair. A lite level (the _lite sets) is drawn beyond 12 m.
// The NPCs (gnome, scarecrows, snowmen) wear chr_* rigs at the legacy NPCs' own holders.
// Under zones=legacy nothing is ever loaded: procedural only.
import * as THREE from "three";
import { mergeGeometries } from "three/examples/jsm/utils/BufferGeometryUtils.js";
import { zoneMode } from "./mode.js";
import { avatarLook, accessoryList } from "./avatar_look.js";
import { hairAttributes, HAIR_VERT_PARS, HAIR_VERT, HAIR_FRAG_PARS, HAIR_ALBEDO, HAIR_LIGHT } from "./hairlook.js";

export const LITE_AT = 22;
let kit = null; // { load(name) -> Promise<scene>, rig, base material }
let v2 = null;
const isV2 = () => (v2 ??= zoneMode().v2);
const waiting = new Set(); // avatars built before the kit came in
const readyFns = [];
const camPos = new THREE.Vector3(0, 0, 0);
let camSeen = false;
const stats = { dressed: 0, lite: 0, failed: 0, npcs: 0, carved: 0, ms: 0 };
const skinMats = new Map();

export const charactersReady = () => Boolean(kit);
export const characterStats = () => ({ ready: Boolean(kit), waiting: waiting.size, ...stats });
export const cameraPos = () => (camSeen ? camPos : null);

// one material for every avatar and NPC: the kit atlas x the tint mask, the three tints and the glow
// riding on each vertex (skinned or not: three compiles each its own program)
function kitMat(base) {
  if (skinMats.has(base)) return skinMats.get(base);
  const mask = base.userData.kitMask;
  const m = base.clone();
  m.userData = { ...base.userData, characters: true };
  m.onBeforeCompile = (sh) => {
    sh.uniforms.tddKitMask = { value: mask };
    sh.vertexShader = sh.vertexShader
      .replace("#include <common>", "#include <common>\nattribute vec3 aTintR;\nattribute vec3 aTintG;\nattribute vec3 aTintB;\nattribute vec3 aEmit;\nvarying vec3 vTintR;\nvarying vec3 vTintG;\nvarying vec3 vTintB;\nvarying vec3 vEmit;" + HAIR_VERT_PARS)
      .replace("#include <uv_vertex>", "#include <uv_vertex>\nvTintR = aTintR; vTintG = aTintG; vTintB = aTintB; vEmit = aEmit;")
      .replace("#include <skinning_vertex>", "#include <skinning_vertex>" + HAIR_VERT);
    sh.fragmentShader = sh.fragmentShader
      .replace("#include <common>", "#include <common>\nuniform sampler2D tddKitMask;\nvarying vec3 vTintR;\nvarying vec3 vTintG;\nvarying vec3 vTintB;\nvarying vec3 vEmit;" + HAIR_FRAG_PARS)
      .replace(
        "#include <map_fragment>",
        "#include <map_fragment>\n{ vec3 km = texture2D(tddKitMask, vMapUv).rgb;\n  hairKm = km;\n  vec3 kw = km * km; kw *= kw; float kwS = max(kw.r + kw.g + kw.b, 1e-4);\n  diffuseColor.rgb *= mix(vec3(1.0), (kw.r * vTintR + kw.g * vTintG + kw.b * vTintB) / kwS, smoothstep(0.15, 0.4, max(km.r, max(km.g, km.b)))); }" + HAIR_ALBEDO,
      )
      .replace("#include <emissivemap_fragment>", "#include <emissivemap_fragment>\ntotalEmissiveRadiance += vEmit;")
      .replace("#include <opaque_fragment>", HAIR_LIGHT + "\n#include <opaque_fragment>");
  };
  m.customProgramCacheKey = () => "tdd_kit_chr_hair3";
  skinMats.set(base, m);
  return m;
}

const kindOf = (asset) => (/^chr_avatar_head/.test(asset) ? "head" : /^chr_avatar_acc/.test(asset) ? "acc" : /^chr_avatar_hair_/.test(asset) ? "hair" : "body");
// the joint a source ANIM_ node stands for, the same in every set (full, _tops, _lite, ...)
const keyOf = (asset, o) => {
  const k = kindOf(asset);
  return k === "hair" ? "hair" : k + ":" + (o.userData?.tdd_role || o.name);
};
// the ANIM_ chain of a source set, without its meshes
function cloneJoints(src, asset, out) {
  const j = new THREE.Object3D();
  j.name = src.name;
  j.position.copy(src.position);
  j.quaternion.copy(src.quaternion);
  j.scale.copy(src.scale);
  j.userData.tdd_role = src.userData?.tdd_role;
  // (its rest, for the clip binding: anim/runtime.js RigBinding)
  j.userData.restTRS = Float32Array.of(j.position.x, j.position.y, j.position.z, j.quaternion.x, j.quaternion.y, j.quaternion.z, j.quaternion.w, j.scale.x, j.scale.y, j.scale.z);
  out.set(keyOf(asset, src), j);
  for (const c of src.children) if (/^ANIM_/.test(c.name)) j.add(cloneJoints(c, asset, out));
  return j;
}
const meshIn = (scene, name) => {
  let m = null;
  scene.traverse((o) => {
    if (!m && o.isMesh && o.name === name) m = o;
  });
  return m;
};
const WHITE = new THREE.Color(1, 1, 1);
const _c = new THREE.Color();
const _m = new THREE.Matrix4();

// one level's geometry: every shown part in the rig's rest space, its bone, tints and glow per vertex
function partsGeometry(parts, scenes, joints, bones, rest, skinned) {
  const geos = [];
  for (const p of parts) {
    const sc = scenes.get(p.asset);
    const o = sc && meshIn(sc, p.mesh);
    if (!o) throw new Error("no " + p.mesh);
    const j = joints.get(keyOf(p.asset, o.parent));
    if (!j) throw new Error("no joint for " + p.mesh);
    const src = o.geometry;
    const g = new THREE.BufferGeometry();
    for (const k of ["position", "normal", "uv"]) g.setAttribute(k, src.attributes[k].clone());
    if (src.index) g.setIndex(src.index.clone());
    g.applyMatrix4(_m.multiplyMatrices(rest.get(j), o.matrix));
    hairAttributes(g, src, kindOf(p.asset) === "hair", _m);
    const n = g.attributes.position.count;
    if (skinned) {
      const bi = bones.indexOf(j);
      const si = new Uint16Array(n * 4);
      const sw = new Float32Array(n * 4);
      for (let i = 0; i < n; i++) {
        si[i * 4] = bi;
        sw[i * 4] = 1;
      }
      g.setAttribute("skinIndex", new THREE.Uint16BufferAttribute(si, 4));
      g.setAttribute("skinWeight", new THREE.Float32BufferAttribute(sw, 4));
    }
    const add = (name, c) => {
      const a = new Float32Array(n * 3);
      for (let i = 0; i < n; i++) c.toArray(a, i * 3);
      g.setAttribute(name, new THREE.Float32BufferAttribute(a, 3));
    };
    for (const ch of ["R", "G", "B"]) add("aTint" + ch, p.tint?.[ch] ? _c.set(p.tint[ch]).clone() : WHITE);
    // (legacy glow: emissive = the accent x its intensity: halo 1.0, crown 0.3, star clips 0.25)
    add("aEmit", p.emissive ? _c.set(p.emissive.color).multiplyScalar(p.emissive.k).clone() : new THREE.Color(0, 0, 0));
    geos.push(g);
  }
  const merged = mergeGeometries(geos);
  for (const g of geos) g.dispose();
  if (!merged) throw new Error("merge failed");
  return merged;
}

function levelMesh(geo, skeleton) {
  const mat = kitMat(kit.base);
  const mesh = skeleton ? new THREE.SkinnedMesh(geo, mat) : new THREE.Mesh(geo, mat);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  geo.computeBoundingSphere();
  if (skeleton) {
    mesh.bind(skeleton, new THREE.Matrix4());
    // (a little roomier than the rest pose: arms go up, legs swing, the body lies down in bed)
    mesh.boundingSphere = geo.boundingSphere.clone();
    mesh.boundingSphere.radius += 0.6;
  }
  return mesh;
}

const assetsOf = (look, body) => [...new Set([`chr_avatar_${body}`, ...look.parts.map((p) => p.asset)])];

// ---- avatars ----
async function dress(av) {
  const gen = (av.kitGen = (av.kitGen || 0) + 1);
  const t0 = performance.now();
  try {
    const look = avatarLook(av.config, kit.rig);
    const names = assetsOf(look, look.body);
    const scenes = new Map();
    const got = await Promise.all(names.map((n) => kit.load(n)));
    names.forEach((n, i) => scenes.set(n, got[i]));
    if (gen !== av.kitGen || !kit) return;
    // the skeleton: the body set's joints, then the head, hair and extras sets grafted on its head
    const joints = new Map();
    const body = cloneJoints(scenes.get(`chr_avatar_${look.body}`).children.find((c) => /^ANIM_/.test(c.name)), `chr_avatar_${look.body}`, joints);
    const head = joints.get("body:head");
    const grafts = new Set(names.filter((n) => kindOf(n) !== "body"));
    for (const n of grafts) for (const c of scenes.get(n).children) if (/^ANIM_/.test(c.name)) head.add(cloneJoints(c, n, joints));
    // the fits over the hair (legacy fitOverHair, measured per hair x extra): each extra's joint
    for (const [name, f] of Object.entries(look.fits)) {
      const j = joints.get("acc:" + name.replace(/^ANIM_chr_avatar_acc_/, ""));
      if (!j) continue;
      if (f.pos) j.position.fromArray(f.pos);
      if (f.scale) j.scale.fromArray(f.scale);
    }
    body.updateMatrixWorld(true);
    const bones = [...joints.values()];
    const rest = new Map(bones.map((b) => [b, b.matrixWorld.clone()]));
    const skeleton = new THREE.Skeleton(bones);
    const full = levelMesh(partsGeometry(look.parts, scenes, joints, bones, rest, true), skeleton);
    full.name = "avatar.kit";
    body.add(full);
    const cfg = av.config;
    const face = cfg.face || "cute";
    const extras = accessoryList(cfg.accessory).filter((id) => cfg.style !== "boy" || !["bow", "catEars", "crown", "flower", "halo", "bunny", "starclips"].includes(id));
    const eyes = [0, 1].map((i) => {
      const arc = face === "happy" || (face === "wink" && i === 1);
      const e = joints.get(`head:${arc ? "eyearc" : "eye"}_${i}`);
      // (the kit's round eyes rest at scale 1, the legacy ones at 1.25: Avatar.update divides)
      e.userData = { ...e.userData, arc, k: face === "sleepy" ? 0.4 : 1, div: arc ? 1 : 1.25 };
      return e;
    });
    const J = (k) => joints.get("body:" + k);
    av.wearKit({
      body,
      joints,
      fields: {
        body,
        hips: J("hips"),
        legs: [0, 1].map((i) => ({ leg: J("leg_" + i), knee: J("knee_" + i) })),
        spine: J("spine"),
        torso: J("torso"),
        arms: [0, 1].map((i) => ({ shoulder: J("shoulder_" + i), elbow: J("elbow_" + i), side: i ? -1 : 1 })),
        head,
        eyes,
        mouth: joints.get("head:mouth"),
        bunnyTail: extras.includes("bunny") ? J("tail") : null,
      },
      // the lite level, made when first wanted: same bones, the _lite sets' parts
      lite: async () => {
        const ll = avatarLook(cfg, kit.rig, { lite: true });
        const ln = assetsOf(ll, ll.body);
        const lg = await Promise.all(ln.map((n) => kit.load(n)));
        if (gen !== av.kitGen || !kit) return null;
        const ls = new Map(ln.map((n, i) => [n, lg[i]]));
        const m = levelMesh(partsGeometry(ll.parts, ls, joints, bones, rest, true), skeleton);
        m.name = "avatar.kit.lite";
        body.add(m);
        stats.lite++;
        return m;
      },
      full,
    });
    stats.dressed++;
    stats.ms = Math.round(performance.now() - t0);
  } catch (e) {
    stats.failed++;
    console.warn("avatar kit", e);
    if (gen === av.kitGen) av.kitFailed?.();
  }
}

// an Avatar was (re)built: it wears its kit look (now, or once the kit is in)
export function dressAvatar(av) {
  if (!isV2()) return;
  if (!kit) return void waiting.add(av);
  dress(av);
}

// ---- NPCs ----
// a holder the legacy builder made (where its NPC stands): it gets the chr_* rig, tinted
async function npc(asset, holder, { tint = null, show = null, hide = false } = {}) {
  const sc = await kit.load(asset);
  if (!kit) return null;
  const parts = [];
  sc.traverse((o) => {
    if (!o.isMesh) return;
    if (show && !show(o.name)) return;
    parts.push(o);
  });
  sc.updateMatrixWorld(true);
  const inv = new THREE.Matrix4().copy(sc.matrixWorld).invert();
  const geos = parts.map((o) => {
    const g = new THREE.BufferGeometry();
    for (const k of ["position", "normal", "uv"]) g.setAttribute(k, o.geometry.attributes[k].clone());
    if (o.geometry.index) g.setIndex(o.geometry.index.clone());
    g.applyMatrix4(_m.multiplyMatrices(inv, o.matrixWorld));
    hairAttributes(g, null, false, null);
    const n = g.attributes.position.count;
    const ch = kit.rig.assets[asset]?.meshes[o.name]?.ch || {};
    for (const c of ["R", "G", "B"]) {
      const a = new Float32Array(n * 3);
      (ch[c] && tint?.[ch[c][0]] ? _c.set(tint[ch[c][0]]) : _c.copy(WHITE)).toArray(a, 0);
      for (let i = 1; i < n; i++) a.copyWithin(i * 3, 0, 3);
      g.setAttribute("aTint" + c, new THREE.Float32BufferAttribute(a, 3));
    }
    g.setAttribute("aEmit", new THREE.Float32BufferAttribute(new Float32Array(n * 3), 3));
    return g;
  });
  const merged = mergeGeometries(geos);
  for (const g of geos) g.dispose();
  const mesh = levelMesh(merged, null);
  mesh.name = asset;
  // (the legacy NPC's own meshes leave; its sprites and props, a wish bubble, stay)
  if (hide) for (const c of holder.children) if (c.isMesh) c.visible = false;
  holder.add(mesh);
  stats.npcs++;
  return mesh;
}

// the zone's own copy of an NPC (the garden and farm kits made one too, merged into the zone): its
// triangles inside the NPC's box leave, so only the chr_* one stands there
// box: in the holder's frame, [x0, x1, y0, y1, z0, z1]; ground-flat triangles always stay
function carve(scenes, holder, box) {
  holder.updateWorldMatrix(true, false);
  const toLocal = new THREE.Matrix4().copy(holder.matrixWorld).invert();
  const v = new THREE.Vector3();
  const inside = (p) => p.x > box[0] && p.x < box[1] && p.y > box[2] && p.y < box[3] && p.z > box[4] && p.z < box[5];
  let cut = 0;
  for (const sc of scenes) {
    sc.updateMatrixWorld(true);
    sc.traverse((o) => {
      if (!o.isMesh || o.isInstancedMesh || o.isSkinnedMesh) return;
      // (only the kit's own solid parts: never the lawn, the paths, the grass or the glows)
      const mn = o.material?.name || "";
      if (!/^MAT_(kit_|farm_hay)/.test(mn) || o.material?.transparent) return;
      const g = o.geometry;
      const pos = g.attributes.position;
      if (!g.boundingBox) g.computeBoundingBox();
      const m = new THREE.Matrix4().multiplyMatrices(toLocal, o.matrixWorld);
      const bb = g.boundingBox.clone().applyMatrix4(m);
      if (bb.max.x < box[0] || bb.min.x > box[1] || bb.max.y < box[2] || bb.min.y > box[3] || bb.max.z < box[4] || bb.min.z > box[5]) return;
      const idx = g.index ? g.index.array : null;
      const tris = (idx ? idx.length : pos.count) / 3;
      const keep = [];
      let n = 0;
      const pt = (i) => v.fromBufferAttribute(pos, idx ? idx[i] : i).applyMatrix4(m);
      for (let t = 0; t < tris; t++) {
        let all = true;
        let top = -1e9;
        for (let k = 0; k < 3; k++) {
          const p = pt(t * 3 + k);
          top = Math.max(top, p.y);
          if (!inside(p)) all = false;
        }
        if (all && top > box[2] + 0.04) n++;
        else for (let k = 0; k < 3; k++) keep.push(idx ? idx[t * 3 + k] : t * 3 + k);
      }
      if (!n) return;
      g.setIndex(keep);
      cut += n;
    });
  }
  stats.carved += cut;
  return cut;
}

// the legacy builders' NPC spots (world.npcSpots: {zone, asset, holder, box, tint}): each one wears
// its chr_* rig once the kit and (for a zone's own copy) that zone are in
const zoneScenes = new Map();
const pendingSpots = [];
function trySpots(world) {
  for (const s of world.npcSpots || []) {
    if (s.done || !kit) continue;
    if (s.zone && !zoneScenes.has(s.zone)) continue;
    s.done = true;
    npc(s.asset, s.holder, s)
      .then((m) => {
        if (m && s.zone && s.box) carve(zoneScenes.get(s.zone), s.holder, s.box);
      })
      .catch((e) => console.warn("npc", s.asset, e));
  }
}
export function npcZoneIn(world, id, scenes) {
  if (!isV2()) return;
  zoneScenes.set(id, scenes);
  if (kit) trySpots(world);
  else pendingSpots.push(world);
}

// the kit is in: everything built so far wears its look
export function setCharacterKit(k, world) {
  kit = k;
  for (const av of waiting) dress(av);
  waiting.clear();
  trySpots(world);
  pendingSpots.length = 0;
  for (const fn of readyFns.splice(0)) fn();
}
export function onCharacters(fn) {
  if (kit) fn();
  else if (isV2()) readyFns.push(fn);
}
// (the camera, for the avatars' own lite switch in Avatar.update)
export function tickCharacters(cam) {
  camPos.copy(cam);
  camSeen = true;
}

export function resetCharacters() {
  for (const m of skinMats.values()) m.dispose();
  skinMats.clear();
  kit = null;
  v2 = null;
  waiting.clear();
  readyFns.length = 0;
  zoneScenes.clear();
  pendingSpots.length = 0;
  camSeen = false;
  Object.assign(stats, { dressed: 0, lite: 0, failed: 0, npcs: 0, carved: 0, ms: 0 });
}
