// The follow camera's arm against the buildings' real shapes. The arm was only shortened by the old
// collision walls (and their heights) and a box round each hall: the Blender buildings' roofs, eaves,
// porches, towers and stalls reach past those, so the camera went inside them and the faces it was
// behind were not drawn (back faces): the user's "parts of buildings disappear from some directions".
// Each building's solid triangles go into a world grid once its place is in (a few ms at a time,
// work()); the arm then walks the cells along it (3D DDA) and tests only the triangles there.
import * as THREE from "three";

const CELL = 2;
const _v = new THREE.Vector3();
const _a = new THREE.Vector3();
const _b = new THREE.Vector3();
const _c = new THREE.Vector3();
const _d = new THREE.Vector3();

export class SolidGrid {
  constructor() {
    this.tri = new Float32Array(9 * 4096);
    this.n = 0;
    this.cells = new Map(); // cell key -> number[] of triangle ids
    this.queue = []; // [mesh, next triangle]
    this.stamp = new Uint32Array(4096);
    this.tick = 0;
  }

  add(meshes) {
    for (const o of meshes) if (o?.isMesh && !o.isInstancedMesh && !o.isSkinnedMesh && o.geometry?.attributes.position) this.queue.push([o, 0]);
  }

  // a few ms of the queued meshes' triangles into the grid
  work(ms = 3) {
    const t0 = performance.now();
    while (this.queue.length && performance.now() - t0 < ms) {
      const q = this.queue[0];
      const [o] = q;
      const g = o.geometry;
      const pos = g.attributes.position;
      const idx = g.index;
      const count = Math.floor((idx ? idx.count : pos.count) / 3);
      // (a mesh whose shape was let go of since: nothing to read)
      if (!pos.array?.length || (idx && !idx.array?.length)) {
        this.queue.shift();
        continue;
      }
      if (q[1] === 0) o.updateWorldMatrix(true, false);
      const m = o.matrixWorld;
      const end = Math.min(count, q[1] + 500);
      for (let t = q[1]; t < end; t++) {
        const i0 = idx ? idx.getX(t * 3) : t * 3;
        const i1 = idx ? idx.getX(t * 3 + 1) : t * 3 + 1;
        const i2 = idx ? idx.getX(t * 3 + 2) : t * 3 + 2;
        _a.fromBufferAttribute(pos, i0).applyMatrix4(m);
        _b.fromBufferAttribute(pos, i1).applyMatrix4(m);
        _c.fromBufferAttribute(pos, i2).applyMatrix4(m);
        const ymax = Math.max(_a.y, _b.y, _c.y);
        // (floors, decks and paving at the ground: the camera is kept above them anyway)
        if (ymax < 0.6) {
          _v.subVectors(_b, _a).cross(_d.subVectors(_c, _a));
          if (Math.abs(_v.y) > 0.95 * _v.length()) continue;
        }
        this.push(_a, _b, _c);
      }
      q[1] = end;
      if (end >= count) this.queue.shift();
    }
  }

  push(a, b, c) {
    if ((this.n + 1) * 9 > this.tri.length) {
      const t = new Float32Array(this.tri.length * 2);
      t.set(this.tri);
      this.tri = t;
      const s = new Uint32Array(this.tri.length / 9);
      s.set(this.stamp);
      this.stamp = s;
    }
    const id = this.n++;
    this.tri.set([a.x, a.y, a.z, b.x, b.y, b.z, c.x, c.y, c.z], id * 9);
    const x0 = Math.floor(Math.min(a.x, b.x, c.x) / CELL), x1 = Math.floor(Math.max(a.x, b.x, c.x) / CELL);
    const y0 = Math.floor(Math.min(a.y, b.y, c.y) / CELL), y1 = Math.floor(Math.max(a.y, b.y, c.y) / CELL);
    const z0 = Math.floor(Math.min(a.z, b.z, c.z) / CELL), z1 = Math.floor(Math.max(a.z, b.z, c.z) / CELL);
    for (let x = x0; x <= x1; x++)
      for (let y = y0; y <= y1; y++)
        for (let z = z0; z <= z1; z++) {
          const k = key(x, y, z);
          let L = this.cells.get(k);
          if (!L) this.cells.set(k, (L = []));
          L.push(id);
        }
  }

  // how far along from -> to (0..1) the segment first meets a building face; faces within `skip`
  // metres of `from` (a door frame round your head) don't count
  block(from, to, skip = 0.4) {
    if (!this.n) return 1;
    const dx = to.x - from.x, dy = to.y - from.y, dz = to.z - from.z;
    const len = Math.hypot(dx, dy, dz);
    if (len < 1e-4) return 1;
    const t0 = skip / len;
    let best = 1;
    const stamp = ++this.tick;
    if (stamp === 0xffffffff) {
      this.stamp.fill(0);
      this.tick = 1;
    }
    const T = this.tri;
    // (the cells the segment passes through, Amanatides-Woo)
    let x = Math.floor(from.x / CELL), y = Math.floor(from.y / CELL), z = Math.floor(from.z / CELL);
    const ex = Math.floor(to.x / CELL), ey = Math.floor(to.y / CELL), ez = Math.floor(to.z / CELL);
    const sx = Math.sign(dx), sy = Math.sign(dy), sz = Math.sign(dz);
    const nxt = (p, s, c) => (s > 0 ? (c + 1) * CELL - p : p - c * CELL);
    let tx = sx ? nxt(from.x, sx, x) / Math.abs(dx) : Infinity, ty = sy ? nxt(from.y, sy, y) / Math.abs(dy) : Infinity, tz = sz ? nxt(from.z, sz, z) / Math.abs(dz) : Infinity;
    const ddx = sx ? CELL / Math.abs(dx) : Infinity, ddy = sy ? CELL / Math.abs(dy) : Infinity, ddz = sz ? CELL / Math.abs(dz) : Infinity;
    for (let step = 0; step < 64; step++) {
      const L = this.cells.get(key(x, y, z));
      if (L)
        for (let j = 0; j < L.length; j++) {
          const id = L[j];
          if (this.stamp[id] === stamp) continue;
          this.stamp[id] = stamp;
          const t = hit(T, id * 9, from, dx, dy, dz);
          if (t > t0 && t < best) best = t;
        }
      // (a hit inside this cell is nearer than anything in the cells after it)
      const cellEnd = Math.min(tx, ty, tz);
      if (best <= cellEnd || (x === ex && y === ey && z === ez) || cellEnd > 1) break;
      if (tx <= ty && tx <= tz) {
        x += sx;
        tx += ddx;
      } else if (ty <= tz) {
        y += sy;
        ty += ddy;
      } else {
        z += sz;
        tz += ddz;
      }
    }
    return best;
  }
}

const key = (x, y, z) => (x + 2048) * 16777216 + (y + 256) * 4096 + (z + 2048);

// Moller-Trumbore, both sides: the segment's parameter t (0..1 along d), or -1
function hit(T, o, p, dx, dy, dz) {
  const ax = T[o], ay = T[o + 1], az = T[o + 2];
  const e1x = T[o + 3] - ax, e1y = T[o + 4] - ay, e1z = T[o + 5] - az;
  const e2x = T[o + 6] - ax, e2y = T[o + 7] - ay, e2z = T[o + 8] - az;
  const px = dy * e2z - dz * e2y, py = dz * e2x - dx * e2z, pz = dx * e2y - dy * e2x;
  const det = e1x * px + e1y * py + e1z * pz;
  if (Math.abs(det) < 1e-9) return -1;
  const inv = 1 / det;
  const sx = p.x - ax, sy = p.y - ay, sz = p.z - az;
  const u = (sx * px + sy * py + sz * pz) * inv;
  if (u < 0 || u > 1) return -1;
  const qx = sy * e1z - sz * e1y, qy = sz * e1x - sx * e1z, qz = sx * e1y - sy * e1x;
  const v = (dx * qx + dy * qy + dz * qz) * inv;
  if (v < 0 || u + v > 1) return -1;
  return (e2x * qx + e2y * qy + e2z * qz) * inv;
}
