// The avatar hair look (hair round 2): every hair part carries, per vertex, what its shader needs to read
// as sculpted stylised hair instead of a dark tinted lump:
//   aHair  (u8 x4): x = hair (1) or not (0), y = root (0) -> tip (1), z = baked occlusion (grooves between
//                   locks, the undersides against the skull; 1 = open), w = a random value per lock / curl
//   aHairT (i8 x4): the strand direction (flowing out of the crown along the surface), in the part's frame
// worked out once per hair geometry from its shape (cached), then used by the characters material:
// a two-tone root -> tip gradient, the grooves, a fine strand grain, a two-lobe anisotropic sheen band
// (the halo ring round the head) and a soft rim. Same on every tier (all per vertex + a few ALU).
import * as THREE from "three";

const CROWN = new THREE.Vector3(0, 0.3, -0.03); // head frame: the whorl strands flow out of
const SK = new THREE.Vector3(0.348, 0.321, 0.335); // the skull ellipsoid (w13_style SK)
const cache = new WeakMap();

function hash(i) {
  let x = (i * 2654435761) >>> 0;
  x ^= x >>> 15;
  x = Math.imul(x, 2246822519) >>> 0;
  x ^= x >>> 13;
  return (x >>> 0) / 4294967296;
}

// the per-vertex data of one hair geometry, in its own (head) frame
function hairData(src) {
  if (cache.has(src)) return cache.get(src);
  const P = src.attributes.position;
  const N = src.attributes.normal;
  const n = P.count;
  const pos = new Float32Array(n * 3);
  const nor = new Float32Array(n * 3);
  for (let i = 0; i < n; i++) {
    pos[i * 3] = P.getX(i);
    pos[i * 3 + 1] = P.getY(i);
    pos[i * 3 + 2] = P.getZ(i);
    const nx = N.getX(i), ny = N.getY(i), nz = N.getZ(i);
    const l = Math.hypot(nx, ny, nz) || 1;
    nor[i * 3] = nx / l;
    nor[i * 3 + 1] = ny / l;
    nor[i * 3 + 2] = nz / l;
  }
  // locks: connected pieces (welding split seams by position), each its own random value
  const parent = new Int32Array(n).map((_, i) => i);
  const find = (i) => {
    while (parent[i] !== i) i = parent[i] = parent[parent[i]];
    return i;
  };
  const join = (a, b) => {
    a = find(a);
    b = find(b);
    if (a !== b) parent[a] = b;
  };
  const idx = src.index ? src.index.array : null;
  const tris = idx ? idx.length : n;
  for (let t = 0; t < tris; t += 3) {
    const a = idx ? idx[t] : t, b = idx ? idx[t + 1] : t + 1, c = idx ? idx[t + 2] : t + 2;
    join(a, b);
    join(a, c);
  }
  const weld = new Map();
  const rep = new Int32Array(n);
  for (let i = 0; i < n; i++) {
    const k = `${Math.round(pos[i * 3] * 2e4)},${Math.round(pos[i * 3 + 1] * 2e4)},${Math.round(pos[i * 3 + 2] * 2e4)}`;
    const w = weld.get(k);
    if (w === undefined) weld.set(k, (rep[i] = i));
    else {
      rep[i] = w;
      join(i, w);
    }
  }
  // smooth normals across the export's split edges: the decimated locks keep no hard facets (area-weighted)
  const acc = new Float64Array(n * 3);
  for (let t = 0; t < tris; t += 3) {
    const a = idx ? idx[t] : t, b = idx ? idx[t + 1] : t + 1, c = idx ? idx[t + 2] : t + 2;
    const ux = pos[b * 3] - pos[a * 3], uy = pos[b * 3 + 1] - pos[a * 3 + 1], uz = pos[b * 3 + 2] - pos[a * 3 + 2];
    const vx = pos[c * 3] - pos[a * 3], vy = pos[c * 3 + 1] - pos[a * 3 + 1], vz = pos[c * 3 + 2] - pos[a * 3 + 2];
    const fx = uy * vz - uz * vy, fy = uz * vx - ux * vz, fz = ux * vy - uy * vx;
    for (const v of [a, b, c]) {
      const r = rep[v] * 3;
      acc[r] += fx;
      acc[r + 1] += fy;
      acc[r + 2] += fz;
    }
  }
  for (let i = 0; i < n; i++) {
    const r = rep[i] * 3;
    const l = Math.hypot(acc[r], acc[r + 1], acc[r + 2]);
    // (a thin lock's two faces welded at its rim cancel out: that vertex keeps its own normal)
    if (l < 1e-9) continue;
    const nx = acc[r] / l, ny = acc[r + 1] / l, nz = acc[r + 2] / l;
    if (nx * nor[i * 3] + ny * nor[i * 3 + 1] + nz * nor[i * 3 + 2] < 0.2) continue;
    nor[i * 3] = nx;
    nor[i * 3 + 1] = ny;
    nor[i * 3 + 2] = nz;
  }
  // root -> tip: distance from the crown, over the furthest reach of this hair
  let dmax = 0.2;
  for (let i = 0; i < n; i++) dmax = Math.max(dmax, Math.hypot(pos[i * 3] - CROWN.x, pos[i * 3 + 1] - CROWN.y, pos[i * 3 + 2] - CROWN.z));
  // occlusion: how much of each vertex's open hemisphere other hair fills (a point-cloud estimate on a grid)
  const R = 0.055;
  const grid = new Map();
  const cell = (x) => Math.floor(x / R);
  for (let i = 0; i < n; i++) {
    const k = cell(pos[i * 3]) + "," + cell(pos[i * 3 + 1]) + "," + cell(pos[i * 3 + 2]);
    let a = grid.get(k);
    if (!a) grid.set(k, (a = []));
    a.push(i);
  }
  const hair = new Uint8Array(n * 4);
  const tan = new Int8Array(n * 4);
  const v = new THREE.Vector3(), nn = new THREE.Vector3(), f = new THREE.Vector3(), q = new THREE.Vector3();
  for (let i = 0; i < n; i++) {
    const px = pos[i * 3], py = pos[i * 3 + 1], pz = pos[i * 3 + 2];
    nn.set(nor[i * 3], nor[i * 3 + 1], nor[i * 3 + 2]);
    let occ = 0, tot = 0;
    const cx = cell(px), cy = cell(py), cz = cell(pz);
    for (let a = -1; a <= 1; a++)
      for (let b = -1; b <= 1; b++)
        for (let c = -1; c <= 1; c++) {
          const list = grid.get(cx + a + "," + (cy + b) + "," + (cz + c));
          if (!list) continue;
          for (const j of list) {
            const dx = pos[j * 3] - px, dy = pos[j * 3 + 1] - py, dz = pos[j * 3 + 2] - pz;
            const d = Math.hypot(dx, dy, dz);
            if (d < 1e-4 || d > R) continue;
            const w = 1 - d / R;
            tot += w;
            const cs = (nn.x * dx + nn.y * dy + nn.z * dz) / d;
            if (cs > 0.15) occ += w * (cs - 0.15) / 0.85;
          }
        }
    let ao = 1 - Math.min(1, (tot ? occ / tot : 0) * 2.4);
    // faces turned in against the skull sit in its shadow
    q.set(px / SK.x, py / SK.y, pz / SK.z);
    const inward = nn.dot(v.set(px, py, pz).normalize());
    const near = Math.max(0, 1 - (q.length() - 1) * 6);
    ao *= 1 - 0.55 * near * Math.min(1, Math.max(0, (0.2 - inward) / 0.9));
    // the strand direction: away from the crown, laid along the surface (hanging straight down when that fails)
    f.set(px - CROWN.x, py - CROWN.y, pz - CROWN.z);
    f.y -= 0.35 * Math.max(0, -py) ; // (below the head, hair falls)
    f.addScaledVector(nn, -f.dot(nn));
    if (f.lengthSq() < 1e-8) f.set(0, -1, 0).addScaledVector(nn, -nn.y);
    f.normalize();
    const t = Math.hypot(px - CROWN.x, py - CROWN.y, pz - CROWN.z) / dmax;
    hair[i * 4] = 255;
    hair[i * 4 + 1] = Math.round(Math.min(1, Math.max(0, t)) * 255);
    hair[i * 4 + 2] = Math.round(Math.max(0, ao) * 255);
    hair[i * 4 + 3] = Math.round(hash(find(i) + 7) * 255);
    tan[i * 4] = Math.round(f.x * 127);
    tan[i * 4 + 1] = Math.round(f.y * 127);
    tan[i * 4 + 2] = Math.round(f.z * 127);
  }
  const out = { hair, tan, nor };
  cache.set(src, out);
  return out;
}

const _m3 = new THREE.Matrix3();
const _t = new THREE.Vector3();
// the two hair attributes for one part (src: the GLB geometry; m: its matrix into the rig's rest space)
export function hairAttributes(g, src, isHair, m) {
  const n = g.attributes.position.count;
  if (!isHair) {
    g.setAttribute("aHair", new THREE.Uint8BufferAttribute(new Uint8Array(n * 4), 4, true));
    g.setAttribute("aHairT", new THREE.Int8BufferAttribute(new Int8Array(n * 4), 4, true));
    return;
  }
  const d = hairData(src);
  const tan = new Int8Array(n * 4);
  _m3.setFromMatrix4(m);
  for (let i = 0; i < n; i++) {
    _t.set(d.tan[i * 4], d.tan[i * 4 + 1], d.tan[i * 4 + 2]).applyMatrix3(_m3).normalize();
    tan[i * 4] = Math.round(_t.x * 127);
    tan[i * 4 + 1] = Math.round(_t.y * 127);
    tan[i * 4 + 2] = Math.round(_t.z * 127);
  }
  const nrm = g.attributes.normal;
  for (let i = 0; i < n; i++) {
    _t.set(d.nor[i * 3], d.nor[i * 3 + 1], d.nor[i * 3 + 2]).applyMatrix3(_m3).normalize();
    nrm.setXYZ(i, _t.x, _t.y, _t.z);
  }
  g.setAttribute("aHair", new THREE.Uint8BufferAttribute(d.hair.slice(), 4, true));
  g.setAttribute("aHairT", new THREE.Int8BufferAttribute(tan, 4, true));
}

// ---- the shader (added to the characters material in onBeforeCompile) ----
export const HAIR_VERT_PARS = `
attribute vec4 aHair;
attribute vec4 aHairT;
varying vec4 vHair;
varying vec3 vHairT;
varying vec3 vHairP;
varying vec3 vHairTo;`;
// (after skinning_vertex: the strand direction skinned like the normal, into view space)
export const HAIR_VERT = `
vHair = aHair;
vHairP = position;
vHairTo = aHairT.xyz;
{ vec3 ht = aHairT.xyz;
#ifdef USE_SKINNING
  ht = (skinMatrix * vec4(ht, 0.0)).xyz;
#endif
  vHairT = (modelViewMatrix * vec4(ht, 0.0)).xyz; }`;
export const HAIR_FRAG_PARS = `
varying vec4 vHair;
varying vec3 vHairT;
varying vec3 vHairP;
varying vec3 vHairTo;
float hairHash(vec3 p) { p = fract(p * 0.3183099 + 0.1); p *= 17.0; return fract(p.x * p.y * p.z * (p.x + p.y + p.z)); }
float hairNoise(vec3 x) {
  vec3 i = floor(x); vec3 f = fract(x); f = f * f * (3.0 - 2.0 * f);
  return mix(mix(mix(hairHash(i), hairHash(i + vec3(1, 0, 0)), f.x), mix(hairHash(i + vec3(0, 1, 0)), hairHash(i + vec3(1, 1, 0)), f.x), f.y),
             mix(mix(hairHash(i + vec3(0, 0, 1)), hairHash(i + vec3(1, 0, 1)), f.x), mix(hairHash(i + vec3(0, 1, 1)), hairHash(i + vec3(1, 1, 1)), f.x), f.y), f.z);
}
// strand grain: noise stretched along the strand, fine across it
float hairGrain() {
  vec3 to = normalize(vHairTo + 1e-4);
  float along = dot(vHairP, to);
  vec3 across = vHairP - to * along;
  return hairNoise(across * 140.0 + to * along * 9.0) * 0.6 + hairNoise(across * 55.0 + 3.1) * 0.4;
}
vec3 hairBase;
float hairOn;
vec3 hairKm;`;
// (after map_fragment and the tints: the hair's own albedo)
export const HAIR_ALBEDO = `
hairOn = step(0.5, vHair.x);
hairBase = diffuseColor.rgb;
if (hairOn > 0.5) {
  // the hair's own colour from its tint channels (the mask says which shade; an untinted texel, a tiny chart
  // reading its neighbour, takes the hair tint): the atlas only adds a little of its baked shading, so the bake's
  // dense lock-on-lock occlusion never turns the hair into a dark mass (the grooves are shaded below, per vertex)
  // (only the channels this hair really uses count: a texel reading a neighbour's channel never goes white)
  float lA = dot(vTintR, vec3(1.0)), lB = dot(vTintG, vec3(1.0)), lC = dot(vTintB, vec3(1.0));
  vec3 kw = hairKm * vec3(step(lA, 2.99), step(lB, 2.99), step(lC, 2.99));
  float ks = kw.x + kw.y + kw.z;
  vec3 tint = ks > 0.5 ? (vTintR * kw.x + vTintG * kw.y + vTintB * kw.z) / ks
                       : (lA < lB ? (lA < lC ? vTintR : vTintB) : (lB < lC ? vTintG : vTintB));
  float texL = dot(texture2D(map, vMapUv).rgb, vec3(0.2126, 0.7152, 0.0722));
  diffuseColor.rgb = tint * mix(1.0, clamp(texL * 1.25, 0.0, 1.0), 0.3);
  vec3 c = diffuseColor.rgb;
  float l = dot(c, vec3(0.2126, 0.7152, 0.0722));
  // (stylised value range: the darkest hair still shows its shapes)
  c *= mix(1.0, 0.05 / max(l, 1e-4), smoothstep(0.05, 0.004, l) * 0.8);
  hairBase = c;
  float tip = smoothstep(0.08, 0.95, vHair.y);
  float lk = vHair.w - 0.5;
  // two-tone: deeper, a touch richer at the root, lighter and warmer towards the tips, each lock its own shade
  vec3 root = c * vec3(0.62, 0.6, 0.66);
  float lift = mix(1.0, 0.55, smoothstep(0.15, 0.6, l));      // (light hair: a gentler lift, the tips never wash out)
  vec3 tipc = c * (vec3(1.0) + vec3(0.32, 0.26, 0.16) * lift) + vec3(0.012, 0.009, 0.006) * lift;
  c = mix(root, tipc, tip) * (1.0 + lk * 0.16);
  // the grooves between locks: darker and more saturated
  float ao = vHair.z;
  vec3 deep = c * c / max(dot(c, vec3(0.333)), 1e-4);
  c = mix(mix(c, deep, 0.5) * 0.4, c, smoothstep(0.0, 0.75, ao));
  c *= 0.86 + 0.28 * hairGrain();
  diffuseColor.rgb = c;
}`;
// (before opaque_fragment: the sheen band and the rim on top of the lit hair)
export const HAIR_LIGHT = `
if (hairOn > 0.5) {
  vec3 Nh = normalize(normal);
  vec3 Vh = normalize(vViewPosition);
  vec3 Lh = normalize(vec3(0.25, 0.9, 0.35));
#if NUM_DIR_LIGHTS > 0
  Lh = directionalLights[0].direction;
#endif
  // how lit this point is (shadows included): its direct diffuse over its albedo
  // how much sky / ambient light there is (night: little): the camera-side sheen, the fill and the rim follow it,
  // so they never draw light lines along the lock edges in the dark
  float amb = clamp(dot(reflectedLight.indirectDiffuse, vec3(0.333)) / max(dot(diffuseColor.rgb, vec3(0.333)) * RECIPROCAL_PI, 1e-3) / 1.6, 0.0, 1.0);
  float lit = clamp(dot(reflectedLight.directDiffuse, vec3(0.333)) / max(dot(diffuseColor.rgb, vec3(0.333)) * RECIPROCAL_PI, 1e-3) / 3.0, 0.0, 1.0);
  vec3 T = vHairT - Nh * dot(vHairT, Nh);
  T = dot(T, T) > 1e-6 ? normalize(T) : vec3(0.0, 1.0, 0.0);
  float g = hairGrain();
  float sh = (g - 0.5) * 0.22 + (vHair.w - 0.5) * 0.12;
  // two lobes (Kajiya-Kay with shifted tangents): a crisp pale band and a wider tinted one under it
  vec3 Hh = normalize(Lh + Vh);
  vec3 T1 = normalize(T + Nh * (sh - 0.06));
  vec3 T2 = normalize(T + Nh * (sh + 0.16));
  float d1 = dot(T1, Hh), d2 = dot(T2, Hh);
  float s1 = sqrt(max(0.0, 1.0 - d1 * d1)), s2 = sqrt(max(0.0, 1.0 - d2 * d2));
  float face = smoothstep(-0.05, 0.35, dot(Nh, Lh)) * smoothstep(0.0, 0.25, dot(Nh, Vh));
  float b1 = pow(s1, 36.0) * face;                      // (satin: a broad soft band, not a mirror streak)
  float b2 = pow(s2, 18.0) * face;
  float hl = dot(hairBase, vec3(0.2126, 0.7152, 0.0722));
  vec3 c1 = mix(vec3(1.0, 0.97, 0.93), normalize(hairBase + 1e-3) * 1.2, 0.6) * mix(0.16, 0.3, smoothstep(0.02, 0.4, hl));
  vec3 c2 = hairBase * 1.6 + vec3(0.02);
  float occ = smoothstep(0.15, 0.9, vHair.z) * (0.35 + 0.65 * lit);
  outgoingLight += (c1 * b1 * (0.6 + 0.4 * g) + c2 * b2 * 0.2) * occ;
  // the halo ring also from the camera side (a soft sky key from above the viewer): a face-on or backlit head
  // still shows its sheen band instead of a muddy mass
  vec3 Hv = normalize(Vh + vec3(0.0, 0.55, 0.0));
  vec3 T3 = normalize(T + Nh * (sh + 0.02));
  float d3 = dot(T3, Hv);
  float b3 = pow(sqrt(max(0.0, 1.0 - d3 * d3)), 30.0) * smoothstep(0.0, 0.3, dot(Nh, Vh));
  outgoingLight += c1 * b3 * (0.5 + 0.5 * g) * 0.35 * smoothstep(0.15, 0.9, vHair.z) * (1.0 - 0.6 * lit) * amb;
  // a soft sky fill on the upper faces and a rim catching the sky
  outgoingLight += hairBase * 0.16 * smoothstep(-0.2, 0.8, Nh.y) * smoothstep(0.1, 0.8, vHair.z) * amb;
  float rim = pow(1.0 - clamp(dot(Nh, Vh), 0.0, 1.0), 2.6) * smoothstep(-0.3, 0.6, Nh.y);
  // (the rim only on open, upward faces; lock edges inside the hair sit in occlusion and get none)
  outgoingLight += hairBase * rim * 0.18 * smoothstep(0.55, 0.95, vHair.z) * amb;
}`;
